export default " cache_position=cache_position,\\n            **kwargs,\\n        )\\n\\n    bsz, q_len, _ = hidden_states.size()\\n\\n    query_states: torch.Tensor = self.q_proj(hidden_states)\\n    key_states: torch.Tensor = self.k_proj(hidden_states)\\n    value_states: torch.Tensor = self.v_proj(hidden_states)\\n\\n    query_states = query_states.view(bsz, q_len, self.num_heads, self.head_dim).transpose(1, 2)\\n    key_states = key_states.view(bsz, q_len, self.num_key_value_heads, self.head_dim).transpose(1, 2)\\n    value_states = value_states.view(bsz, q_len, self.num_key_value_heads, self.head_dim).transpose(1, 2)\\n\\n    if position_embeddings is None:\\n        cos, sin = self.rotary_emb(value_states, position_ids)\\n    else:\\n        cos, sin = position_embeddings\\n\\n    query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)\\n\\n    if past_key_value is not None:\\n        cache_kwargs = {\\\"sin\\\": sin, \\\"cos\\\": cos, \\\"cache_position\\\": cache_position}\\n        key_states, value_states = past_key_value.update(key_states, value_states, self.layer_idx, cache_kwargs)\\n\\n    key_states = repeat_kv(key_states, self.num_key_value_groups)\\n    value_states = repeat_kv(value_states, self.num_key_value_groups)\\n\\n    if getattr(self.config, \\\"group_size_ratio\\\", None) and self.training:  # shift\\n        groupsz = int(q_len * getattr(self.config, \\\"group_size_ratio\\\"))\\n        assert q_len % groupsz == 0, f\\\"q_len {q_len} should be divisible by group size {groupsz}.\\\"\\n        num_groups = q_len // groupsz\\n\\n        def shift(state: \\\"torch.Tensor\\\") -> \\\"torch.Tensor\\\":\\n            state = state.transpose(1, 2)  # output: (bsz, seq_len, n_heads, head_dim)\\n            state = torch.cat(\\n                (state[:, :, : self.num_heads // 2], state[:, :, self.num_heads // 2 :].roll(-groupsz // 2, dims=1)),\\n                dim=2,\\n            )\\n            return state.reshape(bsz * num_groups, groupsz, self.num_heads, self.head_dim).transpose(1, 2)\\n\\n        query_states, key_states, value_states = shift(query_states), shift(key_states), shift(value_states)\\n        if attention_mask is not None:\\n            attention_mask = attention_mask[:, :, :groupsz, :groupsz].repeat(num_groups, 1, 1, 1)\\n\\n    causal_mask = attention_mask\\n    if attention_mask is not None:\\n        causal_mask = causal_mask[:, :, :, : key_states.shape[-2]]\\n\\n    if query_states.device.type == \\\"cuda\\\" and causal_mask is not None:  # avoid pytorch bug\\n        query_states = query_states.contiguous()\\n        key_states = key_states.contiguous()\\n        value_states = value_states.contiguous()\\n\\n    is_causal = True if causal_mask is None and q_len > 1 else False\\n    attn_output = torch.nn.functional.scaled_dot_product_attention(\\n        query_states,\\n        key_states,\\n        value_states,\\n        attn_mask=causal_mask,\\n        dropout_p=self.attention_dropout if self.training else 0.0,\\n        is_causal=is_causal,\\n    )\\n    attn_output = attn_output.transpose(1, 2).contiguous()\\n\\n    if getattr(self.config, \\\"group_size_ratio\\\", None) and self.training:  # shift back\\n        attn_output.reshape(bsz, q_len, self.num_heads, self.head_dim)\\n        attn_output = torch.cat(\\n            (\\n                attn_output[:, :, : self.num_heads // 2],\\n                attn_output[:, :, self.num_heads // 2 :].roll(groupsz // 2, dims=1),\\n            ),\\n            dim=2,\\n        )\\n\\n    attn_output = attn_output.reshape(bsz, q_len, self.hidden_size)\\n    attn_output = self.o_proj(attn_output)\\n\\n    return attn_output, None, past_key_value\\n\\n\\ndef _apply_llama_patch() -> None:\\n    check_version(\\\"transformers>=4.45.0,<4.48.0\\\", mandatory=True)\\n    LlamaAttention.forward = llama_attention_forward\\n    LlamaFlashAttention2.forward = llama_flash_attention_2_forward\\n    LlamaSdpaAttention.forward = llama_sdpa_attention_forward\\n\\n\\ndef configure_longlora(config: \\\"PretrainedConfig\\\", model_args: \\\"ModelArguments\\\", is_trainable: bool) -> None:\\n    if not is_trainable or not model_args.shift_attn:\\n        return\\n\\n    logger = logging.get_logger(__name__)\\n\\n    if getattr(config, \\\"model_type\\\", None) in SUPPORTED_CLASS_FOR_S2ATTN:\\n        setattr(config, \\\"group_size_ratio\\\", 0.25)\\n        _apply_llama_patch()\\n        logger.info_rank0(\\\"Using shift short attention with group_size_ratio=1/4.\\\")\\n    else:\\n        logger.warning_rank0(\\\"Current model does not support shift short attention.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/misc.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ea42f46b3b39a53be80b258e48feeab3346bb71459adf406dfcd5e60645c4a13\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom ...extras import logging\\nfrom .visual import COMPOSITE_MODELS\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PretrainedConfig, PreTrainedModel, PreTrainedTokenizer\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef find_all_linear_modules(model: \\\"PreTrainedModel\\\", freeze_vision_tower: bool) -> list[str]:\\n    r\\\"\\\"\\\"Find all available modules to apply LoRA, GaLore or APOLLO.\\\"\\\"\\\"\\n    model_type = getattr(model.config, \\\"model_type\\\", None)\\n    forbidden_modules = {\\\"lm_head\\\"}\\n    if model_type == \\\"chatglm\\\":\\n        forbidden_modules.add(\\\"output_layer\\\")\\n    elif model_type == \\\"internlm2\\\":\\n        forbidden_modules.add(\\\"output\\\")\\n\\n    if model_type in COMPOSITE_MODELS:\\n        forbidden_modules.update(COMPOSITE_MODELS[model_type].projector_keys)\\n\\n    if freeze_vision_tower and model_type in COMPOSITE_MODELS:\\n        forbidden_modules.update(COMPOSITE_MODELS[model_type].vision_model_keys)\\n\\n    module_names = set()\\n    for name, module in model.named_modules():\\n        if any(forbidden_module in name for forbidden_module in forbidden_modules):\\n            continue\\n\\n        if \\\"Linear\\\" in module.__class__.__name__ and \\\"Embedding\\\" not in module.__class__.__name__:\\n            module_names.add(name.split(\\\".\\\")[-1])\\n\\n    logger.info_rank0(\\\"Found linear modules: {}\\\".format(\\\",\\\".join(module_names)))\\n    return list(module_names)\\n\\n\\ndef find_expanded_modules(model: \\\"PreTrainedModel\\\", target_modules: list[str], num_layer_trainable: int) -> list[str]:\\n    r\\\"\\\"\\\"Find the modules in the expanded blocks to apply lora.\\\"\\\"\\\"\\n    num_layers = getattr(model.config, \\\"num_hidden_layers\\\", None)\\n    if not num_layers:\\n        raise ValueError(\\\"Model was not supported.\\\")\\n\\n    if num_layers % num_layer_trainable != 0:\\n        raise ValueError(\\n            f\\\"`num_layers` {num_layers} should be divisible by `num_layer_trainable` {num_layer_trainable}.\\\"\\n        )\\n\\n    stride = num_layers // num_layer_trainable\\n    trainable_layer_ids = range(stride - 1, num_layers + stride - 1, stride)\\n    trainable_layers = [f\\\".{idx:d}.\\\" for idx in trainable_layer_ids]\\n    module_names = []\\n    for name, _ in model.named_modules():\\n        if any(target_module in name for target_module in target_modules) and any(\\n            trainable_layer in name for trainable_layer in trainable_layers\\n        ):\\n            module_names.append(name)\\n\\n    logger.info_rank0(\\\"Apply lora to layers: {}.\\\".format(\\\",\\\".join(map(str, trainable_layer_ids))))\\n    return module_names\\n\\n\\ndef register_autoclass(config: \\\"PretrainedConfig\\\", model: \\\"PreTrainedModel\\\", tokenizer: \\\"PreTrainedTokenizer\\\"):\\n    if \\\"AutoConfig\\\" in getattr(config, \\\"auto_map\\\", {}):\\n        config.__class__.register_for_auto_class()\\n    if \\\"AutoModelForCausalLM\\\" in getattr(config, \\\"auto_map\\\", {}):\\n        model.__class__.register_for_auto_class()\\n    if \\\"AutoTokenizer\\\" in tokenizer.init_kwargs.get(\\\"auto_map\\\", {}):\\n        tokenizer.__class__.register_for_auto_class()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/mod.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"675e96990dd09995a7540f60f12a3a51cb3b57c7f97cdf9a05902d9c2f5aca36\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING\\n\\nfrom ...extras.constants import MOD_SUPPORTED_MODELS\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PretrainedConfig, PreTrainedModel\\n\\n    from ...hparams import ModelArguments\\n\\n\\ndef load_mod_pretrained_model(**init_kwargs) -> \\\"PreTrainedModel\\\":\\n    from MoD import AutoMoDModelForCausalLM\\n\\n    return AutoMoDModelForCausalLM.from_pretrained(**init_kwargs)\\n\\n\\ndef convert_pretrained_model_to_mod(\\n    model: \\\"PreTrainedModel\\\", config: \\\"PretrainedConfig\\\", model_args: \\\"ModelArguments\\\"\\n) -> \\\"PreTrainedModel\\\":\\n    from MoD import apply_mod_to_hf\\n\\n    if getattr(config, \\\"model_type\\\", None) not in MOD_SUPPORTED_MODELS:\\n        raise ValueError(\\\"Current model is not supported by mixture-of-depth.\\\")\\n\\n    model = apply_mod_to_hf(model)\\n    model = model.to(model_args.compute_dtype)\\n    return model\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/moe.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"84ceefe1ae0cf6305aacb6d45a574f65dd0d116b5ee0d207379695ec2ab1c03d\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Union\\n\\nimport torch\\nfrom torch import nn\\nfrom torch.nn import functional as F\\nfrom transformers.integrations import is_deepspeed_zero3_enabled\\n\\nfrom ...extras.misc import check_version\\nfrom ...extras.packages import is_transformers_version_greater_than\\n\\n\\nif TYPE_CHECKING:\\n    from torch import nn\\n    from transformers import PretrainedConfig, PreTrainedModel\\n\\n    from ...hparams import ModelArguments\\n\\nif is_transformers_version_greater_than(\\\"4.57.0\\\"):\\n    from transformers.models.qwen3_omni_moe import modeling_qwen3_omni_moe\\n\\n\\ndef _set_z3_leaf_modules(model: \\\"PreTrainedModel\\\", leaf_modules: list[Union[\\\"nn.Module\\\", str]]) -> None:\\n    check_version(\\\"deepspeed>=0.13.0\\\")\\n    from deepspeed.utils import set_z3_leaf_modules  # type: ignore\\n\\n    set_z3_leaf_modules(model, leaf_modules)\\n\\n\\ndef add_z3_leaf_module(model: \\\"PreTrainedModel\\\") -> None:\\n    r\\\"\\\"\\\"Set module as a leaf module to skip partitioning in deepspeed zero3.\\\"\\\"\\\"\\n    if not is_deepspeed_zero3_enabled():\\n        return\\n\\n    model_type = getattr(model.config, \\\"model_type\\\", None)\\n    text_config = getattr(model.config, \\\"text_config\\\", None)\\n    text_model_type = getattr(text_config, \\\"model_type\\\", None)\\n\\n    if model_type == \\\"dbrx\\\":\\n        from transformers.models.dbrx.modeling_dbrx import DbrxFFN\\n\\n        _set_z3_leaf_modules(model, [DbrxFFN])\\n\\n    if model_type == \\\"deepseek_v2\\\":\\n        # deepseek v2 uses custom code\\n        _set_z3_leaf_modules(model, [\\\"DeepseekV2MoE\\\"])\\n\\n    if model_type == \\\"deepseek_v3\\\" or model_type == \\\"kimi_vl\\\":\\n        # deepseek v3 and kimi vl use custom code\\n        _set_z3_leaf_modules(model, [\\\"DeepseekV3MoE\\\"])\\n\\n    if model_type == \\\"hy_v3\\\":\\n        # hy3 uses custom code\\n        _set_z3_leaf_modules(model, [\\\"HYV3MoE\\\"])\\n\\n    if model_type == \\\"ernie4_5_moe\\\":\\n        from transformers.models.ernie4_5_moe.modeling_ernie4_5_moe import Ernie4_5_MoeSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [Ernie4_5_MoeSparseMoeBlock])\\n\\n    if model_type == \\\"granitemoe\\\":\\n        from transformers.models.granitemoe.modeling_granitemoe import GraniteMoeMoE\\n\\n        _set_z3_leaf_modules(model, [GraniteMoeMoE])\\n\\n    if model_type == \\\"glm4_moe\\\":\\n        from transformers.models.glm4_moe.modeling_glm4_moe import Glm4MoeMoE\\n\\n        _set_z3_leaf_modules(model, [Glm4MoeMoE])\\n\\n    if model_type == \\\"glm4_moe_lite\\\":\\n        from transformers.models.glm4_moe_lite.modeling_glm4_moe_lite import Glm4MoeLiteMoE\\n\\n        _set_z3_leaf_modules(model, [Glm4MoeLiteMoE])\\n\\n    if model_type == \\\"glm4v_moe\\\":\\n        from transformers.models.glm4v_moe.modeling_glm4v_moe import Glm4vMoeTextMoE\\n\\n        _set_z3_leaf_modules(model, [Glm4vMoeTextMoE])\\n\\n    if model_type == \\\"gpt_oss\\\":\\n        from transformers.models.gpt_oss.modeling_gpt_oss import GptOssMLP\\n\\n        _set_z3_leaf_modules(model, [GptOssMLP])\\n\\n    if model_type == \\\"jamba\\\":\\n        from transformers.models.jamba.modeling_jamba import JambaSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [JambaSparseMoeBlock])\\n\\n    if model_type == \\\"jetmoe\\\":\\n        from transformers.models.jetmoe.modeling_jetmoe import JetMoeMoA, JetMoeMoE\\n\\n        _set_z3_leaf_modules(model, [JetMoeMoA, JetMoeMoE])\\n\\n    if model_type == \\\"llama4\\\":\\n        from transformers.models.llama4.modeling_llama4 import Llama4TextMoe\\n\\n        _set_z3_leaf_modules(model, [Llama4TextMoe])\\n\\n    if model_type == \\\"mixtral\\\":\\n        from transformers.models.mixtral.modeling_mixtral import MixtralSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [MixtralSparseMoeBlock])\\n\\n    if model_type == \\\"olmoe\\\":\\n        from transformers.models.olmoe.modeling_olmoe import OlmoeSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [OlmoeSparseMoeBlock])\\n\\n    if model_type == \\\"phimoe\\\":\\n        from transformers.models.phimoe.modeling_phimoe import PhimoeSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [PhimoeSparseMoeBlock])\\n\\n    if model_type == \\\"qwen2_moe\\\":\\n        from transformers.models.qwen2_moe.modeling_qwen2_moe import Qwen2MoeSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [Qwen2MoeSparseMoeBlock])\\n\\n    if model_type == \\\"qwen3_moe\\\" or text_model_type == \\\"qwen3_moe\\\":  # internvl 3.5\\n        from transformers.models.qwen3_moe.modeling_qwen3_moe import Qwen3MoeSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [Qwen3MoeSparseMoeBlock])\\n\\n    if model_type == \\\"qwen3_vl_moe\\\":\\n        from transformers.models.qwen3_vl_moe.modeling_qwen3_vl_moe import Qwen3VLMoeTextSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [Qwen3VLMoeTextSparseMoeBlock])\\n\\n    if model_type in (\\\"qwen3_omni_moe\\\", \\\"qwen3_omni_moe_thinker\\\"):\\n        from transformers.models.qwen3_omni_moe.modeling_qwen3_omni_moe import Qwen3OmniMoeThinkerTextSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [Qwen3OmniMoeThinkerTextSparseMoeBlock])\\n\\n    if model_type == \\\"qwen3_next\\\":\\n        from transformers.models.qwen3_next.modeling_qwen3_next import Qwen3NextSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [Qwen3NextSparseMoeBlock])\\n\\n    if model_type in (\\\"qwen3_5_moe\\\", \\\"qwen3_5_moe_text\\\"):\\n        from transformers.models.qwen3_5_moe.modeling_qwen3_5_moe import Qwen3_5MoeSparseMoeBlock\\n\\n        _set_z3_leaf_modules(model, [Qwen3_5MoeSparseMoeBlock])\\n\\n\\ndef configure_moe(config: \\\"PretrainedConfig\\\", model_args: \\\"ModelArguments\\\", is_trainable: bool) -> None:\\n    if not is_trainable or not model_args.moe_aux_loss_coef:\\n        return\\n\\n    model_type = getattr(config, \\\"model_type\\\", None)\\n    text_config = getattr(config, \\\"text_config\\\", None)  # for multimodal model\\n\\n    if model_type in [\\n        \\\"dbrx\\\",\\n        \\\"ernie4_5_moe\\\",\\n        \\\"granitemoe\\\",\\n        \\\"jamba\\\",\\n        \\\"jetmoe\\\",\\n        \\\"llama4\\\",\\n        \\\"mixtral\\\",\\n        \\\"olmoe\\\",\\n        \\\"phimoe\\\",\\n        \\\"qwen2_moe\\\",\\n        \\\"qwen3_moe\\\",\\n    ]:\\n        setattr(config, \\\"output_router_logits\\\", True)\\n\\n    if text_config and getattr(text_config, \\\"model_type\\\", None) in [\\n        \\\"glm4v_moe_text\\\",  # glmv4_5\\n        \\\"qwen3_moe\\\",  # internvl_3_5\\n    ]:\\n        setattr(text_config, \\\"output_router_logits\\\", True)\\n\\n    if model_type in [\\n        \\\"ernie4_5_moe\\\",\\n        \\\"granitemoe\\\",\\n        \\\"jamba\\\",\\n        \\\"llama4\\\",\\n        \\\"mixtral\\\",\\n        \\\"olmoe\\\",\\n        \\\"phimoe\\\",\\n        \\\"qwen2_moe\\\",\\n        \\\"qwen3_moe\\\",\\n    ]:\\n        setattr(config, \\\"router_aux_loss_coef\\\", model_args.moe_aux_loss_coef)\\n\\n    elif text_config and getattr(text_config, \\\"model_type\\\", None) in [\\\"qwen3_moe\\\"]:\\n        setattr(text_config, \\\"router_aux_loss_coef\\\", model_args.moe_aux_loss_coef)\\n\\n    elif model_type == \\\"deepseek\\\":\\n        setattr(config, \\\"aux_loss_alpha\\\", model_args.moe_aux_loss_coef)\\n\\n    elif model_type == \\\"jetmoe\\\":\\n        setattr(config, \\\"aux_loss_coef\\\", model_args.moe_aux_loss_coef)\\n\\n\\nclass Qwen3OmniMoeThinkerTextSparseMoeBlock(nn.Module):\\n    def __init__(self, config):\\n        super().__init__()\\n        self.num_experts = config.num_experts\\n        self.top_k = config.num_experts_per_tok\\n        self.norm_topk_prob = config.norm_topk_prob\\n\\n        # gating\\n        self.gate = nn.Linear(config.hidden_size, config.num_experts, bias=False)\\n        self.experts = nn.ModuleList(\\n            [\\n                modeling_qwen3_omni_moe.Qwen3OmniMoeThinkerTextMLP(\\n                    config, intermediate_size=config.moe_intermediate_size\\n                )\\n                for _ in range(self.num_experts)\\n            ]\\n        )\\n\\n    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:\\n        batch_size, sequence_length, hidden_dim = hidden_states.shape\\n        hidden_states = hidden_states.view(-1, hidden_dim)\\n        # router_logits: (batch * sequence_length, n_experts)\\n        router_logits = self.gate(hidden_states)\\n\\n        # Calculate the routing weights for all experts\\n        routing_weights = F.softmax(router_logits, dim=1, dtype=torch.float)\\n\\n        # Retain the weight of the top_k and reset the rest of the expert rights to 0 (instead of retaining only top_k experts)\\n        top_k_weights, top_k_indices = torch.topk(routing_weights, self.top_k, dim=-1)\\n        # Initialize the all-zero weight matrix (same shape as all experts)\\n        full_routing_weights = torch.zeros_like(routing_weights)\\n        # Only the weight of top_k experts is retained, and the weight of the rest of the experts remains at 0\\n        full_routing_weights.scatter_(1, top_k_indices, top_k_weights)\\n\\n        # Normalized top_k weights (keep the original logic consistent)\\n        if self.norm_topk_prob:\\n            # Calculate the sum of the weights top_k each row (for normalization)\\n            top_k_sum = full_routing_weights.sum(dim=-1, keepdim=True)\\n            # Avoid dividing by zero\\n            top_k_sum = torch.clamp(top_k_sum, min=1e-9)\\n            full_routing_weights /= top_k_sum\\n\\n        # Convert back to the input data type\\n        full_routing_weights = full_routing_weights.to(hidden_states.dtype)\\n\\n        final_hidden_states = torch.zeros(\\n            (batch_size * sequence_length, hidden_dim), dtype=hidden_states.dtype, device=hidden_states.device\\n        )\\n\\n        # Go through all the experts (not just the selected ones)\\n        for expert_idx in range(self.num_experts):\\n            expert_layer = self.experts[expert_idx]\\n            # Get the weight of the current expert (inactive expert has a weight of 0 here)\\n            expert_weights = full_routing_weights[:, expert_idx, None]  # shape: (batch*seq, 1)\\n            # All samples participate in the calculations of the current expert, the weight may be equal to 0\\n            current_hidden_states = expert_layer(hidden_states) * expert_weights\\n            # Add-up to all expert outputs (experts with a weight of 0 do not affect the result)\\n            final_hidden_states += current_hidden_states\\n\\n        final_hidden_states = final_hidden_states.reshape(batch_size, sequence_length, hidden_dim)\\n        return final_hidden_states, router_logits\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/packing.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"13cebe9262e30258664758505b7de3a7aae5875ccead40a695b897f8da4d0001\",\"content\":\"# Copyright 2025 Musab Gultekin and the LlamaFactory team.\\n#\\n# This code is based on the Musab Gultekin's functionary library.\\n# https://github.com/MeetKai/functionary/blob/main/functionary/train/packing/monkey_patch_packing.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n#\\n# MIT License\\n#\\n# Copyright (c) 2023 Musab Gultekin\\n#\\n# Permission is hereby granted, free of charge, to any person obtaining a copy\\n# of this software and associated documentation files (the \\\"Software\\\"), to deal\\n# in the Software without restriction, including without limitation the rights\\n# to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\\n# copies of the Software, and to permit persons to whom the Software is\\n# furnished to do so, subject to the following conditions:\\n#\\n# The above copyright notice and this permission notice shall be included in all\\n# copies or substantial portions of the Software.\\n#\\n# THE SOFTWARE IS PROVIDED \\\"AS IS\\\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\\n# IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\\n# FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\\n# AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\\n# LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\\n# OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\\n# SOFTWARE.\\n\\n\\nimport torch\\nimport torch.nn.functional as F\\n\\nfrom ...extras import logging\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef get_seqlens_in_batch(attention_mask: \\\"torch.Tensor\\\") -> \\\"torch.Tensor\\\":\\n    r\\\"\\\"\\\"Get the sequence lengths in the current batch.\\n\\n    e.g.\\n    ```python\\n    # input\\n    [\\n        [1, 1, 2, 2, 2, 0],\\n        [1, 2, 2, 3, 3, 3],\\n    ]\\n    # output\\n    [2, 3, 1, 2, 3]\\n    ```\\n    \\\"\\\"\\\"\\n    bsz = attention_mask.size(0)\\n    dtype, device = attention_mask.dtype, attention_mask.device\\n    max_num = torch.max(attention_mask).item()\\n    counts: torch.Tensor = torch.zeros((bsz, max_num), dtype=dtype, device=device)\\n    for i in range(max_num):\\n        counts[:, i] = torch.sum(attention_mask == (i + 1), dim=-1)\\n\\n    counts = counts.flatten()\\n    seqlens = counts[counts.nonzero().squeeze(dim=-1)]\\n    return seqlens\\n\\n\\ndef get_unpad_data(attention_mask: \\\"torch.Tensor\\\") -> tuple[\\\"torch.Tensor\\\", \\\"torch.Tensor\\\", int]:\\n    r\\\"\\\"\\\"Prepare the indices and seqlens for flash attn varlen function.\\n\\n    Returns:\\n        indices: indices of non-masked tokens from the flattened sequence.\\n        cu_seqlens: the cumulative sequence lengths in the current batch, always starts from 0.\\n        max_seqlen_in_batch: the largest seqlen in the current batch.\\n\\n    e.g.\\n    ```python\\n    # input\\n    [\\n        [1, 1, 2, 2, 2, 0],\\n        [1, 2, 2, 3, 3, 3],\\n    ]\\n    # output\\n    [0, 1, 2, 3, 4, 6, 7, 8, 9, 10, 11]\\n    [0, 2, 5, 6, 8, 11]\\n    3\\n    ```\\n\\n    \\\"\\\"\\\"\\n    seqlens_in_batch = get_seqlens_in_batch(attention_mask)\\n    indices = torch.nonzero(attention_mask.flatten(), as_tuple=False).flatten()\\n    max_seqlen_in_batch = seqlens_in_batch.max().item()\\n    cu_seqlens = F.pad(torch.cumsum(seqlens_in_batch, dim=0, dtype=torch.int32), (1, 0))\\n    return indices, cu_seqlens, max_seqlen_in_batch\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/quantization.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"578d97e12ddf5cbc0960e30066539d60bc3370e9a893da2d90eb44ff880175e5\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's Transformers and Optimum library.\\n# https://github.com/huggingface/transformers/blob/v4.41.0/src/transformers/utils/quantization_config.py\\n# https://github.com/huggingface/optimum/blob/v1.20.0/optimum/gptq/data.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\nimport random\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport torch\\nfrom datasets import load_dataset\\nfrom transformers import BitsAndBytesConfig, EetqConfig, GPTQConfig, HqqConfig\\nfrom transformers.integrations import is_deepspeed_zero3_enabled\\nfrom transformers.modeling_utils import is_fsdp_enabled\\n\\nfrom ...extras import logging\\nfrom ...extras.constants import FILEEXT2TYPE, QuantizationMethod\\nfrom ...extras.misc import check_version, get_current_device\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PretrainedConfig, PreTrainedTokenizer\\n\\n    from ...hparams import ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef _uses_kt_non_expert_cache(model_args: \\\"ModelArguments\\\") -> bool:\\n    return model_args.use_kt and bool(model_args.kt_non_expert_weight_path)\\n\\n\\ndef _get_quantization_dataset(tokenizer: \\\"PreTrainedTokenizer\\\", model_args: \\\"ModelArguments\\\") -> list[dict[str, Any]]:\\n    r\\\"\\\"\\\"Prepare the tokenized dataset to perform AutoGPTQ. Do not use tensor output for JSON serialization.\\\"\\\"\\\"\\n    if os.path.isfile(model_args.export_quantization_dataset):\\n        data_path = FILEEXT2TYPE.get(model_args.export_quantization_dataset.split(\\\".\\\")[-1], None)\\n        data_files = model_args.export_quantization_dataset\\n    else:\\n        data_path = model_args.export_quantization_dataset\\n        data_files = None\\n\\n    dataset = load_dataset(\\n        path=data_path,\\n        data_files=data_files,\\n        split=\\\"train\\\",\\n        cache_dir=model_args.cache_dir,\\n        token=model_args.hf_hub_token,\\n    )\\n\\n    samples = []\\n    maxlen = model_args.export_quantization_maxlen\\n    for _ in range(model_args.export_quantization_nsamples):\\n        n_try = 0\\n        while True:\\n            if n_try > 100:\\n                raise ValueError(\\\"Cannot find satisfying example, considering decrease `export_quantization_maxlen`.\\\")\\n\\n            sample_idx = random.randint(0, len(dataset) - 1)\\n            sample: dict[str, torch.Tensor] = tokenizer(dataset[sample_idx][\\\"text\\\"], return_tensors=\\\"pt\\\")\\n            n_try += 1\\n            if sample[\\\"input_ids\\\"].size(1) > maxlen:\\n                break  # TODO: fix large maxlen\\n\\n        word_idx = random.randint(0, sample[\\\"input_ids\\\"].size(1) - maxlen - 1)\\n        input_ids = sample[\\\"input_ids\\\"][:, word_idx : word_idx + maxlen]\\n        attention_mask = sample[\\\"attention_mask\\\"][:, word_idx : word_idx + maxlen]\\n        samples.append({\\\"input_ids\\\": input_ids.tolist(), \\\"attention_mask\\\": attention_mask.tolist()})\\n\\n    return samples\\n\\n\\ndef configure_quantization(\\n    config: \\\"PretrainedConfig\\\",\\n    tokenizer: \\\"PreTrainedTokenizer\\\",\\n    model_args: \\\"ModelArguments\\\",\\n    is_trainable: bool,\\n    init_kwargs: dict[str, Any],\\n) -> None:\\n    r\\\"\\\"\\\"Priority: PTQ-quantized (train/infer) > AutoGPTQ (export) > On-the-fly quantization (train/infer).\\\"\\\"\\\"\\n    if getattr(config, \\\"quantization_config\\\", None):  # ptq\\n        if model_args.quantization_bit is not None:\\n            logger.warning_rank0(\\\"`quantization_bit` will not affect on the PTQ-quantized models.\\\")\\n\\n        quantization_config: dict[str, Any] = getattr(config, \\\"quantization_config\\\", None)\\n        quant_method = quantization_config.get(\\\"quant_method\\\", \\\"\\\")\\n\\n        if quant_method not in (QuantizationMethod.MXFP4, QuantizationMethod.FP8) and (\\n            is_deepspeed_zero3_enabled() or is_fsdp_enabled()\\n        ):\\n            # mxfp4 will dequant the model weights\\n            raise ValueError(\\\"DeepSpeed ZeRO-3 or FSDP is incompatible with PTQ-quantized models.\\\")\\n\\n        if quant_method == QuantizationMethod.MXFP4:\\n            from transformers import Mxfp4Config\\n\\n            quant_config = Mxfp4Config(dequantize=True)\\n            init_kwargs[\\\"quantization_config\\\"] = quant_config\\n            init_kwargs[\\\"ignore_mismatched_sizes\\\"] = True\\n\\n        if quant_method == QuantizationMethod.FP8:\\n            if _uses_kt_non_expert_cache(model_args):\\n                if model_args.quantization_bit is not None:\\n                    raise ValueError(\\\"`quantization_bit` cannot be combined with KT weight caches.\\\")\\n\\n                logger.info_rank0(\\\"Skipping source FP8 dequantization because KT weight caches are configured.\\\")\\n                return\\n\\n            from transformers import FineGrainedFP8Config\\n\\n            quant_config = FineGrainedFP8Config(dequantize=True)\\n            init_kwargs[\\\"quantization_config\\\"] = quant_config\\n            init_kwargs[\\\"ignore_mismatched_sizes\\\"] = True\\n\\n        if quant_method == QuantizationMethod.GPTQ:\\n            check_version(\\\"gptqmodel>=2.0.0\\\", mandatory=True)\\n            quantization_config.pop(\\\"disable_exllama\\\", None)  # remove deprecated args\\n            quantization_config[\\\"use_exllama\\\"] = False  # disable exllama\\n\\n        if quant_method == QuantizationMethod.AWQ:\\n            check_version(\\\"autoawq\\\", mandatory=True)\\n\\n        if quant_method == QuantizationMethod.AQLM:\\n            check_version(\\\"aqlm>=1.1.0\\\", mandatory=True)\\n            quantization_config[\\\"bits\\\"] = 2\\n\\n        quant_bits = quantization_config.get(\\\"bits\\\", \\\"?\\\")\\n        logger.info_rank0(f\\\"Loading {quant_bits}-bit {quant_method.upper()}-quantized model.\\\")\\n\\n    elif model_args.export_quantization_bit is not None:  # gptqmodel\\n        if model_args.export_quantization_bit not in [8, 4, 3, 2]:\\n            raise ValueError(\\\"AutoGPTQ only accepts 2/3/4/8-bit quantization.\\\")\\n\\n        check_version(\\\"optimum>=1.24.0\\\", mandatory=True)\\n        check_version(\\\"gptqmodel>=2.0.0\\\", mandatory=True)\\n        from accelerate.utils import get_max_memory\\n\\n        if getattr(config, \\\"model_type\\\", None) == \\\"chatglm\\\":\\n            raise ValueError(\\\"ChatGLM model is not supported yet.\\\")\\n\\n        try:\\n            from optimum.gptq import utils as gq_utils\\n\\n            if \\\"language_model.model.layers\\\" not in gq_utils.BLOCK_PATTERNS:\\n                gq_utils.BLOCK_PATTERNS.insert(0, \\\"language_model.model.layers\\\")\\n        except ImportError:\\n            pass\\n\\n        block_name_to_quantize = None\\n        if getattr(config, \\\"model_type\\\", None) in [\\\"gemma3\\\", \\\"paligemma\\\"]:\\n            block_name_to_quantize = \\\"language_model.model.layers\\\"\\n\\n        init_kwargs[\\\"quantization_config\\\"] = GPTQConfig(\\n            bits=model_args.export_quantization_bit,\\n            tokenizer=tokenizer,\\n            dataset=_get_quantization_dataset(tokenizer, model_args),\\n            block_name_to_quantize=block_name_to_quantize,\\n        )\\n        init_kwargs[\\\"device_map\\\"] = \\\"auto\\\"\\n        init_kwargs[\\\"max_memory\\\"] = get_max_memory()\\n        model_args.compute_dtype = torch.float16  # force fp16 for gptqmodel\\n        logger.info_rank0(f\\\"Quantizing model to {model_args.export_quantization_bit} bit with GPTQModel.\\\")\\n\\n    elif model_args.quantization_bit is not None:  # on-the-fly\\n        if model_args.quantization_method == QuantizationMethod.BNB:\\n            if model_args.quantization_bit == 8:\\n                check_version(\\\"bitsandbytes>=0.37.0\\\", mandatory=True)\\n                init_kwargs[\\\"quantization_config\\\"] = BitsAndBytesConfig(load_in_8bit=True)\\n            elif model_args.quantization_bit == 4:\\n                check_version(\\\"bitsandbytes>=0.39.0\\\", mandatory=True)\\n                init_kwargs[\\\"quantization_config\\\"] = BitsAndBytesConfig(\\n                    load_in_4bit=True,\\n                    bnb_4bit_compute_dtype=model_args.compute_dtype,\\n                    bnb_4bit_use_double_quant=model_args.double_quantization,\\n                    bnb_4bit_quant_type=model_args.quantization_type,\\n                    bnb_4bit_quant_storage=model_args.compute_dtype,  # crucial for fsdp+qlora\\n                )\\n            else:\\n                raise ValueError(\\\"Bitsandbytes only accepts 4-bit or 8-bit quantization.\\\")\\n\\n            # Do not assign device map if:\\n            # 1. deepspeed zero3 or fsdp (train)\\n            # 2. auto quantization device map (inference)\\n            if is_deepspeed_zero3_enabled() or is_fsdp_enabled() or model_args.quantization_device_map == \\\"auto\\\":\\n                if model_args.quantization_bit != 4:\\n                    raise ValueError(\\\"Only 4-bit quantized model can use fsdp+qlora or auto device map.\\\")\\n\\n                check_version(\\\"bitsandbytes>=0.43.0\\\", mandatory=True)\\n            else:\\n                init_kwargs[\\\"device_map\\\"] = {\\\"\\\": get_current_device()}  # change auto device map for inference\\n\\n            logger.info_rank0(f\\\"Quantizing model to {model_args.quantization_bit} bit with bitsandbytes.\\\")\\n        elif model_args.quantization_method == QuantizationMethod.HQQ:\\n            if model_args.quantization_bit not in [8, 6, 5, 4, 3, 2, 1]:\\n                raise ValueError(\\\"HQQ only accepts 1/2/3/4/5/6/8-bit quantization.\\\")\\n\\n            if is_deepspeed_zero3_enabled() or is_fsdp_enabled():\\n                raise ValueError(\\\"HQQ quantization is incompatible with DeepSpeed ZeRO-3 or FSDP.\\\")\\n\\n            check_version(\\\"hqq\\\", mandatory=True)\\n            init_kwargs[\\\"quantization_config\\\"] = HqqConfig(\\n                nbits=model_args.quantization_bit, quant_zero=False, quant_scale=False, axis=0\\n            )  # use ATEN kernel (axis=0) for performance\\n            logger.info_rank0(f\\\"Quantizing model to {model_args.quantization_bit} bit with HQQ.\\\")\\n        elif model_args.quantization_method == QuantizationMethod.EETQ:\\n            if model_args.quantization_bit != 8:\\n                raise ValueError(\\\"EETQ only accepts 8-bit quantization.\\\")\\n\\n            if is_deepspeed_zero3_enabled() or is_fsdp_enabled():\\n                raise ValueError(\\\"EETQ quantization is incompatible with DeepSpeed ZeRO-3 or FSDP.\\\")\\n\\n            check_version(\\\"eetq\\\", mandatory=True)\\n            init_kwargs[\\\"quantization_config\\\"] = EetqConfig()\\n            logger.info_rank0(f\\\"Quantizing model to {model_args.quantization_bit} bit with EETQ.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/rope.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1a63e7b1a16f1f8a9eaeae8c26763b1ee036a88c676fd0ff68a9c8a168aab5ae\",\"content\":\"# Copyright 2025 LMSYS and the LlamaFactory team.\\n# Copyright 2023 Rohan Taori, Ishaan Gulrajani, Tianyi Zhang, Yann Dubois, Xuechen Li\\n#\\n# This code is inspired by the LMSYS's FastChat library.\\n# https://github.com/lm-sys/FastChat/blob/v0.2.30/fastchat/train/train.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport math\\nfrom typing import TYPE_CHECKING\\n\\nfrom ...extras import logging\\nfrom ...extras.constants import RopeScaling\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PretrainedConfig\\n\\n    from ...hparams import ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef configure_rope(config: \\\"PretrainedConfig\\\", model_args: \\\"ModelArguments\\\") -> None:\\n    if model_args.rope_scaling is None:\\n        return\\n\\n    if not hasattr(config, \\\"rope_scaling\\\"):\\n        logger.warning_rank0(\\\"Current model does not support RoPE scaling.\\\")\\n        return\\n\\n    rope_scaling = getattr(config, \\\"rope_scaling\\\", None)\\n    if isinstance(rope_scaling, dict) and \\\"original_max_position_embeddings\\\" in rope_scaling:\\n        old_max_length = rope_scaling[\\\"original_max_position_embeddings\\\"]\\n    elif hasattr(config, \\\"max_position_embeddings\\\"):\\n        old_max_length = getattr(config, \\\"max_position_embeddings\\\", None)\\n    else:\\n        logger.warning_rank0(\\\"Cannot find the max position embeddings in the config.\\\")\\n        return\\n\\n    if model_args.model_max_length is not None:  # training\\n        if model_args.model_max_length <= old_max_length:\\n            logger.warning_rank0(\\\"Input length is smaller than max length. Disabling rope scaling.\\\")\\n            return\\n\\n        if model_args.rope_scaling == RopeScaling.DYNAMIC:\\n            logger.warning_rank0(\\n                \\\"Dynamic NTK scaling may not work well with fine-tuning. \\\"\\n                \\\"See: https://github.com/huggingface/transformers/pull/24653\\\"\\n            )\\n\\n        rope_factor = float(math.ceil(model_args.model_max_length / old_max_length))\\n    else:  # inference\\n        rope_factor = 2.0\\n\\n    rope_kwargs = {\\n        \\\"rope_type\\\": getattr(model_args.rope_scaling, \\\"value\\\", model_args.rope_scaling),  # handle enum\\n        \\\"factor\\\": rope_factor,\\n    }\\n    setattr(config, \\\"max_position_embeddings\\\", old_max_length * rope_factor)\\n    logger.info_rank0(f\\\"Enlarge max model length from {old_max_length} to {old_max_length * rope_factor}.\\\")\\n\\n    if model_args.rope_scaling in [RopeScaling.DYNAMIC, RopeScaling.YARN]:\\n        rope_kwargs[\\\"original_max_position_embeddings\\\"] = old_max_length\\n    elif model_args.rope_scaling == RopeScaling.LLAMA3:\\n        rope_kwargs[\\\"original_max_position_embeddings\\\"] = old_max_length\\n        rope_kwargs[\\\"low_freq_factor\\\"] = 1.0\\n        rope_kwargs[\\\"high_freq_factor\\\"] = 4.0\\n\\n    setattr(config, \\\"rope_scaling\\\", rope_kwargs)\\n    logger.info_rank0(\\n        f\\\"Using {rope_kwargs['rope_type']} scaling strategy and setting scaling factor to {rope_kwargs['factor']}.\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/unsloth.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"25b99d12e540a7d3fe80a3f00d23967ce53b52e6f7f07e1f60c0f48263e4e5ac\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nfrom ...extras import logging\\nfrom ...extras.misc import get_current_device\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PretrainedConfig, PreTrainedModel\\n\\n    from ...hparams import FinetuningArguments, ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef _get_unsloth_kwargs(\\n    config: \\\"PretrainedConfig\\\",\\n    model_name_or_path: str,\\n    model_args: \\\"ModelArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n) -> dict[str, Any]:\\n    return {\\n        \\\"model_name\\\": model_name_or_path,\\n        \\\"max_seq_length\\\": model_args.model_max_length or 4096,\\n        \\\"dtype\\\": model_args.compute_dtype,\\n        \\\"load_in_4bit\\\": model_args.quantization_bit == 4,\\n        \\\"token\\\": model_args.hf_hub_token,\\n        \\\"full_finetuning\\\": finetuning_args.finetuning_type == \\\"full\\\",\\n        \\\"device_map\\\": {\\\"\\\": get_current_device()},\\n        \\\"rope_scaling\\\": getattr(config, \\\"rope_scaling\\\", None),\\n        \\\"fix_tokenizer\\\": False,\\n        \\\"trust_remote_code\\\": model_args.trust_remote_code,\\n        \\\"use_gradient_checkpointing\\\": \\\"unsloth\\\",\\n    }\\n\\n\\ndef load_unsloth_pretrained_model(\\n    config: \\\"PretrainedConfig\\\", model_args: \\\"ModelArguments\\\", finetuning_args: \\\"FinetuningArguments\\\"\\n) -> Optional[\\\"PreTrainedModel\\\"]:\\n    r\\\"\\\"\\\"Optionally load pretrained model with unsloth. Used in training.\\\"\\\"\\\"\\n    from unsloth import FastLanguageModel  # type: ignore\\n\\n    unsloth_kwargs = _get_unsloth_kwargs(config, model_args.model_name_or_path, model_args, finetuning_args)\\n    try:\\n        model, _ = FastLanguageModel.from_pretrained(**unsloth_kwargs)\\n    except NotImplementedError:\\n        logger.warning_rank0(\\\"Unsloth does not support model type {}.\\\".format(getattr(config, \\\"model_type\\\", None)))\\n        model = None\\n        model_args.use_unsloth = False\\n\\n    return model\\n\\n\\ndef get_unsloth_peft_model(\\n    model: \\\"PreTrainedModel\\\", model_args: \\\"ModelArguments\\\", peft_kwargs: dict[str, Any]\\n) -> \\\"PreTrainedModel\\\":\\n    r\\\"\\\"\\\"Get the peft model for the pretrained model with unsloth. Used in training.\\\"\\\"\\\"\\n    from unsloth import FastLanguageModel  # type: ignore\\n\\n    unsloth_peft_kwargs = {\\n        \\\"model\\\": model,\\n        \\\"max_seq_length\\\": model_args.model_max_length,\\n        \\\"use_gradient_checkpointing\\\": \\\"unsloth\\\",\\n    }\\n    return FastLanguageModel.get_peft_model(**peft_kwargs, **unsloth_peft_kwargs)\\n\\n\\ndef load_unsloth_peft_model(\\n    config: \\\"PretrainedConfig\\\",\\n    model_args: \\\"ModelArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    is_trainable: bool,\\n) -> Optional[\\\"PreTrainedModel\\\"]:\\n    r\\\"\\\"\\\"Load peft model with unsloth. Used in both training and inference.\\n\\n    Returns None if unsloth does not support the model type, and sets\\n    model_args.use_unsloth = False so callers can fall back to standard loading.\\n    \\\"\\\"\\\"\\n    from unsloth import FastLanguageModel  # type: ignore\\n\\n    unsloth_kwargs = _get_unsloth_kwargs(config, model_args.adapter_name_or_path[0], model_args, finetuning_args)\\n    try:\\n        if not is_trainable:\\n            unsloth_kwargs[\\\"use_gradient_checkpointing\\\"] = False\\n\\n        model, _ = FastLanguageModel.from_pretrained(**unsloth_kwargs)\\n    except NotImplementedError:\\n        logger.warning_rank0(\\\"Unsloth does not support model type {}.\\\".format(getattr(config, \\\"model_type\\\", None)))\\n        model_args.use_unsloth = False\\n        return None\\n\\n    if not is_trainable:\\n        FastLanguageModel.for_inference(model)\\n\\n    return model\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/valuehead.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"151023380cb75e1d7fb120de1cea2af6b2fc6159d84be85dacdd872055087412\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport torch\\nfrom transformers.utils import cached_file\\n\\nfrom ...extras import logging\\nfrom ...extras.constants import V_HEAD_SAFE_WEIGHTS_NAME, V_HEAD_WEIGHTS_NAME\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel\\n\\n    from ...hparams import ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef load_valuehead_params(path_or_repo_id: str, model_args: \\\"ModelArguments\\\") -> dict[str, torch.Tensor]:\\n    r\\\"\\\"\\\"Load value head parameters from Hugging Face Hub or local disk.\\n\\n    Returns: dict with keys `v_head.summary.weight` and `v_head.summary.bias`.\\n    \\\"\\\"\\\"\\n    kwargs = {\\\"path_or_repo_id\\\": path_or_repo_id, \\\"cache_dir\\\": model_args.cache_dir, \\\"token\\\": model_args.hf_hub_token}\\n    err_text = \\\"\\\"\\n\\n    try:\\n        from safetensors import safe_open\\n\\n        vhead_file = cached_file(filename=V_HEAD_SAFE_WEIGHTS_NAME, **kwargs)\\n        with safe_open(vhead_file, framework=\\\"pt\\\", device=\\\"cpu\\\") as f:\\n            return {key: f.get_tensor(key) for key in f.keys()}\\n    except Exception as err:\\n        err_text = str(err)\\n\\n    try:\\n        vhead_file = cached_file(filename=V_HEAD_WEIGHTS_NAME, **kwargs)\\n        return torch.load(vhead_file, map_location=\\\"cpu\\\", weights_only=True)\\n    except Exception as err:\\n        err_text = str(err)\\n\\n    logger.info_rank0(f\\\"Provided path ({path_or_repo_id}) does not contain value head weights: {err_text}.\\\")\\n    logger.info_rank0(\\\"Ignore the above message if you are not resuming the training of a value head model.\\\")\\n    return None\\n\\n\\ndef prepare_valuehead_model(model: \\\"PreTrainedModel\\\") -> None:\\n    if getattr(model.config, \\\"model_type\\\", None) == \\\"llava\\\":\\n        setattr(model, \\\"lm_head\\\", model.language_model.get_output_embeddings())\\n        setattr(model, \\\"_keys_to_ignore_on_save\\\", [\\\"lm_head.weight\\\"])\\n\\n    if getattr(model.config, \\\"model_type\\\", None) == \\\"chatglm\\\":\\n        setattr(model, \\\"lm_head\\\", model.transformer.output_layer)\\n        setattr(model, \\\"_keys_to_ignore_on_save\\\", [\\\"lm_head.weight\\\"])\\n\\n    if getattr(model.config, \\\"model_type\\\", None) == \\\"internlm2\\\":\\n        setattr(model, \\\"lm_head\\\", model.output)\\n        setattr(model, \\\"_keys_to_ignore_on_save\\\", [\\\"lm_head.weight\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/model_utils/visual.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"774d682971e4cd614463cfdb1d131a086bee9fb69d4d5d19ec8607f26db0d374\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's Transformers library.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/src/transformers/models/llava/modeling_llava.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING, Optional\\n\\nimport torch\\nimport transformers\\nimport transformers.models\\nfrom transformers.activations import ACT2FN\\n\\nfrom ...extras import logging\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import LlavaConfig, PretrainedConfig, PreTrainedModel\\n\\n    from ...hparams import FinetuningArguments, ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\ntransformers_logger = transformers.utils.logging.get_logger(__name__)\\n\\n\\n@dataclass\\nclass CompositeModel:\\n    model_type: str\\n    projector_keys: list[str]\\n    vision_model_keys: list[str]\\n    language_model_keys: list[str]\\n    lora_conflict_keys: list[str]\\n\\n    def get_projectors(self, module: \\\"torch.nn.Module\\\") -> list[\\\"torch.nn.Module\\\"]:\\n        mm_projectors: list[torch.nn.Module] = []\\n        for projector_key in self.projector_keys:\\n            project_module = module\\n            for key in projector_key.split(\\\".\\\"):\\n                project_module = getattr(project_module, key, None)\\n                if project_module is None:  # i,e gemma4 bigger one, there is no embed_audio\\n                    logger.warning_rank0(\\n                        f\\\"Projector key {projector_key} not found in module {module.__class__.__name__}.\\\"\\n                    )\\n                    break\\n\\n            if isinstance(project_module, torch.nn.Module):\\n                mm_projectors.append(project_module)\\n\\n        return mm_projectors\\n\\n\\nCOMPOSITE_MODELS: dict[str, \\\"CompositeModel\\\"] = {}\\n\\n\\ndef _register_composite_model(\\n    model_type: str,\\n    projector_keys: list[str] | None = None,\\n    vision_model_keys: Optional[list[str]] = None,\\n    language_model_keys: Optional[list[str]] = None,\\n    lora_conflict_keys: Optional[list[str]] = None,\\n):\\n    r\\\"\\\"\\\"Register a new composite model.\\n\\n    Args:\\n        model_type: model type\\n        projector_keys: multi_modal_projector\\n        vision_model_keys: vision_tower\\n        language_model_keys: language_model\\n        lora_conflict_keys: None\\n\\n    \\\"\\\"\\\"\\n    COMPOSITE_MODELS[model_type] = CompositeModel(\\n        model_type=model_type,\\n        projector_keys=projector_keys or [\\\"multi_modal_projector\\\"],\\n        vision_model_keys=vision_model_keys or [\\\"vision_tower\\\"],\\n        language_model_keys=language_model_keys or [\\\"language_model\\\", \\\"lm_head\\\"],\\n        lora_conflict_keys=lora_conflict_keys or [],\\n    )\\n\\n\\nclass LlavaMultiModalProjectorForYiVL(torch.nn.Module):\\n    def __init__(self, config: \\\"LlavaConfig\\\") -> None:\\n        super().__init__()\\n\\n        self.config = config\\n        if config is None:\\n            return\\n\\n        self.linear_1 = torch.nn.Linear(config.vision_config.hidden_size, config.text_config.hidden_size, bias=True)\\n        self.linear_2 = torch.nn.LayerNorm(config.text_config.hidden_size, bias=True)\\n        self.linear_3 = torch.nn.Linear(config.text_config.hidden_size, config.text_config.hidden_size, bias=True)\\n        self.linear_4 = torch.nn.LayerNorm(config.text_config.hidden_size, bias=True)\\n        self.act = ACT2FN[config.projector_hidden_act]\\n\\n    def forward(self, image_features: \\\"torch.Tensor\\\") -> \\\"torch.Tensor\\\":\\n        hidden_states = self.linear_1(image_features)\\n        hidden_states = self.linear_2(hidden_states)\\n        hidden_states = self.act(hidden_states)\\n        hidden_states = self.linear_3(hidden_states)\\n        hidden_states = self.linear_4(hidden_states)\\n        if hidden_states.dtype == torch.float32:\\n            if torch.is_autocast_enabled():\\n                target_dtype = torch.get_autocast_gpu_dtype()\\n            elif hasattr(self.config, \\\"_pre_quantization_dtype\\\"):\\n                target_dtype = self.config._pre_quantization_dtype\\n            else:\\n                target_dtype = self.linear_1.weight.dtype\\n\\n            transformers_logger.warning_once(\\\"The hidden states seems to be silently casted in float32.\\\")\\n            hidden_states = hidden_states.to(target_dtype)\\n\\n        return hidden_states\\n\\n\\nclass LlavaMultiModalProjectorForYiVLForVLLM(LlavaMultiModalProjectorForYiVL):\\n    def __init__(self, vision_hidden_size: int, text_hidden_size: int, projector_hidden_act: str) -> None:\\n        super().__init__(config=None)\\n\\n        self.linear_1 = torch.nn.Linear(vision_hidden_size, text_hidden_size, bias=True)\\n        self.linear_2 = torch.nn.LayerNorm(text_hidden_size, bias=True)\\n        self.linear_3 = torch.nn.Linear(text_hidden_size, text_hidden_size, bias=True)\\n        self.linear_4 = torch.nn.LayerNorm(text_hidden_size, bias=True)\\n        self.act = ACT2FN[projector_hidden_act]\\n\\n\\ndef autocast_projector_dtype(model: \\\"PreTrainedModel\\\", model_args: \\\"ModelArguments\\\") -> None:\\n    r\\\"\\\"\\\"Cast projector output to half precision for fine-tuning quantized VLMs.\\\"\\\"\\\"\\n\\n    def _mm_projector_forward_post_hook(\\n        module: \\\"torch.nn.Module\\\", args: tuple[\\\"torch.Tensor\\\"], output: \\\"torch.Tensor\\\"\\n    ) -> \\\"torch.Tensor\\\":\\n        return output.to(model_args.compute_dtype)\\n\\n    if getattr(model, \\\"quantization_method\\\", None):\\n        model_type = getattr(model.config, \\\"model_type\\\", None)\\n        if model_type in COMPOSITE_MODELS:\\n            mm_projectors = COMPOSITE_MODELS[model_type].get_projectors(model)\\n        else:\\n            return\\n\\n        logger.info_rank0(\\n            f\\\"Casting multimodal projector outputs in {model_args.compute_dtype}: \\\"\\n            f\\\"{COMPOSITE_MODELS[model_type].projector_keys}.\\\"\\n        )\\n        for mm_projector in mm_projectors:\\n            mm_projector.register_forward_hook(_mm_projector_forward_post_hook)\\n\\n\\ndef configure_visual_model(config: \\\"PretrainedConfig\\\") -> None:\\n    r\\\"\\\"\\\"Patch VLMs before loading them.\\\"\\\"\\\"\\n    if getattr(config, \\\"text_config\\\", None) and not getattr(config, \\\"hidden_size\\\", None):\\n        # required for ds zero3 and valuehead models\\n        setattr(config, \\\"hidden_size\\\", getattr(config.text_config, \\\"hidden_size\\\", None))\\n\\n    if getattr(config, \\\"is_yi_vl_derived_model\\\", None):\\n        logger.info_rank0(\\\"Detected Yi-VL model, applying projector patch.\\\")\\n        transformers.models.llava.modeling_llava.LlavaMultiModalProjector = LlavaMultiModalProjectorForYiVL\\n\\n\\ndef get_forbidden_modules(config: \\\"PretrainedConfig\\\", finetuning_args: \\\"FinetuningArguments\\\") -> set[str]:\\n    r\\\"\\\"\\\"Freeze vision tower and language model for VLM full/freeze tuning.\\\"\\\"\\\"\\n    model_type = getattr(config, \\\"model_type\\\", None)\\n    forbidden_modules = set()\\n    if model_type in COMPOSITE_MODELS:\\n        if finetuning_args.freeze_vision_tower:\\n            vision_model_keys = COMPOSITE_MODELS[model_type].vision_model_keys\\n            logger.info_rank0(f\\\"Set vision model not trainable: {vision_model_keys}.\\\")\\n            forbidden_modules.update(vision_model_keys)\\n\\n        if finetuning_args.freeze_multi_modal_projector:\\n            projector_keys = COMPOSITE_MODELS[model_type].projector_keys\\n            logger.info_rank0(f\\\"Set multi model projector not trainable: {projector_keys}.\\\")\\n            forbidden_modules.update(projector_keys)\\n\\n        if finetuning_args.freeze_language_model:\\n            language_model_keys = COMPOSITE_MODELS[model_type].language_model_keys\\n            logger.info_rank0(f\\\"Set language model not trainable: {language_model_keys}.\\\")\\n            forbidden_modules.update(language_model_keys)\\n\\n    return forbidden_modules\\n\\n\\ndef patch_target_modules(\\n    model: \\\"PreTrainedModel\\\", finetuning_args: \\\"FinetuningArguments\\\", target_modules: list[str]\\n) -> list[str]:\\n    r\\\"\\\"\\\"Freeze vision tower for VLM LoRA tuning.\\\"\\\"\\\"\\n    model_type = getattr(model.config, \\\"model_type\\\", None)\\n    if model_type in COMPOSITE_MODELS:\\n        forbidden_modules = get_forbidden_modules(model.config, finetuning_args)\\n        forbidden_modules.update(COMPOSITE_MODELS[model_type].lora_conflict_keys)\\n        module_names = []\\n        for name, _ in model.named_modules():\\n            if any(target_module in name for target_module in target_modules) and not any(\\n                forbidden_module in name for forbidden_module in forbidden_modules\\n            ):\\n                module_names.append(name)\\n\\n        return module_names\\n    else:\\n        return target_modules\\n\\n\\n_register_composite_model(\\n    model_type=\\\"dots_ocr\\\",\\n    projector_keys=[\\\"vision_tower.merger\\\"],\\n    vision_model_keys=[\\\"vision_tower\\\"],\\n    language_model_keys=[\\\"model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"merger\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"gemma3\\\",\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"gemma3n\\\",\\n    vision_model_keys=[\\\"vision_tower\\\", \\\"audio_tower\\\"],\\n    lora_conflict_keys=[\\\"timm_model\\\", \\\"subsample_conv_projection\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"gemma4\\\",\\n    projector_keys=[\\\"model.embed_vision\\\", \\\"model.embed_audio\\\"],\\n    vision_model_keys=[\\\"vision_tower\\\", \\\"audio_tower\\\"],\\n    lora_conflict_keys=[\\\"per_layer_projection_norm\\\"],\\n)\\n\\n\\n# copied from qwen2vl\\n_register_composite_model(\\n    model_type=\\\"glm4v\\\",\\n    projector_keys=[\\\"visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.patch_embed\\\", \\\"visual.blocks\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"glm4v_moe\\\",\\n    projector_keys=[\\\"visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.patch_embed\\\", \\\"visual.blocks\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"glm_ocr\\\",\\n    projector_keys=[\\\"visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.patch_embed\\\", \\\"visual.blocks\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"internvl\\\",\\n)\\n\\n_register_composite_model(\\n    model_type=\\\"interns1\\\",\\n)\\n\\n_register_composite_model(\\n    model_type=\\\"Keye\\\",\\n    projector_keys=[\\\"mlp_AR\\\"],\\n    vision_model_keys=[\\\"visual.vision_model.patch_embedding\\\", \\\"visual.vision_model.encoder\\\"],\\n    language_model_keys=[\\\"model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embedding\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"kimi_vl\\\",\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"llama4\\\",\\n    vision_model_keys=[\\\"vision_model\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"llava\\\",\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"llava_next\\\",\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"llava_next_video\\\",\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"minicpmv\\\",\\n    projector_keys=[\\\"resampler\\\"],\\n    vision_model_keys=[\\\"vpm\\\"],\\n    language_model_keys=[\\\"llm\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"minicpmv4_6\\\",\\n    projector_keys=[\\\"model.merger\\\"],\\n    vision_model_keys=[\\\"model.vision_tower\\\"],\\n    language_model_keys=[\\\"model.language_model\\\", \\\"lm_head\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"minicpmo\\\",\\n    projector_keys=[\\\"resampler\\\"],\\n    vision_model_keys=[\\\"vpm\\\", \\\"apm\\\", \\\"audio_avg_pooler\\\", \\\"audio_projection_layer\\\", \\\"tts\\\"],\\n    language_model_keys=[\\\"llm\\\"],\\n    lora_conflict_keys=[\\\"audio_projection_layer\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"mistral3\\\",\\n    projector_keys=[\\\"model.multi_modal_projector\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"moss_vl\\\",\\n    projector_keys=[\\\"model.visual.merger\\\", \\\"model.separator_token\\\"],\\n    vision_model_keys=[\\\"model.visual.pos_embed\\\", \\\"model.visual.patch_embed\\\", \\\"model.visual.blocks\\\"],\\n    language_model_keys=[\\\"model.language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"mllama\\\",\\n    vision_model_keys=[\\\"vision_model\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"paligemma\\\",\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen2_audio\\\",\\n    vision_model_keys=[\\\"audio_tower\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen2_5_omni_thinker\\\",\\n    projector_keys=[\\\"visual.merger\\\", \\\"audio_tower.proj\\\"],\\n    vision_model_keys=[\\\"visual.patch_embed\\\", \\\"visual.blocks\\\", \\\"audio_tower\\\"],\\n    language_model_keys=[\\\"model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen2_vl\\\",\\n    projector_keys=[\\\"visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.patch_embed\\\", \\\"visual.blocks\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen2_5_vl\\\",\\n    projector_keys=[\\\"visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.patch_embed\\\", \\\"visual.blocks\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen3_vl\\\",\\n    projector_keys=[\\\"visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.pos_embed\\\", \\\"visual.patch_embed\\\", \\\"visual.blocks\\\", \\\"visual.deepstack_merger_list\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen3_vl_moe\\\",\\n    projector_keys=[\\\"visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.pos_embed\\\", \\\"visual.patch_embed\\\", \\\"visual.blocks\\\", \\\"visual.deepstack_merger_list\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen3_omni_moe_thinker\\\",\\n    projector_keys=[\\\"visual.merger\\\", \\\"audio_tower.proj\\\"],\\n    vision_model_keys=[\\n        \\\"visual.pos_embed\\\",\\n        \\\"visual.patch_embed\\\",\\n        \\\"visual.blocks\\\",\\n        \\\"visual.deepstack_merger_list\\\",\\n        \\\"audio_tower\\\",\\n    ],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen3_5\\\",\\n    projector_keys=[\\\"model.visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.pos_embed\\\", \\\"visual.patch_embed\\\", \\\"visual.blocks\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"qwen3_5_moe\\\",\\n    projector_keys=[\\\"model.visual.merger\\\"],\\n    vision_model_keys=[\\\"visual.pos_embed\\\", \\\"visual.patch_embed\\\", \\\"visual.blocks\\\"],\\n    language_model_keys=[\\\"language_model\\\", \\\"lm_head\\\"],\\n    lora_conflict_keys=[\\\"patch_embed\\\"],\\n)\\n\\n\\n_register_composite_model(\\n    model_type=\\\"video_llava\\\",\\n)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/model/patcher.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a6d1e7c5de4ddfc8aaf30840441bab24d2a38f1441486a2b421ce4e609107237\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom types import MethodType\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport torch\\nfrom peft import PeftModel\\nfrom transformers import GenerationMixin, PreTrainedModel, PreTrainedTokenizerBase\\nfrom transformers.integrations import is_deepspeed_zero3_enabled\\nfrom transformers.modeling_utils import is_fsdp_enabled\\nfrom transformers.utils import is_torch_cuda_available, is_torch_npu_available\\n\\nfrom ..extras import logging\\nfrom ..extras.misc import check_version, infer_optim_dtype\\nfrom ..extras.packages import is_transformers_version_greater_than\\nfrom .model_utils.attention import configure_attn_implementation, print_attn_implementation\\nfrom .model_utils.checkpointing import prepare_model_for_training\\nfrom .model_utils.embedding import resize_embedding_layer\\nfrom .model_utils.kv_cache import configure_kv_cache\\nfrom .model_utils.longlora import configure_longlora\\nfrom .model_utils.moe import add_z3_leaf_module, configure_moe\\nfrom .model_utils.quantization import configure_quantization\\nfrom .model_utils.rope import configure_rope\\nfrom .model_utils.valuehead import prepare_valuehead_model\\nfrom .model_utils.visual import autocast_projector_dtype, configure_visual_model\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PretrainedConfig, PreTrainedTokenizer, ProcessorMixin\\n    from trl import AutoModelForCausalLMWithValueHead\\n\\n    from ..hparams import ModelArguments\\n\\nif is_transformers_version_greater_than(\\\"4.57.0\\\"):\\n    from transformers.models.qwen3_omni_moe import modeling_qwen3_omni_moe\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef patch_qwen3_omni_moe_thinker_text_sparse_moe_block():\\n    if is_transformers_version_greater_than(\\\"4.57.0\\\") and not is_transformers_version_greater_than(\\\"4.58.0\\\"):\\n        from .model_utils.moe import Qwen3OmniMoeThinkerTextSparseMoeBlock\\n\\n        logger.warning_rank0(\\n            \\\"You are using transformers with 4.x version, the Qwen3OmniMoeThinkerTextSparseMoeBlock will have some issues about deepspeed zero2 and fsdp2 training, so that we patched this model to avoid it. Transformers v5.0.0rc0 has fixed the issue, you can also try to update the transformers to using qwen3_omni. See more information on https://github.com/hiyouga/LLaMA-Factory/issues/9628.\\\"\\n        )\\n\\n        modeling_qwen3_omni_moe.Qwen3OmniMoeThinkerTextSparseMoeBlock = Qwen3OmniMoeThinkerTextSparseMoeBlock\\n\\n\\ndef _check_fla_dependencies() -> None:\\n    \\\"\\\"\\\"Check that the FLA dependencies required for varlen GDN forwarding are available.\\n\\n    Requires ``flash-linear-attention >= 0.4.1`` (which exposes the varlen\\n    ``causal_conv1d`` under ``fla.modules.convolution`` and the\\n    ``chunk_gated_delta_rule`` / ``fused_recurrent_gated_delta_rule`` kernels\\n    under ``fla.ops.gated_delta_rule``). Raises ``ImportError`` with an\\n    actionable message otherwise.\\n    \\\"\\\"\\\"\\n    try:\\n        from fla.modules.convolution import causal_conv1d  # noqa: F401\\n        from fla.ops.gated_delta_rule import (  # noqa: F401\\n            chunk_gated_delta_rule,\\n            fused_recurrent_gated_delta_rule,\\n        )\\n    except ImportError as exc:\\n        raise ImportError(\\n            \\\"Qwen3.5 packing-seq forwarding requires `flash-linear-attention>=0.4.1` \\\"\\n            \\\"(provides `fla.modules.convolution.causal_conv1d` and \\\"\\n            \\\"`fla.ops.gated_delta_rule.{chunk,fused_recurrent}_gated_delta_rule`). \\\"\\n            \\\"Please install/upgrade it.\\\"\\n        ) from exc\\n\\n\\ndef patch_qwen3_5_forward_npu(model: \\\"PreTrainedModel\\\") -> None:\\n    \\\"\\\"\\\"Patch for Qwen3.5 models on NPU by importing torch_npu to enable torch.cuda compatibility.\\n\\n    On NPU, torch.cuda operations will fail unless torch_npu is imported.\\n    torch_npu provides compatibility layer that maps torch.cuda calls to NPU operations.\\n\\n    Also replaces chunk_gated_delta_rule with NPU-compatible implementation.\\n    \\\"\\\"\\\"\\n    import importlib.metadata\\n\\n    if \\\"Ascend910\\\" not in torch.npu.get_device_name(0):\\n        logger.warning_rank0(\\\"Currently only 910B series NPUs are supported for the NPU GDN patch.\\\")\\n        return\\n\\n    try:\\n        importlib.metadata.version(\\\"triton_ascend\\\")\\n    except importlib.metadata.PackageNotFoundError:\\n        logger.warning_rank0(\\n            \\\"triton_ascend not installed, skipping NPU GDN patch. \\\"\\n            \\\"To enable it on NPU, reinstall Triton with the Ascend build: \\\"\\n            \\\"`pip uninstall -y triton && pip install -r requirements/triton_ascend.txt`. \\\"\\n            \\\"Note: triton and triton_ascend cannot coexist \u2014 triton must be uninstalled first.\\\"\\n        )\\n        return\\n\\n    logger.info_rank0(\\\"triton_ascend detected for NPU compatibility.\\\")\\n\\n    from ..third_party.triton.chunk_gated_delta_rule import chunk_gated_delta_rule as npu_chunk_gated_delta_rule\\n\\n    if model.config.architectures[0] == \\\"Qwen3_5MoeForConditionalGeneration\\\":\\n        try:\\n            # Qwen3.5-MoE structure: model.model.language_model.layers\\n            for layer in model.model.language_model.layers:\\n                if hasattr(layer, \\\"linear_attn\\\"):\\n                    layer.linear_attn.chunk_gated_delta_rule = npu_chunk_gated_delta_rule\\n\\n            logger.info_rank0(\\n                \\\"Replaced chunk_gated_delta_rule with NPU-compatible implementation for Qwen3.5-MoE model.\\\"\\n            )\\n        except Exception as e:\\n            logger.warning_rank0(f\\\"Failed to replace chunk_gated_delta_rule for NPU: {e}\\\")\\n    elif model.config.architectures[0] == \\\"Qwen3_5ForConditionalGeneration\\\":\\n        try:\\n            # Qwen3.5 structure: model.model.layers\\n            for layer in model.model.layers:\\n                if hasattr(layer, \\\"linear_attn\\\"):\\n                    layer.linear_attn.chunk_gated_delta_rule = npu_chunk_gated_delta_rule\\n\\n            logger.info_rank0(\\\"Replaced chunk_gated_delta_rule with NPU-compatible implementation for Qwen3.5 model.\\\")\\n        except Exception as e:\\n            logger.warning_rank0(f\\\"Failed to replace chunk_gated_delta_rule for NPU: {e}\\\")\\n\\n\\ndef patch_qwen3_5_forward_gpu(model: \\\"PreTrainedModel\\\") -> None:\\n    \\\"\\\"\\\"Patch Qwen3.5 decoder forward methods to support cu_seqlens during training.\\n\\n    Refer to: https://github.com/axolotl-ai-cloud/axolotl/blob/main/src/axolotl/monkeypatch/models/qwen3_5/modeling.py.\\n    \\\"\\\"\\\"\\n    if is_transformers_version_greater_than(\\\"5.2.0\\\"):\\n        from transformers.models.qwen3_5.modeling_qwen3_5 import apply_mask_to_padding_states\\n\\n    from torch.nn import functional as F\\n    from transformers.modeling_flash_attention_utils import prepare_fa_kwargs_from_position_ids\\n\\n    _check_fla_dependencies()\\n    from fla.modules.convolution import causal_conv1d as fla_causal_conv1d\\n    from fla.ops.gated_delta_rule import chunk_gated_delta_rule\\n\\n    def _patched_decoder_forward(\\n        self,\\n        hidden_states: torch.Tensor,\\n        position_embeddings: tuple[torch.Tensor, torch.Tensor],\\n        attention_mask: torch.Tensor | None = None,\\n        position_ids: torch.LongTensor | None = None,\\n        past_key_values=None,\\n        cache_position: torch.LongTensor | None = None,\\n        **kwargs,\\n    ) -> torch.FloatTensor:\\n        \\\"\\\"\\\"Decoder layer forward that passes position_ids through to linear attention.\\\"\\\"\\\"\\n        residual = hidden_states\\n        hidden_states = self.input_layernorm(hidden_states)\\n\\n        if self.layer_type == \\\"linear_attention\\\":\\n            hidden_states = self.linear_attn(\\n                hidden_states=hidden_states,\\n                cache_params=past_key_values,\\n                cache_position=cache_position,\\n                attention_mask=attention_mask,\\n                position_ids=position_ids,  # passing position_ids to linear attention\\n            )\\n        elif self.layer_type == \\\"full_attention\\\":\\n            hidden_states, _ = self.self_attn(\\n                hidden_states=hidden_states,\\n                attention_mask=attention_mask,\\n                position_ids=position_ids[None, 0],  # keep [1, B, L]\\n                past_key_values=past_key_values,\\n                cache_position=cache_position,\\n                position_embeddings=position_embeddings,\\n                **kwargs,\\n            )\\n\\n        hidden_states = residual + hidden_states\\n\\n        residual = hidden_states\\n        hidden_states = self.post_attention_layernorm(hidden_states)\\n        hidden_states = self.mlp(hidden_states)\\n        if isinstance(hidden_states, tuple):  # MoE returns (hidden_states, router_logits)\\n            hidden_states, _ = hidden_states\\n\\n        hidden_states = residual + hidden_states\\n\\n        return hidden_states\\n\\n    # gdn forward (training only, cache_params is always None)\\n    def _patch_gdn_forward(\\n        self,\\n        hidden_states: torch.Tensor,\\n        cache_params=None,\\n        cache_position: torch.LongTensor | None = None,\\n        attention_mask: torch.Tensor | None = None,\\n        position_ids: torch.LongTensor | None = None,\\n    ):\\n        # @kuangdd fix: here attention_mask is None\\n        hidden_states = apply_mask_to_padding_states(hidden_states, attention_mask)\\n\\n        batch_size, seq_len, _ = hidden_states.shape\\n\\n        # Qwen3.5 VL passes 3-D MRoPE position_ids ([axes, B, T]); collapse to [B, T].\\n        if position_ids is not None and position_ids.ndim == 3:\\n            position_ids = position_ids[0]\\n\\n        # cu_seqlens for the FLA varlen path is only needed when batch_size == 1:\\n        # packing / neat-packing: always folded into a single sequence (bsz == 1) -> varlen\\n        # non-packing, bsz == 1: single segment, equivalent to a standard single sequence\\n        # non-packing, bsz > 1: not packed, use cu_seqlens=None and standard batched kernels\\n        if position_ids is not None and batch_size == 1:\\n            cu_seqlens = prepare_fa_kwargs_from_position_ids(position_ids)[0][0]\\n        else:\\n            cu_seqlens = None\\n\\n        # FLA varlen kernels expect [B, T, D] layout, not [B, D, T] like the\\n        # standard causal-conv1d path that the upstream forward uses.\\n        mixed_qkv = self.in_proj_qkv(hidden_states)\\n\\n        z = self.in_proj_z(hidden_states)\\n        z = z.reshape(batch_size, seq_len, -1, self.head_v_dim)\\n\\n        b = self.in_proj_b(hidden_states)\\n        a = self.in_proj_a(hidden_states)\\n\\n        # FLA's causal_conv1d returns (out, final_state); we don't use the state here.\\n        mixed_qkv, _ = fla_causal_conv1d(\\n            x=mixed_qkv,\\n            weight=self.conv1d.weight.squeeze(1),\\n            bias=self.conv1d.bias,\\n            activation=self.activation,\\n            cu_seqlens=cu_seqlens,\\n        )\\n\\n        query, key, value = torch.split(\\n            mixed_qkv,\\n            [\\n                self.key_dim,\\n                self.key_dim,\\n                self.value_dim,\\n            ],\\n            dim=-1,\\n        )\\n\\n        query = query.reshape(batch_size, seq_len, -1, self.head_k_dim)\\n        key = key.reshape(batch_size, seq_len, -1, self.head_k_dim)\\n        value = value.reshape(batch_size, seq_len, -1, self.head_v_dim)\\n\\n        beta = b.sigmoid()\\n        # If the model is loaded in fp16, without the .float() here, A might be -inf\\n        g = -self.A_log.float().exp() * F.softplus(a.float() + self.dt_bias)\\n        if self.num_v_heads // self.num_k_heads > 1:\\n            query = query.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=2)\\n            key = key.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=2)\\n\\n        core_attn_out, _ = chunk_gated_delta_rule(\\n            query,\\n            key,\\n            value,\\n            g=g,\\n            beta=beta,\\n            initial_state=None,\\n            output_final_state=False,\\n            use_qk_l2norm_in_kernel=True,\\n            **({\\\"cu_seqlens\\\": cu_seqlens} if cu_seqlens is not None else {}),\\n        )\\n\\n        core_attn_out = core_attn_out.reshape(-1, self.head_v_dim)\\n        z = z.reshape(-1, self.head_v_dim)\\n        core_attn_out = self.norm(core_attn_out, z)\\n        core_attn_out = core_attn_out.reshape(batch_size, seq_len, -1)\\n\\n        output = self.out_proj(core_attn_out)\\n\\n        return output\\n\\n    if model.config.architectures[0] in (\\\"Qwen3_5ForCausalLM\\\", \\\"Qwen3_5ForConditionalGeneration\\\"):\\n        from transformers.models.qwen3_5.modeling_qwen3_5 import Qwen3_5DecoderLayer, Qwen3_5GatedDeltaNet\\n\\n        Qwen3_5DecoderLayer.forward = _patched_decoder_forward\\n        Qwen3_5GatedDeltaNet.forward = _patch_gdn_forward\\n    elif model.config.architectures[0] in (\\\"Qwen3_5MoeForCausalLM\\\", \\\"Qwen3_5MoeForConditionalGeneration\\\"):\\n        from transformers.models.qwen3_5_moe.modeling_qwen3_5_moe import (\\n            Qwen3_5MoeDecoderLayer,\\n            Qwen3_5MoeGatedDeltaNet,\\n        )\\n\\n        Qwen3_5MoeDecoderLayer.forward = _patched_decoder_forward\\n        Qwen3_5MoeGatedDeltaNet.forward = _patch_gdn_forward\\n\\n    logger.info_rank0(\\\"Patched Qwen3.5 decoder forward to support cu_seqlens input only patch when do training.\\\")\\n\\n\\ndef patch_youtu_vl_model(model: \\\"PreTrainedModel\\\") -> None:\\n    original_forward = model.forward\\n\\n    def forward(self, *args, **kwargs):\\n        outputs = original_forward(*args, **kwargs)\\n        if \\\"loss\\\" not in outputs and \\\"labels\\\" in kwargs:\\n            logits = outputs.get(\\\"logits\\\")\\n            labels = kwargs.get(\\\"labels\\\")\\n            if logits is not None and labels is not None:\\n                shift_logits = logits[..., :-1, :].contiguous()\\n                shift_labels = labels[..., 1:].contiguous()\\n                loss_fct = torch.nn.CrossEntropyLoss()\\n                loss = loss_fct(shift_logits.view(-1, self.config.vocab_size), shift_labels.view(-1))\\n                outputs[\\\"loss\\\"] = loss\\n\\n        return outputs\\n\\n    model.forward = MethodType(forward, model)\\n\\n\\ndef patch_tokenizer(tokenizer: \\\"PreTrainedTokenizer\\\", model_args: \\\"ModelArguments\\\") -> None:\\n    if \\\"PreTrainedTokenizerBase\\\" not in str(tokenizer._pad.__func__):\\n        tokenizer._pad = MethodType(PreTrainedTokenizerBase._pad, tokenizer)\\n\\n    if model_args.model_max_length is not None and tokenizer.model_max_length < model_args.model_max_length:\\n        tokenizer.model_max_length = model_args.model_max_length  # enlarge the tokenizer max length\\n\\n    if model_args.add_tokens is not None:\\n        num_added_tokens = tokenizer.add_tokens(new_tokens=model_args.add_tokens, special_tokens=False)\\n        logger.info_rank0(\\\"Add tokens {} to tokenizer's vocabulary.\\\".format(\\\",\\\".join(model_args.add_tokens)))\\n        if num_added_tokens > 0 and not model_args.resize_vocab:\\n            model_args.resize_vocab = True\\n            logger.warning_rank0(\\\"New tokens have been added, changed `resize_vocab` to True.\\\")\\n\\n    if model_args.add_special_tokens is not None:\\n        num_added_special_tokens = tokenizer.add_tokens(new_tokens=model_args.add_special_tokens, special_tokens=True)\\n        logger.info_rank0(\\n            \\\"Add special tokens {} to tokenizer's vocabulary.\\\".format(\\\",\\\".join(model_args.add_special_tokens))\\n        )\\n        if num_added_special_tokens > 0 and not model_args.resize_vocab:\\n            model_args.resize_vocab = True\\n            logger.warning_rank0(\\\"New special tokens have been added, changed `resize_vocab` to True.\\\")\\n\\n\\ndef patch_processor(\\n    processor: \\\"ProcessorMixin\\\",\\n    tokenizer: \\\"PreTrainedTokenizer\\\",\\n    model_args: \\\"ModelArguments\\\",\\n) -> None:\\n    setattr(processor, \\\"tokenizer\\\", tokenizer)\\n    setattr(processor, \\\"image_max_pixels\\\", model_args.image_max_pixels)\\n    setattr(processor, \\\"image_min_pixels\\\", model_args.image_min_pixels)\\n    setattr(processor, \\\"image_do_pan_and_scan\\\", model_args.image_do_pan_and_scan)\\n    setattr(processor, \\\"crop_to_patches\\\", model_args.crop_to_patches)\\n    setattr(processor, \\\"video_max_pixels\\\", model_args.video_max_pixels)\\n    setattr(processor, \\\"video_min_pixels\\\", model_args.video_min_pixels)\\n    setattr(processor, \\\"video_fps\\\", model_args.video_fps)\\n    setattr(processor, \\\"video_maxlen\\\", model_args.video_maxlen)\\n    setattr(processor, \\\"use_audio_in_video\\\", model_args.use_audio_in_video)\\n    setattr(processor, \\\"audio_sampling_rate\\\", model_args.audio_sampling_rate)\\n\\n\\ndef patch_config(\\n    config: \\\"PretrainedConfig\\\",\\n    tokenizer: \\\"PreTrainedTokenizer\\\",\\n    model_args: \\\"ModelArguments\\\",\\n    init_kwargs: dict[str, Any],\\n    is_trainable: bool,\\n) -> None:\\n    if model_args.compute_dtype is None:  # priority: bf16 > fp16 > fp32\\n        if model_args.infer_dtype != \\\"auto\\\" and not is_trainable:\\n            model_args.compute_dtype = getattr(torch, model_args.infer_dtype)\\n        else:\\n            model_args.compute_dtype = infer_optim_dtype(model_dtype=getattr(config, \\\"torch_dtype\\\", None))\\n\\n    configure_attn_implementation(config, model_args)\\n    configure_rope(config, model_args)\\n    configure_longlora(config, model_args, is_trainable)\\n    configure_quantization(config, tokenizer, model_args, is_trainable, init_kwargs)\\n    configure_moe(config, model_args, is_trainable)\\n    configure_visual_model(config)\\n    configure_kv_cache(config, model_args, is_trainable)\\n\\n    if getattr(config, \\\"model_type\\\", None) == \\\"qwen\\\":\\n        setattr(config, \\\"use_flash_attn\\\", model_args.flash_attn == \\\"fa2\\\")\\n        for dtype_name, dtype in [(\\\"fp16\\\", torch.float16), (\\\"bf16\\\", torch.bfloat16), (\\\"fp32\\\", torch.float32)]:\\n            setattr(config, dtype_name, model_args.compute_dtype == dtype)\\n\\n    if getattr(config, \\\"model_type\\\", None) == \\\"minicpmo\\\":\\n        setattr(config, \\\"init_audio\\\", True)\\n        setattr(config, \\\"init_tts\\\", False)\\n\\n    # replace the top-k gating method\\n    if getattr(config, \\\"model_type\\\", None) == \\\"kimi_vl\\\" and is_trainable:\\n        setattr(config.text_config, \\\"topk_method\\\", \\\"greedy\\\")\\n\\n    architectures = getattr(config, \\\"architectures\\\", None)\\n    if isinstance(architectures, list) and \\\"InternVLChatModel\\\" in architectures:\\n        raise ValueError(\\n            \\\"Please download the internvl models in a Hugging Face\u2013compatible format \\\"\\n            \\\"(for example, https://huggingface.co/OpenGVLab/InternVL3-8B-hf).\\\"\\n        )\\n\\n    if isinstance(architectures, list) and \\\"LlavaLlamaForCausalLM\\\" in architectures:\\n        raise ValueError(\\\"Please download llava models with hf-compatible format: https://huggingface.co/llava-hf\\\")\\n\\n    if getattr(config, \\\"model_type\\\", None) == \\\"internlm3\\\" and not is_transformers_version_greater_than(\\\"4.47.1\\\"):\\n        raise RuntimeError(\\\"InternLM3 model requires transformers>=4.47.1, please upgrade it.\\\")\\n\\n    if getattr(config, \\\"model_type\\\", None) == \\\"lfm2_vl\\\" and not is_transformers_version_greater_than(\\\"4.58.0\\\"):\\n        raise RuntimeError(\\n            \\\"LFM2.5-VL model requires transformers>=4.58.0 or install from commit: \\\"\\n            \\\"pip install git+https://github.com/huggingface/transformers.git@3c2517727ce28a30f5044e01663ee204deb1cdbe\\\"\\n        )\\n\\n    if getattr(config, \\\"model_type\\\", None) == \\\"moss_vl\\\":\\n        check_version(\\\"transformers==4.57.1\\\", mandatory=True)\\n        check_version(\\\"torchcodec==0.7.0\\\", mandatory=True)\\n\\n    if getattr(config, \\\"model_type\\\", None) == \\\"qwen3_omni_moe\\\":\\n        patch_qwen3_omni_moe_thinker_text_sparse_moe_block()\\n\\n    # deepspeed zero3 is not compatible with low_cpu_mem_usage\\n    init_kwargs[\\\"low_cpu_mem_usage\\\"] = model_args.low_cpu_mem_usage and (not is_deepspeed_zero3_enabled())\\n\\n    # fsdp/deepspeed zero3 does not need device map\\n    if not (is_deepspeed_zero3_enabled() or is_fsdp_enabled()) and init_kwargs[\\\"low_cpu_mem_usage\\\"]:\\n        if \\\"device_map\\\" not in init_kwargs and model_args.device_map:\\n            init_kwargs[\\\"device_map\\\"] = model_args.device_map  # device map requires low_cpu_mem_usage=True\\n\\n        if init_kwargs.get(\\\"device_map\\\", None) == \\\"auto\\\":\\n            init_kwargs[\\\"offload_folder\\\"] = model_args.offload_folder\\n\\n\\ndef patch_model(\\n    model: \\\"PreTrainedModel\\\",\\n    tokenizer: \\\"PreTrainedTokenizer\\\",\\n    model_args: \\\"ModelArguments\\\",\\n    is_trainable: bool,\\n    add_valuehead: bool,\\n) -> None:\\n    gen_config = model.generation_config  # check and fix generation config\\n    if not gen_config.do_sample and (\\n        (gen_config.temperature is not None and gen_config.temperature != 1.0)\\n        or (gen_config.top_p is not None and gen_config.top_p != 1.0)\\n        or (gen_config.typical_p is not None and gen_config.typical_p != 1.0)\\n    ):\\n        gen_config.do_sample = True\\n\\n    if getattr(model.config, \\\"model_type\\\", None) not in [\\\"minicpmv\\\", \\\"minicpmo\\\"] and \\\"GenerationMixin\\\" not in str(\\n        model.generate.__func__\\n    ):\\n        model.generate = MethodType(GenerationMixin.generate, model)\\n\\n    if add_valuehead:\\n        prepare_valuehead_model(model)\\n\\n    if model_args.resize_vocab:\\n        # Pass the explicit list of newly added tokens so their exact embedding rows can be\\n        # located and initialized, even when they land in a model's pre-existing padding zone.\\n        new_tokens = (model_args.add_tokens or []) + (model_args.add_special_tokens or [])\\n\\n        resize_embedding_layer(\\n            model,\\n            tokenizer,\\n            new_tokens=new_tokens or None,\\n            new_special_tokens_config=getattr(model_args, \\\"_special_token_descriptions\\\", None),\\n            init_special_tokens=model_args.init_special_tokens,\\n        )\\n\\n    if is_trainable:\\n        if getattr(model.config, \\\"model_type\\\", None) == \\\"gemma3n\\\":\\n            setattr(model_args, \\\"disable_gradient_checkpointing\\\", True)\\n\\n        if getattr(model.config, \\\"model_type\\\", None) == \\\"youtu_vl\\\":\\n            patch_youtu_vl_model(model)\\n\\n        prepare_model_for_training(model, model_args)\\n        autocast_projector_dtype(model, model_args)\\n        add_z3_leaf_module(model)\\n\\n        if getattr(model.config, \\\"model_type\\\", None) in [\\n            \\\"qwen3_5\\\",\\n            \\\"qwen3_5_moe\\\",\\n            \\\"qwen3_5_moe_text\\\",\\n            \\\"qwen3_5_text\\\",\\n        ]:\\n            if is_torch_npu_available():\\n                patch_qwen3_5_forward_npu(model)\\n            elif is_torch_cuda_available() and model_args.flash_attn == \\\"fa2\\\":\\n                # this is the patch for packing/neat_packing for GPU GDN. And when setting packing, flash_attn must be fa2.\\n                patch_qwen3_5_forward_gpu(model)\\n\\n    if not model_args.use_unsloth:\\n        print_attn_implementation(model.config)\\n\\n    try:\\n        model.add_model_tags([\\\"llama-factory\\\"])\\n    except Exception:\\n        logger.warning_rank0(\\\"Cannot properly tag the model.\\\")\\n\\n\\ndef patch_valuehead_model(model: \\\"AutoModelForCausalLMWithValueHead\\\") -> None:\\n    def tie_weights(self: \\\"AutoModelForCausalLMWithValueHead\\\") -> None:\\n        if isinstance(self.pretrained_model, PreTrainedModel):\\n            self.pretrained_model.tie_weights()\\n\\n    def get_input_embeddings(self: \\\"AutoModelForCausalLMWithValueHead\\\") -> torch.nn.Module:\\n        if isinstance(self.pretrained_model, PreTrainedModel):\\n            return self.pretrained_model.get_input_embeddings()\\n\\n    def get_output_embeddings(self: \\\"AutoModelForCausalLMWithValueHead\\\") -> torch.nn.Module:\\n        if isinstance(self.pretrained_model, PreTrainedModel):\\n            return self.pretrained_model.get_output_embeddings()\\n\\n    def create_or_update_model_card(self: \\\"AutoModelForCausalLMWithValueHead\\\", output_dir: str) -> None:\\n        if isinstance(self.pretrained_model, PeftModel):\\n            self.pretrained_model.create_or_update_model_card(output_dir)\\n\\n    def get_rope_index_func(self: \\\"AutoModelForCausalLMWithValueHead\\\"):\\n        if isinstance(self.pretrained_model, PeftModel):\\n            base_model = self.pretrained_model.base_model.model\\n        else:\\n            base_model = self.pretrained_model\\n\\n        if base_model and hasattr(base_model, \\\"get_rope_index\\\"):\\n            return base_model.get_rope_index\\n        elif base_model and hasattr(base_model, \\\"model\\\") and hasattr(base_model.model, \\\"get_rope_index\\\"):\\n            return base_model.model.get_rope_index\\n        else:\\n            return None\\n\\n    ignore_modules = [name for name, _ in model.named_parameters() if \\\"pretrained_model\\\" in name]\\n    setattr(model, \\\"_keys_to_ignore_on_save\\\", ignore_modules)\\n    setattr(model, \\\"tie_weights\\\", MethodType(tie_weights, model))\\n    setattr(model, \\\"get_input_embeddings\\\", MethodType(get_input_embeddings, model))\\n    setattr(model, \\\"get_output_embeddings\\\", MethodType(get_output_embeddings, model))\\n    setattr(model, \\\"get_rope_index\\\", get_rope_index_func(model))\\n    setattr(model, \\\"create_or_update_model_card\\\", MethodType(create_or_update_model_card, model))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/muon/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d3d8af7d3e2a9eceafc91afc6ad367485c96c636eb8f27c86c6dcdf88bc727ad\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .muon import Muon\\n\\n\\n__all__ = [\\\"Muon\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/muon/muon.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dc30cd84142fe2f80d0d4728648e9270550907bd6f4bfd7b1becffd0215910ea\",\"content\":\"# Copyright 2025 Moonshot AI and the LlamaFactory team.\\n#\\n# This code is based on the MoonshotAI's Moonlight library.\\n# https://github.com/MoonshotAI/Moonlight/blob/master/examples/toy_train.py\\n# and the Keller Jordan's Muon library.\\n# https://github.com/KellerJordan/Muon/blob/master/muon.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n#\\n# MIT License\\n#\\n# Copyright (c) 2025 Moonshot AI\\n# Copyright (c) 2024 Keller Jordan\\n#\\n# Permission is hereby granted, free of charge, to any person obtaining a copy\\n# of this software and associated documentation files (the \\\"Software\\\"), to deal\\n# in the Software without restriction, including without limitation the rights\\n# to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\\n# copies of the Software, and to permit persons to whom the Software is\\n# furnished to do so, subject to the following conditions:\\n#\\n# The above copyright notice and this permission notice shall be included in all\\n# copies or substantial portions of the Software.\\n#\\n# THE SOFTWARE IS PROVIDED \\\"AS IS\\\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\\n# IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\\n# FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\\n# AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\\n# LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\\n# OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\\n# SOFTWARE.\\n\\nimport math\\n\\nimport torch\\n\\n\\ndef zeropower_via_newtonschulz5(G: \\\"torch.Tensor\\\", steps: int) -> \\\"torch.Tensor\\\":\\n    \\\"\\\"\\\"Newton-Schulz iteration to compute the zeroth power / orthogonalization of G.\\n\\n    We opt to use a quintic iteration whose coefficients are selected to maximize the slope at zero.\\n    For the purpose of minimizing steps, it turns out to be empirically effective to keep increasing\\n    the slope at zero even beyond the point where the iteration no longer converges all the way to\\n    one everywhere on the interval. This iteration therefore does not produce UV^T but rather something\\n    like US'V^T where S' is diagonal with S_{ii}' ~ Uniform(0.5, 1.5), which turns out not to hurt model\\n    performance at all relative to UV^T, where USV^T = G is the SVD.\\n    \\\"\\\"\\\"\\n    assert len(G.shape) == 2\\n    a, b, c = (3.4445, -4.7750, 2.0315)\\n    X = G.bfloat16()\\n    if G.size(0) > G.size(1):\\n        X = X.T\\n    # Ensure spectral norm is at most 1\\n    X = X / (X.norm() + 1e-7)\\n    # Perform the NS iterations\\n    for _ in range(steps):\\n        A = X @ X.T\\n        B = b * A + c * A @ A  # adapted from suggestion by @jxbz, @leloykun, and @YouJiacheng\\n        X = a * X + B @ X\\n\\n    if G.size(0) > G.size(1):\\n        X = X.T\\n    return X\\n\\n\\nclass Muon(torch.optim.Optimizer):\\n    \\\"\\\"\\\"Muon - MomentUm Orthogonalized by Newton-schulz.\\n\\n    Muon internally runs standard SGD-momentum, and then performs an orthogonalization post-\\n    processing step, in which each 2D parameter's update is replaced with the nearest orthogonal\\n    matrix. To efficiently orthogonalize each update, we use a Newton-Schulz iteration, which has\\n    the advantage that it can be stably run in bfloat16 on the GPU.\\n\\n    Some warnings:\\n    - We believe this optimizer is unlikely to work well for training with small batch size.\\n    - We believe it may not work well for finetuning pretrained models, but we haven't tested this.\\n\\n    Arguments:\\n        muon_params: The parameters to be optimized by Muon.\\n        lr: The learning rate. The updates will have spectral norm of `lr`. (0.02 is a good default)\\n        momentum: The momentum used by the internal SGD. (0.95 is a good default)\\n        nesterov: Whether to use Nesterov-style momentum in the internal SGD. (recommended)\\n        ns_steps: The number of Newton-Schulz iterations to run. (6 is probably always enough)\\n        adamw_params: The parameters to be optimized by AdamW. Any parameters in `muon_params` which are\\n        {0, 1}-D or are detected as being the embed or lm_head will be optimized by AdamW as well.\\n        adamw_lr: The learning rate for the internal AdamW.\\n        adamw_betas: The betas for the internal AdamW.\\n        adamw_eps: The epsilon for the internal AdamW.\\n        adamw_wd: The weight decay for the internal AdamW.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        lr=1e-3,\\n        wd=0.1,\\n        muon_params=None,\\n        momentum=0.95,\\n        nesterov=True,\\n        ns_steps=5,\\n        adamw_params=None,\\n        adamw_betas=(0.9, 0.95),\\n        adamw_eps=1e-8,\\n    ):\\n        defaults = dict(\\n            lr=lr,\\n            wd=wd,\\n            momentum=momentum,\\n            nesterov=nesterov,\\n            ns_steps=ns_steps,\\n            adamw_betas=adamw_betas,\\n            adamw_eps=adamw_eps,\\n        )\\n\\n        params = list(muon_params)\\n        adamw_params = list(adamw_params) if adamw_params is not None else []\\n        params.extend(adamw_params)\\n        super().__init__(params, defaults)\\n        # Sort parameters into those for which we will use Muon, and those for which we will not\\n        for p in muon_params:\\n            # Use Muon for every parameter in muon_params which is >= 2D and doesn't look like an embedding or head layer\\n            assert p.ndim == 2, p.ndim\\n            self.state[p][\\\"use_muon\\\"] = True\\n        for p in adamw_params:\\n            # Do not use Muon for parameters in adamw_params\\n            self.state[p][\\\"use_muon\\\"] = False\\n\\n    def adjust_lr_for_muon(self, lr: float, param_shape: list[int]) -> float:\\n        A, B = param_shape[:2]\\n        # We adjust the learning rate and weight decay based on the size of the parameter matrix\\n        # as describted in the paper\\n        adjusted_ratio = 0.2 * math.sqrt(max(A, B))\\n        adjusted_lr = lr * adjusted_ratio\\n        return adjusted_lr\\n\\n    def step(self, closure=None):\\n        \\\"\\\"\\\"Perform a single optimization step.\\n\\n        Args:\\n            closure (Callable, optional): A closure that reevaluates the model\\n                and returns the loss.\\n        \\\"\\\"\\\"\\n        loss = None\\n        if closure is not None:\\n            with torch.enable_grad():\\n                loss = closure()\\n\\n        for group in self.param_groups:\\n            # Muon loop\\n            params = [p for p in group[\\\"params\\\"] if self.state[p][\\\"use_muon\\\"]]\\n            lr = group[\\\"lr\\\"]\\n            wd = group[\\\"wd\\\"]\\n            momentum = group[\\\"momentum\\\"]\\n\\n            # generate weight updates in distributed fashion\\n            for p in params:\\n                # sanity check\\n                g = p.grad\\n                if g is None:\\n                    continue\\n                if g.ndim > 2:\\n                    g = g.view(g.size(0), -1)\\n                assert g is not None\\n\\n                # calc update\\n                state = self.state[p]\\n                if \\\"momentum_buffer\\\" not in state:\\n                    state[\\\"momentum_buffer\\\"] = torch.zeros_like(g)\\n                buf = state[\\\"momentum_buffer\\\"]\\n                buf.mul_(momentum).add_(g)\\n                if group[\\\"nesterov\\\"]:\\n                    g = g.add(buf, alpha=momentum)\\n                else:\\n                    g = buf\\n                u = zeropower_via_newtonschulz5(g, steps=group[\\\"ns_steps\\\"])\\n\\n                # scale update\\n                adjusted_lr = self.adjust_lr_for_muon(lr, p.shape)\\n\\n                # apply weight decay\\n                p.data.mul_(1 - lr * wd)\\n\\n                # apply update\\n                p.data.add_(u, alpha=-adjusted_lr)\\n\\n            # Adam backup\\n            params = [p for p in group[\\\"params\\\"] if not self.state[p][\\\"use_muon\\\"]]\\n            lr = group[\\\"lr\\\"]\\n            beta1, beta2 = group[\\\"adamw_betas\\\"]\\n            eps = group[\\\"adamw_eps\\\"]\\n            weight_decay = group[\\\"wd\\\"]\\n\\n            for p in params:\\n                g = p.grad\\n                if g is None:\\n                    continue\\n                state = self.state[p]\\n                if \\\"step\\\" not in state:\\n                    state[\\\"step\\\"] = 0\\n                    state[\\\"moment1\\\"] = torch.zeros_like(g)\\n                    state[\\\"moment2\\\"] = torch.zeros_like(g)\\n                state[\\\"step\\\"] += 1\\n                step = state[\\\"step\\\"]\\n                buf1 = state[\\\"moment1\\\"]\\n                buf2 = state[\\\"moment2\\\"]\\n                buf1.lerp_(g, 1 - beta1)\\n                buf2.lerp_(g.square(), 1 - beta2)\\n\\n                g = buf1 / (eps + buf2.sqrt())\\n\\n                bias_correction1 = 1 - beta1**step\\n                bias_correction2 = 1 - beta2**step\\n                scale = bias_correction1 / bias_correction2**0.5\\n                p.data.mul_(1 - lr * weight_decay)\\n                p.data.add_(g, alpha=-lr / scale)\\n\\n        return loss\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/chunk_delta_h.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2e9e3fcefb6eccd050473cd2611b96f07a3aa8cc7838613232d8ec8ec54ea0a2\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nfrom typing import Optional\\n\\nimport torch\\nimport triton\\nimport triton.language as tl\\n\\nfrom .utils import get_autotune_config, get_npu_properties, prepare_chunk_indices, prepare_chunk_offsets\\n\\n\\nCUBE_CORE_NUM = get_npu_properties()[\\\"num_aicore\\\"]\\n\\n\\n@triton.heuristics(\\n    {\\n        \\\"USE_G\\\": lambda args: args[\\\"g\\\"] is not None,\\n        \\\"USE_GK\\\": lambda args: args[\\\"gk\\\"] is not None,\\n        \\\"USE_INITIAL_STATE\\\": lambda args: args[\\\"h0\\\"] is not None,\\n        \\\"STORE_FINAL_STATE\\\": lambda args: args[\\\"ht\\\"] is not None,\\n        \\\"SAVE_NEW_VALUE\\\": lambda args: args[\\\"v_new\\\"] is not None,\\n        \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None,\\n    }\\n)\\n@triton.autotune(\\n    configs=get_autotune_config(multibuffer_list=(False,)),\\n    key=[\\\"H\\\", \\\"K\\\", \\\"V\\\", \\\"BT\\\"],\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_gated_delta_rule_fwd_kernel_h_blockdim64(\\n    k,\\n    v,\\n    w,\\n    v_new,\\n    g,\\n    gk,\\n    h,\\n    h0,\\n    ht,\\n    cu_seqlens,\\n    chunk_offsets,\\n    T,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    V: tl.constexpr,\\n    BT: tl.constexpr,\\n    BV: tl.constexpr,\\n    NT: tl.constexpr,\\n    USE_G: tl.constexpr,\\n    USE_GK: tl.constexpr,\\n    USE_INITIAL_STATE: tl.constexpr,\\n    STORE_FINAL_STATE: tl.constexpr,\\n    SAVE_NEW_VALUE: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    T_all = T\\n    NT_all = NT\\n    i_v, i_nh = tl.program_id(0), tl.program_id(1)\\n    i_n, i_h = i_nh // H, i_nh % H\\n    if IS_VARLEN:\\n        bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n        T = eos - bos\\n        NT = tl.cdiv(T, BT)\\n        boh = tl.load(chunk_offsets + i_n).to(tl.int32)\\n    else:\\n        bos, eos = i_n * T, i_n * T + T\\n        NT = tl.cdiv(T, BT)\\n        boh = i_n * NT\\n\\n    # Initialize hidden states\\n    b_h1 = tl.zeros([64, BV], dtype=tl.float32)\\n    if K > 64:\\n        b_h2 = tl.zeros([64, BV], dtype=tl.float32)\\n    if K > 128:\\n        b_h3 = tl.zeros([64, BV], dtype=tl.float32)\\n    if K > 192:\\n        b_h4 = tl.zeros([64, BV], dtype=tl.float32)\\n\\n    if IS_VARLEN:\\n        v = v + (i_h * T_all + bos) * V\\n        k = k + (i_h * T_all + bos) * K\\n        w = w + (i_h * T_all + bos) * K\\n        g = g + i_h * T_all + bos\\n        h = h + (i_h * NT_all + boh) * K * V\\n        if SAVE_NEW_VALUE:\\n            v_new_base = v_new + (i_h * T_all + bos) * V\\n    else:\\n        v = v + (i_n * H + i_h) * T * V\\n        k = k + (i_n * H + i_h) * T * K\\n        w = w + (i_n * H + i_h) * T * K\\n        g = g + (i_n * H + i_h) * T\\n        h = h + (i_n * H + i_h) * NT * K * V\\n        if SAVE_NEW_VALUE:\\n            v_new_base = v_new + (i_n * H + i_h) * T * V\\n\\n    if USE_INITIAL_STATE:\\n        h0_ptr = h0 + i_nh * K * V\\n    if STORE_FINAL_STATE:\\n        ht_ptr = ht + i_nh * K * V\\n\\n    # Load initial state\\n    if USE_INITIAL_STATE:\\n        p_h0_1 = tl.make_block_ptr(h0_ptr, (K, V), (V, 1), (0, i_v * BV), (64, BV), (1, 0))\\n        b_h1 += tl.load(p_h0_1, boundary_check=(0, 1)).to(tl.float32)\\n        if K > 64:\\n            p_h0_2 = tl.make_block_ptr(h0_ptr, (K, V), (V, 1), (64, i_v * BV), (64, BV), (1, 0))\\n            b_h2 += tl.load(p_h0_2, boundary_check=(0, 1)).to(tl.float32)\\n        if K > 128:\\n            p_h0_3 = tl.make_block_ptr(h0_ptr, (K, V), (V, 1), (128, i_v * BV), (64, BV), (1, 0))\\n            b_h3 += tl.load(p_h0_3, boundary_check=(0, 1)).to(tl.float32)\\n        if K > 192:\\n            p_h0_4 = tl.make_block_ptr(h0_ptr, (K, V), (V, 1), (192, i_v * BV), (64, BV), (1, 0))\\n            b_h4 += tl.load(p_h0_4, boundary_check=(0, 1)).to(tl.float32)\\n\\n    # Main recurrence over chunks\\n    for i_t in range(NT):\\n        # Store current hidden state h_t\\n        p_h1 = tl.make_block_ptr(h + i_t * K * V, (K, V), (V, 1), (0, i_v * BV), (64, BV), (1, 0))\\n        tl.store(p_h1, b_h1.to(p_h1.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 64:\\n            p_h2 = tl.make_block_ptr(h + i_t * K * V, (K, V), (V, 1), (64, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_h2, b_h2.to(p_h2.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 128:\\n            p_h3 = tl.make_block_ptr(h + i_t * K * V, (K, V), (V, 1), (128, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_h3, b_h3.to(p_h3.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 192:\\n            p_h4 = tl.make_block_ptr(h + i_t * K * V, (K, V), (V, 1), (192, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_h4, b_h4.to(p_h4.dtype.element_ty), boundary_check=(0, 1))\\n\\n        # Compute v_residual = v - w @ h\\n        p_w = tl.make_block_ptr(w, (T, K), (K, 1), (i_t * BT, 0), (BT, 64), (1, 0))\\n        b_w = tl.load(p_w, boundary_check=(0, 1))\\n        b_v = tl.dot(b_w, b_h1.to(b_w.dtype))\\n        if K > 64:\\n            p_w = tl.make_block_ptr(w, (T, K), (K, 1), (i_t * BT, 64), (BT, 64), (1, 0))\\n            b_w = tl.load(p_w, boundary_check=(0, 1))\\n            b_v += tl.dot(b_w, b_h2.to(b_w.dtype))\\n        if K > 128:\\n            p_w = tl.make_block_ptr(w, (T, K), (K, 1), (i_t * BT, 128), (BT, 64), (1, 0))\\n            b_w = tl.load(p_w, boundary_check=(0, 1))\\n            b_v += tl.dot(b_w, b_h3.to(b_w.dtype))\\n        if K > 192:\\n            p_w = tl.make_block_ptr(w, (T, K), (K, 1), (i_t * BT, 192), (BT, 64), (1, 0))\\n            b_w = tl.load(p_w, boundary_check=(0, 1))\\n            b_v += tl.dot(b_w, b_h4.to(b_w.dtype))\\n\\n        p_v = tl.make_block_ptr(v, (T, V), (V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n        b_v = tl.load(p_v, boundary_check=(0, 1)) - b_v\\n\\n        if SAVE_NEW_VALUE:\\n            p_v_new = tl.make_block_ptr(v_new_base, (T, V), (V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n            tl.store(p_v_new, b_v.to(p_v_new.dtype.element_ty), boundary_check=(0, 1))\\n\\n        last_idx = min((i_t + 1) * BT, T) - 1\\n\\n        # Apply output gate g\\n        if USE_G:\\n            m_t = (i_t * BT + tl.arange(0, BT)).to(tl.float32) < T\\n            b_g_last = tl.load(g + last_idx)\\n            p_g = tl.make_block_ptr(g, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n            b_g = tl.load(p_g, boundary_check=(0,))\\n            b_v *= (m_t * tl.exp(b_g_last - b_g))[:, None]\\n            b_g_last_exp = tl.exp(b_g_last)\\n            b_h1 *= b_g_last_exp\\n            if K > 64:\\n                b_h2 *= b_g_last_exp\\n            if K > 128:\\n                b_h3 *= b_g_last_exp\\n            if K > 192:\\n                b_h4 *= b_g_last_exp\\n\\n        # Apply key gate gk\\n        if USE_GK:\\n            o_k1 = tl.arange(0, 64).to(tl.float32)\\n            gk_base_ptr = gk + (i_n * H + i_h) * T * K\\n            b_gk_last1 = tl.load(gk_base_ptr + last_idx * K + o_k1, mask=(o_k1 < K), other=0.0)\\n            b_h1 *= tl.exp(b_gk_last1)[:, None]\\n            if K > 64:\\n                o_k2 = 64 + o_k1\\n                b_gk_last2 = tl.load(gk_base_ptr + last_idx * K + o_k2, mask=(o_k2 < K), other=0.0)\\n                b_h2 *= tl.exp(b_gk_last2)[:, None]\\n            if K > 128:\\n                o_k3 = 128 + o_k1\\n                b_gk_last3 = tl.load(gk_base_ptr + last_idx * K + o_k3, mask=(o_k3 < K), other=0.0)\\n                b_h3 *= tl.exp(b_gk_last3)[:, None]\\n            if K > 192:\\n                o_k4 = 192 + o_k1\\n                b_gk_last4 = tl.load(gk_base_ptr + last_idx * K + o_k4, mask=(o_k4 < K), other=0.0)\\n                b_h4 *= tl.exp(b_gk_last4)[:, None]\\n\\n        b_v = b_v.to(k.dtype.element_ty)\\n\\n        # Update hidden state: h += k @ v\\n        p_k = tl.make_block_ptr(k, (K, T), (1, K), (0, i_t * BT), (64, BT), (0, 1))\\n        b_k = tl.load(p_k, boundary_check=(0, 1))\\n        if USE_GK:\\n            p_gk = tl.make_block_ptr(gk_base_ptr, (K, T), (1, K), (0, i_t * BT), (64, BT), (0, 1))\\n            b_k = (b_k * tl.exp(b_gk_last1[:, None] - tl.load(p_gk, boundary_check=(0, 1)))).to(b_k.dtype)\\n        b_h1 += tl.dot(b_k, b_v)\\n\\n        if K > 64:\\n            p_k = tl.make_block_ptr(k, (K, T), (1, K), (64, i_t * BT), (64, BT), (0, 1))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n            if USE_GK:\\n                p_gk = tl.make_block_ptr(gk_base_ptr, (K, T), (1, K), (64, i_t * BT), (64, BT), (0, 1))\\n                b_k = (b_k * tl.exp(b_gk_last2[:, None] - tl.load(p_gk, boundary_check=(0, 1)))).to(b_k.dtype)\\n            b_h2 += tl.dot(b_k, b_v)\\n\\n        if K > 128:\\n            p_k = tl.make_block_ptr(k, (K, T), (1, K), (128, i_t * BT), (64, BT), (0, 1))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n            if USE_GK:\\n                p_gk = tl.make_block_ptr(gk_base_ptr, (K, T), (1, K), (128, i_t * BT), (64, BT), (0, 1))\\n                b_k = (b_k * tl.exp(b_gk_last3[:, None] - tl.load(p_gk, boundary_check=(0, 1)))).to(b_k.dtype)\\n            b_h3 += tl.dot(b_k, b_v)\\n\\n        if K > 192:\\n            p_k = tl.make_block_ptr(k, (K, T), (1, K), (192, i_t * BT), (64, BT), (0, 1))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n            if USE_GK:\\n                p_gk = tl.make_block_ptr(gk_base_ptr, (K, T), (1, K), (192, i_t * BT), (64, BT), (0, 1))\\n                b_k = (b_k * tl.exp(b_gk_last4[:, None] - tl.load(p_gk, boundary_check=(0, 1)))).to(b_k.dtype)\\n            b_h4 += tl.dot(b_k, b_v)\\n\\n    # Store final state\\n    if STORE_FINAL_STATE:\\n        p_ht = tl.make_block_ptr(ht_ptr, (K, V), (V, 1), (0, i_v * BV), (64, BV), (1, 0))\\n        tl.store(p_ht, b_h1.to(p_ht.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 64:\\n            p_ht = tl.make_block_ptr(ht_ptr, (K, V), (V, 1), (64, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_ht, b_h2.to(p_ht.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 128:\\n            p_ht = tl.make_block_ptr(ht_ptr, (K, V), (V, 1), (128, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_ht, b_h3.to(p_ht.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 192:\\n            p_ht = tl.make_block_ptr(ht_ptr, (K, V), (V, 1), (192, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_ht, b_h4.to(p_ht.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\ndef chunk_gated_delta_rule_fwd_h(\\n    k: torch.Tensor,\\n    w: torch.Tensor,\\n    u: torch.Tensor,\\n    g: Optional[torch.Tensor] = None,\\n    gk: Optional[torch.Tensor] = None,\\n    initial_state: Optional[torch.Tensor] = None,\\n    output_final_state: bool = False,\\n    chunk_size: int = 64,  # default:64\\n    save_new_value: bool = True,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n) -> tuple[torch.Tensor, torch.Tensor]:\\n    B, T, H, K, V = *k.shape, u.shape[-1]\\n    BT = chunk_size\\n\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, chunk_size) if cu_seqlens is not None else None\\n    # N: the actual number of sequences in the batch with either equal or variable lengths\\n    if cu_seqlens is None:\\n        N, NT, chunk_offsets = B, triton.cdiv(T, BT), None\\n    else:\\n        N, NT, chunk_offsets = len(cu_seqlens) - 1, len(chunk_indices), prepare_chunk_offsets(cu_seqlens, BT)\\n    assert K <= 256, \\\"current kernel does not support head dimension larger than 256.\\\"\\n\\n    h = k.new_empty(B, NT, H, K, V).permute(0, 2, 1, 3, 4).contiguous()\\n    final_state = k.new_empty(N, H, K, V, dtype=torch.float32) if output_final_state else None\\n\\n    BV = 128\\n\\n    v_new = torch.empty_like(u).permute(0, 2, 1, 3).contiguous() if save_new_value else None\\n    k = k.permute(0, 2, 1, 3).contiguous()\\n    w = w.permute(0, 2, 1, 3).contiguous()\\n    u = u.permute(0, 2, 1, 3).contiguous()\\n    g = g.permute(0, 2, 1).contiguous()\\n    chunk_gated_delta_rule_fwd_kernel_h_blockdim64[(triton.cdiv(V, BV), N * H)](\\n        k=k,\\n        v=u,\\n        w=w,\\n        v_new=v_new,\\n        g=g,\\n        gk=gk,\\n        h=h,\\n        h0=initial_state,\\n        ht=final_state,\\n        cu_seqlens=cu_seqlens,\\n        chunk_offsets=chunk_offsets,\\n        T=T,\\n        H=H,\\n        K=K,\\n        V=V,\\n        BT=BT,\\n        BV=BV,\\n        NT=NT,\\n    )\\n    h = h.permute(0, 2, 1, 3, 4).contiguous()\\n    v_new = v_new.permute(0, 2, 1, 3).contiguous()\\n    return h, v_new, final_state\\n\\n\\n@triton.heuristics(\\n    {\\n        \\\"USE_G\\\": lambda args: args[\\\"g\\\"] is not None,\\n        \\\"USE_GK\\\": lambda args: args[\\\"gk\\\"] is not None,\\n        \\\"USE_INITIAL_STATE\\\": lambda args: args[\\\"dh0\\\"] is not None,\\n        \\\"USE_FINAL_STATE_GRADIENT\\\": lambda args: args[\\\"dht\\\"] is not None,\\n        \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None,\\n    }\\n)\\n@triton.autotune(\\n    configs=get_autotune_config(multibuffer_list=(True, False)),\\n    key=[\\\"H\\\", \\\"K\\\", \\\"V\\\", \\\"BT\\\", \\\"BV\\\", \\\"USE_G\\\", \\\"IS_VARLEN\\\"],\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_gated_delta_rule_bwd_kernel_dhu_blockdim64(\\n    q,\\n    k,\\n    w,\\n    g,\\n    gk,\\n    dht,\\n    dh0,\\n    do,\\n    dh,\\n    dv,\\n    dv2,\\n    cu_seqlens,\\n    chunk_offsets,\\n    scale,\\n    T,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    V: tl.constexpr,\\n    BT: tl.constexpr,\\n    BV: tl.constexpr,\\n    USE_G: tl.constexpr,\\n    USE_GK: tl.constexpr,\\n    USE_INITIAL_STATE: tl.constexpr,\\n    USE_FINAL_STATE_GRADIENT: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    T_all = T\\n    i_v, i_nh = tl.program_id(0), tl.program_id(1)\\n    i_n, i_h = i_nh // H, i_nh % H\\n    if IS_VARLEN:\\n        bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n        T = eos - bos\\n        NT = tl.cdiv(T, BT)\\n        boh = tl.load(chunk_offsets + i_n).to(tl.int32)\\n    else:\\n        bos, eos = i_n * T, i_n * T + T\\n        NT = tl.cdiv(T, BT)\\n        boh = i_n * NT\\n\\n    b_dh1 = tl.zeros([64, BV], dtype=tl.float32)\\n    if K > 64:\\n        b_dh2 = tl.zeros([64, BV], dtype=tl.float32)\\n    if K > 128:\\n        b_dh3 = tl.zeros([64, BV], dtype=tl.float32)\\n    if K > 192:\\n        b_dh4 = tl.zeros([64, BV], dtype=tl.float32)\\n\\n    q += (bos * H + i_h) * K\\n    k += (bos * H + i_h) * K\\n    w += (bos * H + i_h) * K\\n    do += (bos * H + i_h) * V\\n    dv += (bos * H + i_h) * V\\n    dv2 += (bos * H + i_h) * V\\n    dh += (boh * H + i_h) * K * V\\n    if USE_GK:\\n        gk += (bos * H + i_h) * K\\n\\n    if USE_INITIAL_STATE:\\n        dh0 += i_nh * K * V\\n    if USE_FINAL_STATE_GRADIENT:\\n        dht += i_nh * K * V\\n\\n    stride_v = H * V\\n    stride_h = H * K * V\\n    stride_k = H * K\\n\\n    if USE_FINAL_STATE_GRADIENT:\\n        p_dht1 = tl.make_block_ptr(dht, (K, V), (V, 1), (0, i_v * BV), (64, BV), (1, 0))\\n        b_dh1 += tl.load(p_dht1, boundary_check=(0, 1))\\n        if K > 64:\\n            p_dht2 = tl.make_block_ptr(dht, (K, V), (V, 1), (64, i_v * BV), (64, BV), (1, 0))\\n            b_dh2 += tl.load(p_dht2, boundary_check=(0, 1))\\n        if K > 128:\\n            p_dht3 = tl.make_block_ptr(dht, (K, V), (V, 1), (128, i_v * BV), (64, BV), (1, 0))\\n            b_dh3 += tl.load(p_dht3, boundary_check=(0, 1))\\n        if K > 192:\\n            p_dht4 = tl.make_block_ptr(dht, (K, V), (V, 1), (192, i_v * BV), (64, BV), (1, 0))\\n            b_dh4 += tl.load(p_dht4, boundary_check=(0, 1))\\n\\n    for i_t in range(NT - 1, -1, -1):\\n        p_dh1 = tl.make_block_ptr(dh + i_t * stride_h, (K, V), (V, 1), (0, i_v * BV), (64, BV), (1, 0))\\n        tl.store(p_dh1, b_dh1.to(p_dh1.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 64:\\n            p_dh2 = tl.make_block_ptr(dh + i_t * stride_h, (K, V), (V, 1), (64, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_dh2, b_dh2.to(p_dh2.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 128:\\n            p_dh3 = tl.make_block_ptr(dh + i_t * stride_h, (K, V), (V, 1), (128, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_dh3, b_dh3.to(p_dh3.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 192:\\n            p_dh4 = tl.make_block_ptr(dh + i_t * stride_h, (K, V), (V, 1), (192, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_dh4, b_dh4.to(p_dh4.dtype.element_ty), boundary_check=(0, 1))\\n\\n        last_idx = min((i_t + 1) * BT, T) - 1\\n        if USE_G:\\n            if IS_VARLEN:\\n                bos_g = i_h * T_all + bos\\n            else:\\n                bos_g = (i_n * H + i_h) * T_all\\n            bg_last = tl.load(g + bos_g + last_idx)\\n            bg_last_exp = tl.exp(bg_last)\\n            p_g = tl.make_block_ptr(\\n                base=g + bos_g, shape=(T,), strides=(1,), offsets=(i_t * BT,), block_shape=(BT,), order=(0,)\\n            )\\n            b_g = tl.load(p_g, boundary_check=(0,))\\n            b_g_exp = tl.exp(b_g)\\n\\n        p_dv = tl.make_block_ptr(dv, (T, V), (stride_v, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n        p_dv2 = tl.make_block_ptr(dv2, (T, V), (stride_v, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n        p_do = tl.make_block_ptr(do, (T, V), (stride_v, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n\\n        b_do = tl.load(p_do, boundary_check=(0, 1))\\n\\n        # Update dv\\n        p_k = tl.make_block_ptr(k, (T, K), (stride_k, 1), (i_t * BT, 0), (BT, 64), (1, 0))\\n        b_k = tl.load(p_k, boundary_check=(0, 1))\\n        if USE_GK:\\n            o_k1 = tl.arange(0, 64)\\n            b_gk_last1 = tl.load(gk + last_idx * H * K + o_k1, mask=(o_k1 < K), other=0.0)\\n        b_dv = tl.dot(b_k, b_dh1.to(b_k.dtype))\\n\\n        if K > 64:\\n            p_k = tl.make_block_ptr(k, (T, K), (stride_k, 1), (i_t * BT, 64), (BT, 64), (1, 0))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n            if USE_GK:\\n                o_k2 = 64 + o_k1\\n                b_gk_last2 = tl.load(gk + last_idx * H * K + o_k2, mask=(o_k2 < K), other=0.0)\\n            b_dv += tl.dot(b_k, b_dh2.to(b_k.dtype))\\n\\n        if K > 128:\\n            p_k = tl.make_block_ptr(k, (T, K), (stride_k, 1), (i_t * BT, 128), (BT, 64), (1, 0))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n            if USE_GK:\\n                o_k3 = 128 + o_k1\\n                b_gk_last3 = tl.load(gk + last_idx * H * K + o_k3, mask=(o_k3 < K), other=0.0)\\n            b_dv += tl.dot(b_k, b_dh3.to(b_k.dtype))\\n\\n        if K > 192:\\n            p_k = tl.make_block_ptr(k, (T, K), (stride_k, 1), (i_t * BT, 192), (BT, 64), (1, 0))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n            if USE_GK:\\n                o_k4 = 192 + o_k1\\n                b_gk_last4 = tl.load(gk + last_idx * H * K + o_k4, mask=(o_k4 < K), other=0.0)\\n            b_dv += tl.dot(b_k, b_dh4.to(b_k.dtype))\\n\\n        if USE_G:\\n            m_t = (i_t * BT + tl.arange(0, BT)).to(tl.float32) < T\\n            b_dv *= (m_t * tl.exp(bg_last - b_g))[:, None]\\n        b_dv += tl.load(p_dv, boundary_check=(0, 1))\\n\\n        tl.store(p_dv2, b_dv.to(p_dv.dtype.element_ty), boundary_check=(0, 1))\\n        # Update dh\\n        p_w = tl.make_block_ptr(w, (K, T), (1, stride_k), (0, i_t * BT), (64, BT), (0, 1))\\n        p_q = tl.make_block_ptr(q, (K, T), (1, stride_k), (0, i_t * BT), (64, BT), (0, 1))\\n        b_w = tl.load(p_w, boundary_check=(0, 1))\\n        b_q = tl.load(p_q, boundary_check=(0, 1))\\n        if USE_G:\\n            b_dh1 *= bg_last_exp\\n            b_q = b_q * b_g_exp[None, :]\\n        if USE_GK:\\n            b_dh1 *= tl.exp(b_gk_last1[:, None])\\n        b_dh1 += tl.dot(b_q.to(b_q.dtype), b_do.to(b_q.dtype)) * scale - tl.dot(b_w, b_dv.to(b_w.dtype))\\n        if K > 64:\\n            p_q = tl.make_block_ptr(q, (K, T), (1, stride_k), (64, i_t * BT), (64, BT), (0, 1))\\n            p_w = tl.make_block_ptr(w, (K, T), (1, stride_k), (64, i_t * BT), (64, BT), (0, 1))\\n            b_q = tl.load(p_q, boundary_check=(0, 1))\\n            b_w = tl.load(p_w, boundary_check=(0, 1))\\n            if USE_G:\\n                b_dh2 *= bg_last_exp\\n                b_q = b_q * b_g_exp[None, :]\\n            if USE_GK:\\n                b_dh2 *= tl.exp(b_gk_last2[:, None])\\n            b_dh2 += tl.dot(b_q.to(b_q.dtype), b_do.to(b_q.dtype)) * scale - tl.dot(b_w, b_dv.to(b_w.dtype))\\n        if K > 128:\\n            p_q = tl.make_block_ptr(q, (K, T), (1, stride_k), (128, i_t * BT), (64, BT), (0, 1))\\n            p_w = tl.make_block_ptr(w, (K, T), (1, stride_k), (128, i_t * BT), (64, BT), (0, 1))\\n            b_q = tl.load(p_q, boundary_check=(0, 1))\\n            b_w = tl.load(p_w, boundary_check=(0, 1))\\n            if USE_G:\\n                b_dh3 *= bg_last_exp\\n                b_q = b_q * b_g_exp[None, :]\\n            if USE_GK:\\n                b_dh3 *= tl.exp(b_gk_last3[:, None])\\n            b_dh3 += tl.dot(b_q.to(b_q.dtype), b_do.to(b_q.dtype)) * scale - tl.dot(b_w, b_dv.to(b_w.dtype))\\n        if K > 192:\\n            p_q = tl.make_block_ptr(q, (K, T), (1, stride_k), (192, i_t * BT), (64, BT), (0, 1))\\n            p_w = tl.make_block_ptr(w, (K, T), (1, stride_k), (192, i_t * BT), (64, BT), (0, 1))\\n            b_q = tl.load(p_q, boundary_check=(0, 1))\\n            b_w = tl.load(p_w, boundary_check=(0, 1))\\n            if USE_G:\\n                b_dh4 *= bg_last_exp\\n                b_q = b_q * b_g_exp[None, :]\\n            if USE_GK:\\n                b_dh4 *= tl.exp(b_gk_last4[:, None])\\n            b_dh4 += tl.dot(b_q.to(b_q.dtype), b_do.to(b_q.dtype)) * scale - tl.dot(b_w, b_dv.to(b_w.dtype))\\n\\n    if USE_INITIAL_STATE:\\n        p_dh0 = tl.make_block_ptr(dh0, (K, V), (V, 1), (0, i_v * BV), (64, BV), (1, 0))\\n        tl.store(p_dh0, b_dh1.to(p_dh0.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 64:\\n            p_dh1 = tl.make_block_ptr(dh0, (K, V), (V, 1), (64, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_dh1, b_dh2.to(p_dh1.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 128:\\n            p_dh2 = tl.make_block_ptr(dh0, (K, V), (V, 1), (128, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_dh2, b_dh3.to(p_dh2.dtype.element_ty), boundary_check=(0, 1))\\n        if K > 192:\\n            p_dh3 = tl.make_block_ptr(dh0, (K, V), (V, 1), (192, i_v * BV), (64, BV), (1, 0))\\n            tl.store(p_dh3, b_dh4.to(p_dh3.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\ndef chunk_gated_delta_rule_bwd_dhu(\\n    q: torch.Tensor,\\n    k: torch.Tensor,\\n    w: torch.Tensor,\\n    do: torch.Tensor,\\n    dv: torch.Tensor,\\n    g: torch.Tensor | None = None,\\n    gk: torch.Tensor | None = None,\\n    h0: torch.Tensor | None = None,\\n    dht: torch.Tensor | None = None,\\n    scale: float | None = None,\\n    cu_seqlens: torch.LongTensor | None = None,\\n    chunk_size: int = 64,  # SY: remove this argument and force chunk size 64?\\n    chunk_indices: torch.LongTensor | None = None,\\n    use_exp2: bool = False,\\n) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:\\n    B, T, H, K, V = *q.shape, do.shape[-1]\\n    # N: the actual number of sequences in the batch with either equal or variable lengths\\n    BT = 64\\n    assert K <= 256, \\\"current kernel does not support head dimension being larger than 256.\\\"\\n\\n    if chunk_indices is None and cu_seqlens is not None:\\n        chunk_indices = prepare_chunk_indices(cu_seqlens, chunk_size)\\n    if cu_seqlens is None:\\n        N, NT, chunk_offsets = B, triton.cdiv(T, BT), None\\n    else:\\n        N, NT, chunk_offsets = len(cu_seqlens) - 1, len(chunk_indices), prepare_chunk_offsets(cu_seqlens, BT)\\n\\n    dh = q.new_empty(B, NT, H, K, V)\\n    dh0 = torch.empty_like(h0, dtype=torch.float32) if h0 is not None else None\\n    dv2 = torch.empty_like(dv)\\n\\n    BV = 128\\n\\n    g = g.permute(0, 2, 1).contiguous()\\n\\n    chunk_gated_delta_rule_bwd_kernel_dhu_blockdim64[(triton.cdiv(V, BV), N * H)](\\n        q=q,\\n        k=k,\\n        w=w,\\n        g=g,\\n        gk=gk,\\n        dht=dht,\\n        dh0=dh0,\\n        do=do,\\n        dh=dh,\\n        dv=dv,\\n        dv2=dv2,\\n        cu_seqlens=cu_seqlens,\\n        chunk_offsets=chunk_offsets,\\n        scale=scale,\\n        T=T,\\n        H=H,\\n        K=K,\\n        V=V,\\n        BT=BT,\\n        BV=BV,\\n    )\\n    return dh, dh0, dv2\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/chunk_gated_delta_rule.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cafe5d4d804e0a46305a5bfecae1fc7df8e076e59b4d305a3cc0f115c116d8d9\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport warnings\\nfrom typing import Optional\\n\\nimport torch\\n\\nfrom .chunk_delta_h import chunk_gated_delta_rule_bwd_dhu, chunk_gated_delta_rule_fwd_h\\nfrom .chunk_o import chunk_bwd_dqkwg, chunk_bwd_dv_local, chunk_fwd_o\\nfrom .chunk_scaled_dot_kkt import chunk_scaled_dot_kkt_fwd\\nfrom .cumsum import chunk_local_cumsum\\nfrom .solve_tril import solve_tril\\nfrom .utils import autocast_custom_bwd, autocast_custom_fwd, input_guard\\nfrom .wy_fast import prepare_wy_repr_bwd, recompute_w_u_fwd\\n\\n\\ndef chunk_gated_delta_rule_fwd(\\n    q: torch.Tensor,\\n    k: torch.Tensor,\\n    v: torch.Tensor,\\n    g: torch.Tensor,\\n    beta: torch.Tensor,\\n    scale: float,\\n    initial_state: torch.Tensor,\\n    output_final_state: bool,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n    chunk_size: int = 64,\\n):\\n    g = chunk_local_cumsum(g, chunk_size=chunk_size, cu_seqlens=cu_seqlens, head_first=False)\\n    # obtain WY representation. u is actually the new v.\\n    A = chunk_scaled_dot_kkt_fwd(\\n        k=k, g=g, beta=beta, cu_seqlens=cu_seqlens, chunk_size=chunk_size, output_dtype=torch.float32\\n    )\\n    A = solve_tril(A=A, cu_seqlens=cu_seqlens, output_dtype=k.dtype)\\n    w, u = recompute_w_u_fwd(\\n        k=k,\\n        v=v,\\n        beta=beta,\\n        A=A,\\n        g=g,\\n        cu_seqlens=cu_seqlens,\\n    )\\n    h, v_new, final_state = chunk_gated_delta_rule_fwd_h(\\n        k=k,\\n        w=w,\\n        u=u,\\n        g=g,\\n        initial_state=initial_state,\\n        output_final_state=output_final_state,\\n        chunk_size=chunk_size,\\n        cu_seqlens=cu_seqlens,\\n    )\\n    o = chunk_fwd_o(\\n        q=q,\\n        k=k,\\n        v=v_new,\\n        h=h,\\n        g=g,\\n        scale=scale,\\n        cu_seqlens=cu_seqlens,\\n        chunk_size=chunk_size,\\n    )\\n    return g, o, A, final_state\\n\\n\\ndef chunk_gated_delta_rule_bwd(\\n    q: torch.Tensor,\\n    k: torch.Tensor,\\n    v: torch.Tensor,\\n    g: torch.Tensor,\\n    beta: torch.Tensor,\\n    A: torch.Tensor,\\n    scale: float,\\n    initial_state: torch.Tensor,\\n    do: torch.Tensor,\\n    dht: torch.Tensor,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n    chunk_size: int = 64,\\n):\\n    w, u = recompute_w_u_fwd(\\n        k=k,\\n        v=v,\\n        beta=beta,\\n        A=A,\\n        g=g,\\n        cu_seqlens=cu_seqlens,\\n    )\\n    h, v_new, _ = chunk_gated_delta_rule_fwd_h(\\n        k=k,\\n        w=w,\\n        u=u,\\n        g=g,\\n        initial_state=initial_state,\\n        output_final_state=False,\\n        cu_seqlens=cu_seqlens,\\n        chunk_size=chunk_size,\\n    )\\n    dv = chunk_bwd_dv_local(\\n        q=q,\\n        k=k,\\n        g=g,\\n        do=do,\\n        scale=scale,\\n        cu_seqlens=cu_seqlens,\\n        chunk_size=chunk_size,\\n    )\\n    dh, dh0, dv = chunk_gated_delta_rule_bwd_dhu(\\n        q=q,\\n        k=k,\\n        w=w,\\n        g=g,\\n        h0=initial_state,\\n        dht=dht,\\n        do=do,\\n        dv=dv,\\n        scale=scale,\\n        cu_seqlens=cu_seqlens,\\n        chunk_size=chunk_size,\\n    )\\n    dq, dk, dw, dg = chunk_bwd_dqkwg(\\n        q=q,\\n        k=k,\\n        v=v_new,\\n        w=w,\\n        g=g,\\n        h=h,\\n        dv=dv,\\n        do=do,\\n        dh=dh,\\n        chunk_size=chunk_size,\\n        scale=scale,\\n        cu_seqlens=cu_seqlens,\\n    )\\n    dk2, dv, db, dg2 = prepare_wy_repr_bwd(\\n        k=k, v=v, beta=beta, g=g, A=A, dw=dw, du=dv, cu_seqlens=cu_seqlens, chunk_size=chunk_size\\n    )\\n    dk.add_(dk2)\\n    dg.add_(dg2)\\n    if dg.dtype != torch.float32:\\n        raise ValueError(f\\\"dg current type is {dg.dtype} , should be float32\\\")\\n    dg = chunk_local_cumsum(dg, chunk_size=chunk_size, reverse=True, cu_seqlens=cu_seqlens, head_first=False)\\n    return dq, dk, dv, db, dg, dh0\\n\\n\\nclass ChunkGatedDeltaRuleFunction(torch.autograd.Function):\\n    @staticmethod\\n    @input_guard\\n    @autocast_custom_fwd\\n    def forward(\\n        ctx,\\n        q: torch.Tensor,\\n        k: torch.Tensor,\\n        v: torch.Tensor,\\n        g: torch.Tensor,\\n        beta: torch.Tensor,\\n        scale: float,\\n        initial_state: torch.Tensor,\\n        output_final_state: bool,\\n        cu_seqlens: Optional[torch.LongTensor] = None,\\n        use_qk_l2norm_in_kernel: bool = False,\\n        chunk_size: int = 64,\\n    ):\\n        q_rstd, k_rstd = None, None\\n        g, o, A, final_state = chunk_gated_delta_rule_fwd(\\n            q=q,\\n            k=k,\\n            v=v,\\n            g=g,\\n            beta=beta,\\n            scale=scale,\\n            initial_state=initial_state,\\n            output_final_state=output_final_state,\\n            cu_seqlens=cu_seqlens,\\n            chunk_size=chunk_size,\\n        )\\n        ctx.save_for_backward(q, q_rstd, k, k_rstd, v, g, beta, A, initial_state, cu_seqlens)\\n        ctx.scale = scale\\n        ctx.use_qk_l2norm_in_kernel = use_qk_l2norm_in_kernel\\n        ctx.chunk_size = chunk_size\\n        return o.to(q.dtype), final_state\\n\\n    @staticmethod\\n    @input_guard\\n    @autocast_custom_bwd\\n    def backward(ctx, do: torch.Tensor, dht: torch.Tensor):\\n        q, q_rstd, k, k_rstd, v, g, beta, A, initial_state, cu_seqlens = ctx.saved_tensors\\n        dq, dk, dv, db, dg, dh0 = chunk_gated_delta_rule_bwd(\\n            q=q,\\n            k=k,\\n            v=v,\\n            g=g,\\n            beta=beta,\\n            A=A,\\n            scale=ctx.scale,\\n            initial_state=initial_state,\\n            do=do,\\n            dht=dht,\\n            cu_seqlens=cu_seqlens,\\n            chunk_size=ctx.chunk_size,\\n        )\\n        return dq.to(q), dk.to(k), dv.to(v), dg.to(g), db.to(beta), None, dh0, None, None, None, None\\n\\n\\n@torch.compiler.disable\\ndef chunk_gated_delta_rule(\\n    q: torch.Tensor,\\n    k: torch.Tensor,\\n    v: torch.Tensor,\\n    g: torch.Tensor,\\n    beta: torch.Tensor,\\n    scale: float = None,\\n    initial_state: torch.Tensor = None,\\n    output_final_state: bool = False,\\n    use_qk_l2norm_in_kernel: bool = False,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n    chunk_size: int = 64,\\n    head_first: bool = False,\\n):\\n    r\\\"\\\"\\\"Args:\\n        q (torch.Tensor):\\n            queries of shape `[B, T, H, K]`.\\n        k (torch.Tensor):\\n            keys of shape `[B, T, H, K]`.\\n        v (torch.Tensor):\\n            values of shape `[B, T, H, V]`.\\n        g (torch.Tensor):\\n            (forget) gating tensor (in log space!) of shape `[B, T, H]`.\\n        beta (torch.Tensor):\\n            betas of shape `[B, T, H]`.\\n        scale (Optional[float]):\\n            Scale factor for the RetNet attention scores.\\n            If not provided, it will default to `1 / sqrt(K)`. Default: `None`.\\n        initial_state (Optional[torch.Tensor]):\\n            Initial state of shape `[N, H, K, V]` for `N` input sequences.\\n            For equal-length input sequences, `N` equals the batch size `B`.\\n            Default: `None`.\\n        output_final_state (Optional[bool]):\\n            Whether to output the final state of shape `[N, H, K, V]`. Default: `False`.\\n        use_qk_l2norm_in_kernel (bool):\\n            Whether to apply L2norm to the q/k tensor internally. Default: `False`.\\n        cu_seqlens (torch.LongTensor):\\n            Cumulative sequence lengths of shape `[N+1]` used for variable-length training,\\n            consistent with the FlashAttention API.\\n        head_first (Optional[bool]):\\n            Whether the inputs are in the head-first format. Default: `False`.\\n            This argument has been deprecated.\\n\\n    Returns:\\n        o (torch.Tensor):\\n            Outputs of shape `[B, T, H, V]`.\\n        final_state (torch.Tensor):\\n            Final state of shape `[N, H, K, V]` if `output_final_state=True` else `None`.\\n\\n    Examples::\\n        >>> import torch\\n        >>> import torch.nn.functional as F\\n        >>> from einops import rearrange\\n        >>> from fla.ops.gated_delta_rule import chunk_gated_delta_rule\\n        # inputs with equal lengths\\n        >>> B, T, H, K, V = 4, 2048, 4, 512, 512\\n        >>> q = torch.randn(B, T, H, K, dtype=torch.bfloat16, device='cuda')\\n        >>> k = F.normalize(torch.randn(B, T, H, K, dtype=torch.bfloat16, device='cuda'), p=2, dim=-1)\\n        >>> v = torch.randn(B, T, H, V, dtype=torch.bfloat16, device='cuda')\\n        >>> beta = torch.rand(B, T, H, dtype=torch.bfloat16, device='cuda').sigmoid()\\n        >>> g = F.logsigmoid(torch.rand(B, T, H, dtype=torch.bfloat16, device='cuda'))\\n        >>> h0 = torch.randn(B, H, K, V, dtype=torch.bfloat16, device='cuda')\\n        >>> o, ht = chunk_gated_delta_rule(\\n            q, k, v, g, beta,\\n            initial_state=h0,\\n            output_final_state=True\\n        )\\n        # for variable-length inputs, the batch size `B` is expected to be 1 and `cu_seqlens` is required\\n        >>> q, k, v, beta, g = map(lambda x: rearrange(x, 'b t ... -> 1 (b t) ...'), (q, k, v, beta, g))\\n        # for a batch with 4 sequences, `cu_seqlens` with 5 start/end positions are expected\\n        >>> cu_seqlens = q.new_tensor([0, 2048, 4096, 6144, 8192], dtype=torch.long)\\n        >>> o, ht = chunk_gated_delta_rule(\\n            q, k, v, g, beta,\\n            initial_state=h0,\\n            output_final_state=True,\\n            cu_seqlens=cu_seqlens\\n        )\\n    \\\"\\\"\\\"  # noqa: D205\\n    if q.dtype != k.dtype or k.dtype != v.dtype:\\n        raise ValueError(\\n            f\\\"q current type is {q.dtype} , k current type is {k.dtype} ,v current type is {v.dtype} , they should are equal\\\"\\n        )\\n    if q.dtype == torch.float32:\\n        raise ValueError(\\\"ChunkGatedDeltaRuleFunction does not support float32. Please use bfloat16.\\\")\\n    if len(beta.shape) != 3:\\n        raise ValueError(\\n            f\\\"beta current shape len is {len(beta.shape)}, beta must be of shape [B, T, H] if head_first=False, or [B, H, T] otherwise.\\\"\\n        )\\n\\n    if head_first:\\n        warnings.warn(\\n            \\\"head_first is deprecated and will be removed in a future version. \\\"\\n            \\\"Please use head_first=False for now instead.\\\"\\n        )\\n    if not head_first and q.shape[1] < q.shape[2]:\\n        warnings.warn(\\n            f\\\"Input tensor shape suggests potential format mismatch: seq_len ({q.shape[1]}) < num_heads ({q.shape[2]}). \\\"\\n            \\\"This may indicate the inputs were passed in head-first format [B, H, T, ...] \\\"\\n            \\\"when head_first=False was specified. \\\"\\n            \\\"Please verify your input tensor format matches the expected shape [B, T, H, ...].\\\"\\n        )\\n    if cu_seqlens is not None:\\n        if q.shape[0] != 1:\\n            raise ValueError(\\n                f\\\"The batch size is expected to be 1 rather than {q.shape[0]} when using `cu_seqlens`.\\\"\\n                f\\\"Please flatten variable-length inputs before processing.\\\"\\n            )\\n        if initial_state is not None and initial_state.shape[0] != len(cu_seqlens) - 1:\\n            raise ValueError(\\n                f\\\"The number of initial states is expected to be equal to the number of input sequences, \\\"\\n                f\\\"i.e., {len(cu_seqlens) - 1} rather than {initial_state.shape[0]}.\\\"\\n            )\\n    if scale is None:\\n        scale = k.shape[-1] ** -0.5\\n\\n    def l2norm(x: torch.FloatTensor, dim: int = -1, eps: float = 1e-6):\\n        \\\"\\\"\\\"This function is intended to align with the l2norm implementation in the FLA library.\\\"\\\"\\\"\\n        original_dtype = x.dtype\\n        inv_norm = torch.rsqrt((x * x).sum(dim=dim, keepdim=True) + eps)\\n        # Counteract verl's autocast promotion (bf16 -> fp32) by restoring original dtype\\n        return (x * inv_norm).to(original_dtype)\\n\\n    if use_qk_l2norm_in_kernel:\\n        q = l2norm(q, dim=-1, eps=1e-6)\\n        k = l2norm(k, dim=-1, eps=1e-6)\\n\\n    o, final_state = ChunkGatedDeltaRuleFunction.apply(\\n        q, k, v, g, beta, scale, initial_state, output_final_state, cu_seqlens, False, chunk_size\\n    )\\n    return o, final_state\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/chunk_o.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ded0a31ca80bc78e97455ce19f42d1defec2d23c1f04addfd1152c64b614033d\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import Optional\\n\\nimport torch\\nimport triton\\nimport triton.language as tl\\n\\nfrom .utils import exp, prepare_chunk_indices, prepare_chunk_offsets\\n\\n\\n@triton.heuristics(\\n    {\\n        \\\"USE_G\\\": lambda args: args[\\\"g\\\"] is not None,\\n        \\\"USE_G_GAMMA\\\": lambda args: args[\\\"g_gamma\\\"] is not None,\\n        \\\"USE_DW\\\": lambda args: args[\\\"dw\\\"] is not None,\\n        \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None,\\n    }\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_bwd_kernel_dqkwg(\\n    q,\\n    k,\\n    v,\\n    h,\\n    g,\\n    g_gamma,\\n    do,\\n    dh,\\n    dq,\\n    dk,\\n    dg,\\n    w,\\n    dv,\\n    dw,\\n    cu_seqlens,\\n    chunk_indices,\\n    scale,\\n    B: tl.constexpr,\\n    T,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    V: tl.constexpr,\\n    BT: tl.constexpr,\\n    BK: tl.constexpr,\\n    BV: tl.constexpr,\\n    USE_G: tl.constexpr,\\n    USE_G_GAMMA: tl.constexpr,\\n    USE_DW: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n    gdiff,\\n):\\n    i_t, i_b = tl.program_id(0), tl.program_id(1)\\n    T_max = T\\n    if IS_VARLEN:\\n        i_tg = i_t\\n        i_n, i_t = tl.load(chunk_indices + i_t * 2).to(tl.int32), tl.load(chunk_indices + i_t * 2 + 1).to(tl.int32)\\n        bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n        total = B * T_max\\n        T = eos - bos\\n    else:\\n        NT = tl.cdiv(T, BT)\\n        i_tg = i_b * NT + i_t\\n        bos, eos = i_b * T, i_b * T + T\\n        total = B * T_max\\n\\n    NK = tl.cdiv(K, BK)\\n    for i_k in range(NK):\\n        if USE_G:\\n            dg_k = dg + i_k * total * H\\n\\n        for i_h in range(H):\\n            v_h = v + (bos * H + i_h) * V\\n            do_h = do + (bos * H + i_h) * V\\n            h_h = h + (i_tg * H + i_h).to(tl.int64) * K * V\\n            dh_h = dh + (i_tg * H + i_h).to(tl.int64) * K * V\\n            q_h = q + (bos * H + i_h) * K\\n            k_h = k + (bos * H + i_h) * K\\n            dq_h = dq + (bos * H + i_h) * K\\n            dk_h = dk + (bos * H + i_h) * K\\n\\n            if USE_DW:\\n                w_h = w + (bos * H + i_h) * K  # noqa: F841\\n                dw_h = dw + (bos * H + i_h) * K\\n                dv_h = dv + (bos * H + i_h) * V\\n\\n            if USE_G:\\n                if IS_VARLEN:\\n                    dg_h = dg_k + i_h * T_max + bos\\n                    g_h = g + i_h * T_max + bos\\n                else:\\n                    dg_h = dg_k + (i_b * H + i_h) * T_max\\n                    g_h = g + (i_b * H + i_h) * T_max\\n                b_dg_last = tl.zeros(\\n                    [\\n                        1,\\n                    ],\\n                    dtype=tl.float32,\\n                )\\n\\n            if USE_G_GAMMA:\\n                b_gamma = tl.load(g_gamma + i_h)\\n                b_g = b_gamma * (tl.arange(0, BT) + 1)\\n                b_g_last = b_gamma * min(BT, T - i_t * BT)\\n\\n            b_dq = tl.zeros([BT, BK], dtype=tl.float32)\\n            b_dk = tl.zeros([BT, BK], dtype=tl.float32)\\n            b_ds = tl.zeros([BT, BT], dtype=tl.float32)\\n            b_dw = tl.zeros([BT, BK], dtype=tl.float32) if USE_DW else None\\n\\n            for i_v in range(tl.cdiv(V, BV)):\\n                p_v = tl.make_block_ptr(v_h, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n                p_do = tl.make_block_ptr(do_h, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n                p_h = tl.make_block_ptr(h_h, (V, K), (1, V), (i_v * BV, i_k * BK), (BV, BK), (0, 1))\\n                p_dh = tl.make_block_ptr(dh_h, (V, K), (1, V), (i_v * BV, i_k * BK), (BV, BK), (0, 1))\\n\\n                b_v = tl.load(p_v, boundary_check=(0, 1))\\n                b_do = tl.load(p_do, boundary_check=(0, 1))\\n                b_h = tl.load(p_h, boundary_check=(0, 1))\\n                b_dh = tl.load(p_dh, boundary_check=(0, 1))\\n\\n                if USE_G:\\n                    b_dg_last += tl.sum(b_h * b_dh)\\n\\n                b_ds += tl.dot(b_do, tl.trans(b_v))\\n                b_dq += tl.dot(b_do, b_h.to(b_do.dtype))\\n                b_dk += tl.dot(b_v, b_dh.to(b_v.dtype))\\n\\n                if USE_DW:\\n                    p_dv = tl.make_block_ptr(dv_h, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n                    b_dv = tl.load(p_dv, boundary_check=(0, 1))\\n                    b_dw += tl.dot(b_dv.to(b_v.dtype), b_h.to(b_v.dtype))\\n\\n            if USE_DW:\\n                p_dw = tl.make_block_ptr(dw_h, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0))\\n                tl.store(p_dw, -b_dw.to(p_dw.dtype.element_ty), boundary_check=(0, 1))\\n\\n            tl.debug_barrier()\\n\\n            p_q = tl.make_block_ptr(q_h, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0))\\n            p_k = tl.make_block_ptr(k_h, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0))\\n            b_q = tl.load(p_q, boundary_check=(0, 1))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n\\n            p_dq = tl.make_block_ptr(dq_h, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0))\\n            p_dk = tl.make_block_ptr(dk_h, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0))\\n\\n            o_t = i_t * BT + tl.arange(0, BT)\\n            m_t = o_t < T\\n            m_A = (o_t[:, None] >= o_t[None, :]) & (m_t[:, None] & m_t)\\n\\n            if USE_G:\\n                b_dg = tl.zeros(\\n                    [\\n                        BT,\\n                    ],\\n                    dtype=tl.float32,\\n                )\\n                p_g = tl.make_block_ptr(g_h, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                b_g = tl.load(p_g, boundary_check=(0,))\\n                b_g_last = tl.load(g_h + (min(i_t * BT + BT, T) - 1) * 1)\\n                b_dg_last *= tl.exp(b_g_last)\\n\\n                b_dq = b_dq * tl.exp(b_g)[:, None] * scale\\n                b_dg += tl.sum(b_dq * b_q, axis=1)\\n\\n                b_dk = b_dk * tl.where(m_t, tl.exp(-b_g + b_g_last), 0)[:, None]\\n                b_dg -= tl.sum(b_k * b_dk, axis=1)\\n                b_dg_last += tl.sum(b_dk * b_k)\\n\\n                if IS_VARLEN:\\n                    b_ds = tl.where(m_A, b_ds * exp(b_g[:, None] - b_g[None, :]), 0) * scale\\n                else:\\n                    p_gdiff = tl.make_block_ptr(\\n                        gdiff + i_b * H * NT * BT * BT + i_h * NT * BT * BT + i_t * BT * BT,\\n                        (BT, BT),\\n                        (BT, 1),\\n                        (0, 0),\\n                        (BT, BT),\\n                        (1, 0),\\n                    )\\n                    gdiff_ = tl.load(p_gdiff)\\n                    b_ds = b_ds * gdiff_ * scale\\n\\n                b_ds2 = b_ds * tl.dot(b_q, tl.trans(b_k))\\n                b_dg += tl.sum(b_ds2, axis=1)\\n                b_dg -= tl.sum(b_ds2, axis=0)\\n\\n                b_ds = b_ds.to(b_k.dtype)\\n                b_dq += tl.dot(b_ds, b_k)\\n                b_dk += tl.dot(tl.trans(b_ds), b_q)\\n                p_dg = tl.make_block_ptr(dg_h, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n\\n                last_index_local = min(BT, T - i_t * BT) - 1\\n                if last_index_local >= 0:\\n                    is_last_mask = tl.arange(0, BT) == last_index_local\\n                    b_dg = tl.where(is_last_mask, b_dg + b_dg_last, b_dg)\\n                else:\\n                    pass\\n\\n                tl.store(p_dq, b_dq.to(p_dq.dtype.element_ty), boundary_check=(0, 1))\\n                tl.store(p_dk, b_dk.to(p_dk.dtype.element_ty), boundary_check=(0, 1))\\n                tl.store(p_dg, b_dg.to(p_dg.dtype.element_ty), boundary_check=(0,))\\n\\n            elif USE_G_GAMMA:\\n                b_dq = b_dq * exp(b_g)[:, None] * scale\\n                b_dk = b_dk * tl.where(m_t, exp(-b_g + b_g_last), 0)[:, None]\\n                b_ds = tl.where(m_A, b_ds * exp(b_g[:, None] - b_g[None, :]), 0) * scale\\n                b_ds = b_ds.to(b_k.dtype)\\n                b_dq += tl.dot(b_ds, b_k)\\n                b_dk += tl.dot(tl.trans(b_ds), b_q)\\n                tl.store(p_dq, b_dq.to(p_dq.dtype.element_ty), boundary_check=(0, 1))\\n                tl.store(p_dk, b_dk.to(p_dk.dtype.element_ty), boundary_check=(0, 1))\\n\\n            else:\\n                b_ds = tl.where(m_A, b_ds, 0)\\n                b_ds = b_ds.to(b_k.dtype)\\n                b_dq += tl.dot(b_ds, b_k)\\n                b_dk += tl.dot(tl.trans(b_ds), b_q) * scale\\n                b_dq *= scale\\n                tl.store(p_dq, b_dq.to(p_dq.dtype.element_ty), boundary_check=(0, 1))\\n                tl.store(p_dk, b_dk.to(p_dk.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\n@triton.heuristics(\\n    {\\n        \\\"USE_G\\\": lambda args: args[\\\"g\\\"] is not None,\\n        \\\"USE_G_GAMMA\\\": lambda args: args[\\\"g_gamma\\\"] is not None,\\n        \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None,\\n    }\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_bwd_kernel_dv_local(\\n    q,\\n    k,\\n    g,\\n    g_gamma,\\n    do,\\n    dv,\\n    cu_seqlens,\\n    chunk_indices,\\n    scale,\\n    T,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    V: tl.constexpr,\\n    BT: tl.constexpr,\\n    BK: tl.constexpr,\\n    BV: tl.constexpr,\\n    USE_G: tl.constexpr,\\n    USE_G_GAMMA: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    i_t, i_b = tl.program_id(0), tl.program_id(1)\\n    T_max = T\\n\\n    if IS_VARLEN:\\n        i_n, i_t = tl.load(chunk_indices + i_t * 2).to(tl.int32), tl.load(chunk_indices + i_t * 2 + 1).to(tl.int32)\\n        bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n        T = eos - bos\\n    else:\\n        bos, eos = i_b * T, i_b * T + T\\n\\n    for i_h in range(H):\\n        offset_kh = (bos * H + i_h) * K\\n        offset_vh = (bos * H + i_h) * V\\n\\n        b_A = tl.zeros([BT, BT], dtype=tl.float32)\\n        for i_k in range(tl.cdiv(K, BK)):\\n            p_k = tl.make_block_ptr(k + offset_kh, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0))\\n            p_q = tl.make_block_ptr(q + offset_kh, (K, T), (1, H * K), (i_k * BK, i_t * BT), (BK, BT), (0, 1))\\n            b_q = tl.load(p_q, boundary_check=(0, 1))\\n            b_k = tl.load(p_k, boundary_check=(0, 1))\\n            b_A += tl.dot(b_k, b_q)\\n\\n        if USE_G:\\n            if IS_VARLEN:\\n                offset_g = i_h * T_max + bos\\n            else:\\n                offset_g = i_b * H * T_max + i_h * T_max\\n\\n            p_g = tl.make_block_ptr(g + offset_g, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n            b_g = tl.load(p_g, boundary_check=(0,))\\n\\n        if USE_G_GAMMA:\\n            b_gamma = tl.load(g_gamma + i_h)\\n            b_g = b_gamma * (tl.arange(0, BT) + 1)\\n\\n        o_t = i_t * BT + tl.arange(0, BT)\\n        m_t = o_t < T\\n        m_A = (o_t[:, None] <= o_t[None, :]) & (m_t[:, None] & m_t)\\n\\n        if USE_G:\\n            b_A = tl.where(m_A, b_A * tl.exp(b_g[None, :] - b_g[:, None]) * scale, 0).to(do.dtype.element_ty)\\n        else:\\n            b_A = tl.where(m_A, b_A * scale, 0).to(do.dtype.element_ty)\\n\\n        for i_v in range(tl.cdiv(V, BV)):\\n            p_do = tl.make_block_ptr(do + offset_vh, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n            p_dv = tl.make_block_ptr(dv + offset_vh, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n            b_do = tl.load(p_do, boundary_check=(0, 1))\\n            b_dv = tl.dot(b_A.to(b_do.dtype), b_do)\\n            tl.store(p_dv, b_dv.to(p_dv.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\n@triton.heuristics(\\n    {\\n        \\\"USE_G\\\": lambda args: args[\\\"g\\\"] is not None,\\n        \\\"USE_G_GAMMA\\\": lambda args: args[\\\"g_gamma\\\"] is not None,\\n        \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None,\\n    }\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_fwd_kernel_o(\\n    q,\\n    k,\\n    v,\\n    h,\\n    g,\\n    g_gamma,\\n    o,\\n    cu_seqlens,\\n    chunk_offsets,\\n    scale,\\n    T,\\n    H: tl.constexpr,\\n    N: tl.constexpr,\\n    Hg: tl.constexpr,\\n    K: tl.constexpr,\\n    V: tl.constexpr,\\n    BT: tl.constexpr,\\n    BK: tl.constexpr,\\n    BV: tl.constexpr,\\n    USE_G: tl.constexpr,\\n    USE_G_GAMMA: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    T_max = T\\n    for i_v in range(tl.cdiv(V, BV)):\\n        for i_n in range(N):\\n            if IS_VARLEN:\\n                bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n                T = eos - bos\\n                NT = tl.cdiv(T, BT)\\n                boh = tl.load(chunk_offsets + i_n).to(tl.int64)\\n            else:\\n                bos, eos = i_n * T, i_n * T + T\\n                NT = tl.cdiv(T, BT)\\n                boh = i_n * NT\\n\\n            core_id = tl.program_id(0)\\n            total_cores = tl.num_programs(0)\\n            base_chunks_per_pid = NT // total_cores\\n            remainder = NT % total_cores\\n\\n            if core_id < remainder:\\n                chunks_this_pid = base_chunks_per_pid + 1\\n                start_idx = core_id * chunks_this_pid\\n            else:\\n                chunks_this_pid = base_chunks_per_pid\\n                start_idx = core_id * base_chunks_per_pid + remainder\\n\\n            # offset calculation\\n            for i_h in range(0, H):\\n                q_offset = (bos * Hg + i_h // (H // Hg)) * K\\n                k_offset = (bos * Hg + i_h // (H // Hg)) * K\\n                v_offset = (bos * H + i_h) * V\\n                o_offset = (bos * H + i_h) * V\\n\\n                for i_t in range(start_idx, start_idx + chunks_this_pid):\\n                    i_tg = boh + i_t\\n                    h_base = h + (i_tg * H + i_h).to(tl.int64) * K * V\\n                    b_o = tl.zeros([BT, BV], dtype=tl.float32)\\n                    b_A = tl.zeros([BT, BT], dtype=tl.float32)\\n                    for i_k in range(tl.cdiv(K, BK)):\\n                        p_q = tl.make_block_ptr(\\n                            q + q_offset, (T, K), (Hg * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                        )\\n                        p_k = tl.make_block_ptr(\\n                            k + k_offset, (K, T), (1, Hg * K), (i_k * BK, i_t * BT), (BK, BT), (0, 1)\\n                        )\\n                        p_h = tl.make_block_ptr(h_base, (K, V), (V, 1), (i_k * BK, i_v * BV), (BK, BV), (1, 0))\\n                        b_q = tl.load(p_q, boundary_check=(0, 1))\\n                        b_k = tl.load(p_k, boundary_check=(0, 1))\\n                        b_h = tl.load(p_h, boundary_check=(0, 1))\\n\\n                        # [BT, BK] @ [BK, BV] -> [BT, BV]\\n                        b_o += tl.dot(b_q, b_h)\\n                        # [BT, BK] @ [BK, BT] -> [BT, BT]\\n                        b_A += tl.dot(b_q, b_k)\\n\\n                    if USE_G:\\n                        if IS_VARLEN:\\n                            p_g = tl.make_block_ptr(g + bos + i_h * T_max, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                        else:\\n                            p_g = tl.make_block_ptr(g + bos * H + i_h * T_max, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                        b_g = tl.load(p_g, boundary_check=(0,))\\n                        b_o = b_o * exp(b_g)[:, None]\\n                        b_A = b_A * exp(b_g[:, None] - b_g[None, :])\\n                    if USE_G_GAMMA:\\n                        b_gamma = tl.load(g_gamma + i_h)\\n                        b_g = b_gamma * (tl.arange(0, BT) + 1)\\n\\n                    o_i = tl.arange(0, BT)\\n                    m_A = o_i[:, None] >= o_i[None, :]\\n                    b_A = tl.where(m_A, b_A, 0)\\n\\n                    p_v = tl.make_block_ptr(v + v_offset, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n                    p_o = tl.make_block_ptr(o + o_offset, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0))\\n                    b_v = tl.load(p_v, boundary_check=(0, 1))\\n\\n                    # to fix mma -> mma layout conversion\\n                    # already solved by triton v3.2 or higher\\n                    b_o = b_o * scale + tl.dot(b_A.to(b_v.dtype), b_v) * scale\\n                    tl.store(p_o, b_o.to(p_o.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\ndef chunk_bwd_dqkwg(\\n    q: torch.Tensor,\\n    k: torch.Tensor,\\n    v: torch.Tensor,\\n    do: torch.Tensor,\\n    h: torch.Tensor,\\n    dh: torch.Tensor,\\n    g: Optional[torch.Tensor] = None,\\n    g_gamma: Optional[torch.Tensor] = None,\\n    dv: Optional[torch.Tensor] = None,\\n    w: Optional[torch.Tensor] = None,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n    chunk_size: int = 64,\\n    scale: float = 1.0,\\n) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:\\n    B, T, H, K, V = *k.shape, v.shape[-1]\\n    BT = min(chunk_size, max(16, triton.next_power_of_2(T)))\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n    NT = triton.cdiv(T, BT) if cu_seqlens is None else len(chunk_indices)\\n\\n    BK = 128 if cu_seqlens is None else 64\\n    BV = 64\\n    NK = triton.cdiv(K, BK)\\n    dq = torch.empty_like(q)\\n    dk = torch.empty_like(k)\\n    g = g.transpose(1, 2).contiguous()\\n    dg = torch.empty(NK, *g.shape, dtype=torch.float32, device=g.device) if g is not None else None\\n    dw = torch.empty_like(w) if w is not None else None\\n    grid = (NT, B)\\n\\n    if cu_seqlens is None:\\n        if NT * BT == T:\\n            g_ = g.reshape(B, H, NT, BT)\\n            g_diff = g_[:, :, :, :, None] - g_[:, :, :, None, :]\\n            g_diff = g_diff.clamp(-60, 60).exp()\\n            g_diff[:, :, :] *= torch.tril(torch.ones(BT, BT), diagonal=0).to(g.device)\\n        else:\\n            diff = NT * BT - T\\n            g_ = torch.cat((g, torch.zeros(B, H, diff).to(g.device)), dim=-1).reshape(B, H, NT, BT)\\n            g_diff = g_[:, :, :, :, None] - g_[:, :, :, None, :]\\n            g_diff = g_diff.clamp(-60, 60).exp()\\n            g_diff[:, :, :] *= torch.tril(torch.ones(BT, BT), diagonal=0).to(g.device)\\n            bias = torch.arange(0, BT).to(g.device)\\n            o_t = (NT - 1) * BT + bias\\n            m_t = o_t < T\\n            m_A = m_t[:, None] & m_t\\n            g_diff[:, :, -1] *= m_A\\n    else:\\n        g_diff = None\\n\\n    chunk_bwd_kernel_dqkwg[grid](\\n        q=q,\\n        k=k,\\n        v=v,\\n        h=h,\\n        g=g,\\n        g_gamma=g_gamma,\\n        do=do,\\n        dh=dh,\\n        dv=dv,\\n        w=w,\\n        dw=dw,\\n        dq=dq,\\n        dk=dk,\\n        dg=dg,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        scale=scale,\\n        B=B,\\n        T=T,\\n        H=H,\\n        K=K,\\n        V=V,\\n        BT=BT,\\n        BK=BK,\\n        BV=BV,\\n        gdiff=g_diff,\\n    )\\n\\n    if dg is not None:\\n        dg = dg.sum(0)\\n        dg = dg.transpose(1, 2).contiguous()\\n    return dq, dk, dw, dg\\n\\n\\ndef chunk_bwd_dv_local(\\n    q: torch.Tensor,\\n    k: torch.Tensor,\\n    do: torch.Tensor,\\n    g: Optional[torch.Tensor] = None,\\n    g_gamma: Optional[torch.Tensor] = None,\\n    scale: float = None,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n    chunk_size: int = 64,\\n) -> torch.Tensor:\\n    B, T, H, K, V = *k.shape, do.shape[-1]\\n    BT = min(chunk_size, max(16, triton.next_power_of_2(T)))\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n\\n    BK = 128\\n    BV = 128\\n    NT = triton.cdiv(T, BT) if cu_seqlens is None else len(chunk_indices)\\n\\n    g = g.transpose(1, 2).contiguous()\\n    dv = torch.empty_like(do)\\n    grid = (NT, B)\\n    chunk_bwd_kernel_dv_local[grid](\\n        q=q,\\n        k=k,\\n        g=g,\\n        g_gamma=g_gamma,\\n        do=do,\\n        dv=dv,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        scale=scale,\\n        T=T,\\n        H=H,\\n        K=K,\\n        V=V,\\n        BT=BT,\\n        BK=BK,\\n        BV=BV,\\n    )\\n    return dv\\n\\n\\ndef chunk_fwd_o(\\n    q: torch.Tensor,\\n    k: torch.Tensor,\\n    v: torch.Tensor,\\n    h: torch.Tensor,\\n    g: Optional[torch.Tensor] = None,\\n    g_gamma: Optional[torch.Tensor] = None,\\n    scale: Optional[float] = None,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n    chunk_size: int = 64,\\n) -> torch.Tensor:\\n    B, T, Hg, K, V = *q.shape, v.shape[-1]\\n    H = v.shape[-2]\\n    BT = min(chunk_size, max(16, triton.next_power_of_2(T)))\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n    NT = triton.cdiv(T, BT) if cu_seqlens is None else len(chunk_indices)  # noqa: F841\\n    if scale is None:\\n        scale = k.shape[-1] ** -0.5\\n\\n    o = torch.empty_like(v)\\n    if cu_seqlens is None:\\n        N, chunk_offsets = B, None\\n    else:\\n        N, chunk_offsets = (\\n            len(cu_seqlens) - 1,\\n            prepare_chunk_offsets(cu_seqlens, BT),\\n        )\\n\\n    def grid(meta):\\n        return (triton.cdiv(V, meta[\\\"BV\\\"]), N * H)\\n\\n    g = g.transpose(1, 2).contiguous()\\n    h = h.contiguous()\\n    CV_kernel_num = 24\\n    chunk_fwd_kernel_o[(CV_kernel_num,)](\\n        q,\\n        k,\\n        v,\\n        h,\\n        g,\\n        g_gamma,\\n        o,\\n        cu_seqlens,\\n        chunk_offsets,\\n        scale,\\n        T=T,\\n        H=H,\\n        N=N,\\n        Hg=Hg,\\n        K=K,\\n        V=V,\\n        BT=BT,\\n        BK=128,\\n        BV=128,\\n    )\\n    return o\\n\\n\\nbwd_chunk_dqkwg = chunk_bwd_dqkwg\\nbwd_chunk_dv_local = chunk_bwd_dv_local\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/chunk_scaled_dot_kkt.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"78c7557b6f5f50471f67947e3acf1bc6ad36d2c2909327600a9c5f767e483a69\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import Optional\\n\\nimport torch\\nimport triton\\nimport triton.language as tl\\n\\nfrom .utils import prepare_chunk_indices\\n\\n\\n@triton.heuristics(\\n    {\\n        \\\"USE_G\\\": lambda args: args[\\\"g\\\"] is not None,\\n        \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None,\\n    }\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_scaled_dot_kkt_fwd_kernel(\\n    k,\\n    g,\\n    beta,\\n    A,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    BT: tl.constexpr,\\n    BK: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n    USE_G: tl.constexpr,\\n    NT,\\n    B,\\n    TOTAL_TASKS,\\n):\\n    core_id = tl.program_id(0)\\n    num_blocks = tl.num_programs(0)\\n    T_max = T\\n\\n    base_tasks_per_block = TOTAL_TASKS // num_blocks\\n    remainder_tasks = TOTAL_TASKS % num_blocks\\n\\n    if core_id < remainder_tasks:\\n        tasks_this_core = base_tasks_per_block + 1\\n        start_idx = core_id * tasks_this_core\\n    else:\\n        tasks_this_core = base_tasks_per_block\\n        start_idx = core_id * base_tasks_per_block + remainder_tasks\\n\\n    for idx in range(start_idx, start_idx + tasks_this_core):\\n        i_b = idx // NT\\n        local_idx = idx % NT\\n\\n        if IS_VARLEN:\\n            i_n = tl.load(chunk_indices + local_idx * 2).to(tl.int32)\\n            i_t = tl.load(chunk_indices + local_idx * 2 + 1).to(tl.int32)\\n            bos = tl.load(cu_seqlens + i_n).to(tl.int32)\\n            eos = tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n            T_local = eos - bos\\n        else:\\n            bos, eos = 0, T\\n            i_t = local_idx\\n            T_local = T\\n\\n        for i_h in range(H):\\n            k_batch_off = i_b * T_max * H * K\\n            beta_batch_off = i_b * H * T_max\\n            g_batch_off = i_b * H * T_max\\n            A_batch_off = i_b * T_max * H * BT\\n\\n            p_beta = tl.make_block_ptr(\\n                beta + beta_batch_off + bos + i_h * T_max, (T_local,), (1,), (i_t * BT,), (BT,), (0,)\\n            )\\n            b_beta = tl.load(p_beta, boundary_check=(0,))\\n\\n            b_A = tl.zeros([BT, BT], dtype=tl.float32)\\n            for i_k in range(tl.cdiv(K, BK)):\\n                p_k = tl.make_block_ptr(\\n                    k + k_batch_off + (bos * H + i_h) * K,\\n                    (T_local, K),\\n                    (H * K, 1),\\n                    (i_t * BT, i_k * BK),\\n                    (BT, BK),\\n                    (1, 0),\\n                )\\n                b_k = tl.load(p_k, boundary_check=(0, 1))\\n                dot_product = tl.dot(b_k, tl.trans(b_k))\\n\\n                o_t = i_t * BT + tl.arange(0, BT)\\n                o_t = o_t.to(tl.float32)\\n                T_mask = (o_t < T_local).to(tl.float32)\\n\\n                row_indices = tl.arange(0, BT)[:, None]\\n                col_indices = tl.arange(0, BT)[None, :]\\n                tril_mask = (row_indices > col_indices).to(tl.float32)\\n                tril_mask = tril_mask * T_mask[:, None]\\n                masked_dot = dot_product * tril_mask\\n                b_A += masked_dot\\n\\n            if USE_G:\\n                p_g = tl.make_block_ptr(\\n                    g + g_batch_off + bos + i_h * T_max, (T_local,), (1,), (i_t * BT,), (BT,), (0,)\\n                )\\n                b_g = tl.load(p_g, boundary_check=(0,))\\n                b_g_diff = b_g[:, None] - b_g[None, :]\\n                b_g_diff = tl.minimum(tl.maximum(b_g_diff, -50.0), 50.0)\\n                b_A *= tl.exp(b_g_diff)\\n            b_A *= b_beta[:, None]\\n\\n            p_A = tl.make_block_ptr(\\n                A + A_batch_off + (bos * H + i_h) * BT, (T_local, BT), (BT * H, 1), (i_t * BT, 0), (BT, BT), (1, 0)\\n            )\\n            tl.store(p_A, b_A.to(p_A.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\n@triton.heuristics({\\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None})\\n@triton.autotune(configs=[triton.Config({\\\"BK\\\": BK}) for BK in [32, 64]], key=[\\\"BC\\\"])\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_scaled_dot_kkt_fwd_kernel_intra_sub_inter(\\n    k,\\n    g,\\n    beta,\\n    A,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    BT: tl.constexpr,\\n    BC: tl.constexpr,\\n    BK: tl.constexpr,\\n    NC: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    i_t, i_c, i_b = tl.program_id(0), tl.program_id(1), tl.program_id(2)\\n    i_i, i_j = i_c // NC, i_c % NC\\n\\n    for i_h in range(H):\\n        if IS_VARLEN:\\n            i_n, i_t = tl.load(chunk_indices + i_t * 2).to(tl.int32), tl.load(chunk_indices + i_t * 2 + 1).to(tl.int32)\\n            bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n            T_val = eos - bos\\n        else:\\n            bos, eos = i_b * T, i_b * T + T\\n            T_val = T\\n\\n        should_compute = (i_t * BT + i_i * BC < T_val) and (i_i > i_j)\\n\\n        if should_compute:\\n            k_ptr = k + (bos * H + i_h) * K\\n            g_ptr = g + (bos * H + i_h) * K\\n            A_ptr = A + (bos * H + i_h) * BT\\n\\n            p_beta = tl.make_block_ptr(beta + bos * H + i_h, (T_val,), (H,), (i_t * BT + i_i * BC,), (BC,), (0,))\\n            b_beta = tl.load(p_beta, boundary_check=(0,))\\n\\n            b_A = tl.zeros([BC, BC], dtype=tl.float32)\\n            for i_k in range(tl.cdiv(K, BK)):\\n                p_k = tl.make_block_ptr(\\n                    k_ptr, (T_val, K), (H * K, 1), (i_t * BT + i_i * BC, i_k * BK), (BC, BK), (1, 0)\\n                )\\n                p_g = tl.make_block_ptr(\\n                    g_ptr, (T_val, K), (H * K, 1), (i_t * BT + i_i * BC, i_k * BK), (BC, BK), (1, 0)\\n                )\\n                b_kt = tl.make_block_ptr(\\n                    k_ptr, (K, T_val), (1, H * K), (i_k * BK, i_t * BT + i_j * BC), (BK, BC), (0, 1)\\n                )\\n                p_gk = tl.make_block_ptr(\\n                    g_ptr, (K, T_val), (1, H * K), (i_k * BK, i_t * BT + i_j * BC), (BK, BC), (0, 1)\\n                )\\n\\n                o_k = i_k * BK + tl.arange(0, BK)\\n                m_k = o_k < K\\n                b_gn = tl.load(g_ptr + (i_t * BT + i_i * BC) * H * K + o_k, mask=m_k, other=0)\\n                b_g = tl.load(p_g, boundary_check=(0, 1))\\n                b_k = tl.load(p_k, boundary_check=(0, 1)) * tl.exp(b_g - b_gn[None, :])\\n                b_gk = tl.load(p_gk, boundary_check=(0, 1))\\n                b_kt = tl.load(b_kt, boundary_check=(0, 1)) * tl.exp(b_gn[:, None] - b_gk)\\n                b_A += tl.dot(b_k, b_kt)\\n            b_A *= b_beta[:, None]\\n\\n            p_A = tl.make_block_ptr(A_ptr, (T_val, BT), (H * BT, 1), (i_t * BT + i_i * BC, i_j * BC), (BC, BC), (1, 0))\\n            tl.store(p_A, b_A.to(A.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\n@triton.heuristics({\\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None})\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_scaled_dot_kkt_fwd_kernel_intra_sub_intra(\\n    k,\\n    g,\\n    beta,\\n    A,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    BT: tl.constexpr,\\n    BC: tl.constexpr,\\n    BK: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    i_t, i_i, i_b = tl.program_id(0), tl.program_id(1), tl.program_id(2)\\n\\n    for i_h in range(H):\\n        if IS_VARLEN:\\n            i_n, i_t = tl.load(chunk_indices + i_t * 2).to(tl.int32), tl.load(chunk_indices + i_t * 2 + 1).to(tl.int32)\\n            bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n            T_val = eos - bos\\n        else:\\n            bos, eos = i_b * T, i_b * T + T\\n            T_val = T\\n\\n        should_compute = i_t * BT + i_i * BC < T_val\\n\\n        if should_compute:\\n            o_i = tl.arange(0, BC)\\n            o_k = tl.arange(0, BK)\\n            m_k = o_k < K\\n            m_A = (i_t * BT + i_i * BC + o_i) < T_val\\n            o_A = (bos + i_t * BT + i_i * BC + o_i) * H * BT + i_h * BT + i_i * BC\\n\\n            p_k = tl.make_block_ptr(\\n                k + (bos * H + i_h) * K, (T_val, K), (H * K, 1), (i_t * BT + i_i * BC, 0), (BC, BK), (1, 0)\\n            )\\n            p_g = tl.make_block_ptr(\\n                g + (bos * H + i_h) * K, (T_val, K), (H * K, 1), (i_t * BT + i_i * BC, 0), (BC, BK), (1, 0)\\n            )\\n            p_beta = beta + (bos + i_t * BT + i_i * BC + o_i) * H + i_h\\n\\n            b_k = tl.load(p_k, boundary_check=(0, 1)) * tl.load(p_beta, mask=m_A, other=0)[:, None]\\n            b_g = tl.load(p_g, boundary_check=(0, 1))\\n\\n            p_kt = k + (bos + i_t * BT + i_i * BC) * H * K + i_h * K + o_k\\n            p_gk = g + (bos + i_t * BT + i_i * BC) * H * K + i_h * K + o_k\\n\\n            for j in range(0, min(BC, T_val - i_t * BT - i_i * BC)):\\n                b_kt = tl.load(p_kt, mask=m_k, other=0).to(tl.float32)\\n                b_gk = tl.load(p_gk, mask=m_k, other=0).to(tl.float32)\\n                b_A = tl.sum(b_k * b_kt[None, :] * tl.exp(b_g - b_gk[None, :]), 1)\\n                # \u8f6c\u5316\u6210f32\\n                o_i_tmp = o_i.to(tl.float32)\\n                b_A = tl.where(o_i_tmp > j, b_A, 0.0)\\n\\n                tl.store(A + o_A + j, b_A, mask=m_A)\\n                p_kt += H * K\\n                p_gk += H * K\\n\\n\\ndef chunk_scaled_dot_kkt_fwd(\\n    k: torch.Tensor,\\n    g: Optional[torch.Tensor] = None,\\n    gk: Optional[torch.Tensor] = None,\\n    beta: Optional[torch.Tensor] = None,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n    chunk_size: int = 64,\\n    output_dtype: torch.dtype = torch.float32,\\n) -> torch.Tensor:\\n    r\\\"\\\"\\\"Compute beta * K * K^T.\\n\\n    Args:\\n        k (torch.Tensor):\\n            The key tensor of shape `[B, T, H, K]`.\\n        beta (torch.Tensor):\\n            The beta tensor of shape `[B, T, H]`.\\n        g (torch.Tensor):\\n            The cumulative sum of the gate tensor of shape `[B, T, H]`. Default: `None`.\\n        gk (torch.Tensor):\\n            The cumulative sum of the gate tensor of shape `[B, T, H, K]` applied to the key tensor. Default: `None`.\\n        cu_seqlens (torch.LongTensor):\\n            The cumulative sequence lengths of the input tensor.\\n            Default: None\\n        chunk_size (int):\\n            The chunk size. Default: 64.\\n        output_dtype (torch.dtype):\\n            The dtype of the output tensor. Default: `torch.float32`\\n\\n    Returns:\\n        beta * K * K^T of shape `[B, T, H, BT]` where `BT` is the chunk size.\\n    \\\"\\\"\\\"\\n    B, T, H, K = k.shape\\n    BT = chunk_size\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n    NT = triton.cdiv(T, BT) if cu_seqlens is None else len(chunk_indices)\\n    beta = beta.transpose(1, 2).contiguous()\\n    g = g.transpose(1, 2).contiguous()\\n    BK = 128\\n    kernel_num = 24\\n\\n    if gk is None:\\n        A = torch.empty(B, T, H, BT, device=k.device, dtype=output_dtype)\\n        chunk_scaled_dot_kkt_fwd_kernel[(kernel_num,)](\\n            k=k,\\n            g=g,\\n            beta=beta,\\n            A=A,\\n            cu_seqlens=cu_seqlens,\\n            chunk_indices=chunk_indices,\\n            T=T,\\n            H=H,\\n            K=K,\\n            BT=BT,\\n            BK=BK,\\n            NT=NT,\\n            B=B,\\n            TOTAL_TASKS=B * NT,\\n        )\\n        return A\\n\\n    BC = min(16, BT)\\n    NC = triton.cdiv(BT, BC)\\n    BK = max(triton.next_power_of_2(K), 16)\\n    A = torch.zeros(B, T, H, BT, device=k.device, dtype=output_dtype)\\n    grid = (NT, NC * NC, B)\\n    chunk_scaled_dot_kkt_fwd_kernel_intra_sub_inter[grid](\\n        k=k,\\n        g=gk,\\n        beta=beta,\\n        A=A,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        T=T,\\n        H=H,\\n        K=K,\\n        BT=BT,\\n        BC=BC,\\n        NC=NC,\\n    )\\n\\n    grid = (NT, NC, B)\\n    chunk_scaled_dot_kkt_fwd_kernel_intra_sub_intra[grid](\\n        k=k,\\n        g=gk,\\n        beta=beta,\\n        A=A,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        T=T,\\n        H=H,\\n        K=K,\\n        BT=BT,\\n        BC=BC,\\n        BK=BK,\\n    )\\n    return A\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/cumsum.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a4b35b9889654f8c8f00e6444fbd738dfcc3de3806355fee30a7ae3bcead6685\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import Optional\\n\\nimport torch\\nimport triton\\nimport triton.language as tl\\n\\nfrom .utils import prepare_chunk_indices\\n\\n\\n@triton.heuristics(\\n    {\\\"HAS_SCALE\\\": lambda args: args[\\\"scale\\\"] is not None, \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None}\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef chunk_local_cumsum_scalar_kernel(\\n    s,\\n    o,\\n    scale,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    B: tl.constexpr,\\n    H: tl.constexpr,\\n    BLOCK_T: tl.constexpr,\\n    REVERSE: tl.constexpr,\\n    HAS_SCALE: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n    HEAD_FIRST: tl.constexpr,\\n    CHUNK_SIZE: tl.constexpr = 64,\\n):\\n    i_block, i_b = tl.program_id(0), tl.program_id(1)\\n    N_CHUNKS: tl.constexpr = BLOCK_T // CHUNK_SIZE\\n\\n    if IS_VARLEN:\\n        i_s, i_block = (\\n            tl.load(chunk_indices + i_block * 2).to(tl.int32),\\n            tl.load(chunk_indices + i_block * 2 + 1).to(tl.int32),\\n        )\\n\\n        bos, eos = tl.load(cu_seqlens + i_s).to(tl.int32), tl.load(cu_seqlens + i_s + 1).to(tl.int32)\\n        T = eos - bos\\n    else:\\n        bos, eos = i_b * T, i_b * T + T\\n\\n    ptr_s = tl.make_block_ptr(s + bos * H, (T, H), (H, 1), (i_block * BLOCK_T, 0), (BLOCK_T, H), (1, 0))\\n    ptr_o = tl.make_block_ptr(o + bos * H, (T, H), (H, 1), (i_block * BLOCK_T, 0), (BLOCK_T, H), (1, 0))\\n    b_s = tl.load(ptr_s, boundary_check=(0,)).to(tl.float32)\\n    b_s = tl.reshape(b_s, (N_CHUNKS, CHUNK_SIZE, H))\\n    b_s = tl.trans(b_s, (1, 0, 2))\\n    b_o = tl.cumsum(b_s, axis=0)\\n    if REVERSE:\\n        b_z = tl.sum(b_s, axis=0)\\n        b_o = -b_o + b_z[None] + b_s\\n    if HAS_SCALE:\\n        b_o *= scale\\n    b_o = tl.trans(b_o, (1, 0, 2))\\n    b_o = tl.reshape(b_o, (BLOCK_T, H))\\n\\n    tl.store(ptr_o, b_o.to(ptr_o.dtype.element_ty), boundary_check=(0,))\\n    return\\n\\n\\ndef chunk_local_cumsum_scalar(\\n    g: torch.Tensor,\\n    chunk_size: int,\\n    reverse: bool = False,\\n    scale: float = None,\\n    cu_seqlens: Optional[torch.Tensor] = None,\\n    head_first: bool = False,\\n    output_dtype: Optional[torch.dtype] = torch.float,\\n) -> torch.Tensor:\\n    B, T, H = g.shape\\n    if chunk_size != 2 ** (chunk_size.bit_length() - 1):\\n        raise ValueError(f\\\"chunk_size must be a power of 2, chunk_size is{chunk_size}\\\")\\n    # We adjust the tiling strategy to prevent overflow in in backward passes and context parallel scenarios\\n    #  while maximizing UB utilization where possible.\\n    # The tiling strategy is as follows:\\n    # 1. BT must be greater than or equal to chunk_size.\\n    # 2. UB estimation varies directly with H.\\n    # 3. BT in reverse mode is smaller than in forward mode.\\n    BT = max(chunk_size, triton.next_power_of_2((1 << 11 if reverse else 1 << 12) // H))\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n    NT = triton.cdiv(T, BT) if cu_seqlens is None else len(chunk_indices)\\n    g_org, g = g, torch.empty_like(g, dtype=output_dtype or g.dtype)\\n    grid = (NT, B)\\n    chunk_local_cumsum_scalar_kernel[grid](\\n        s=g_org,\\n        o=g,\\n        scale=scale,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        T=T,\\n        B=B,\\n        H=H,\\n        BLOCK_T=BT,\\n        HEAD_FIRST=head_first,\\n        REVERSE=reverse,\\n        CHUNK_SIZE=chunk_size,\\n    )\\n    return g\\n\\n\\ndef chunk_local_cumsum(\\n    g: torch.Tensor,\\n    chunk_size: int,\\n    reverse: bool = False,\\n    scale: float = None,\\n    cu_seqlens: Optional[torch.Tensor] = None,\\n    head_first: bool = False,\\n    output_dtype: Optional[torch.dtype] = torch.float,\\n    **kwargs,\\n) -> torch.Tensor:\\n    if cu_seqlens is not None:\\n        if g.shape[0] != 1:\\n            raise ValueError(\\n                f\\\"Only batch size 1 is supported when cu_seqlens are provided, current size is{g.shape[0]}\\\"\\n            )\\n    if len(g.shape) == 3:\\n        return chunk_local_cumsum_scalar(\\n            g=g,\\n            chunk_size=chunk_size,\\n            reverse=reverse,\\n            scale=scale,\\n            cu_seqlens=cu_seqlens,\\n            head_first=head_first,\\n            output_dtype=output_dtype,\\n        )\\n    else:\\n        raise ValueError(\\n            f\\\"Unsupported input shape {g.shape}, \\\"\\n            f\\\"which should be (B, T, H, D) if `head_first=False` \\\"\\n            f\\\"or (B, H, T, D) otherwise\\\"\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/solve_tril.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0edb0ff03e79f992b0351a659855b2514cb996bd5cf190df40f4e0b3c3c03f0a\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n# Copyright (c) 2026, Huawei Technologies Co., Ltd. All rights reserved.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nimport os\\nfrom typing import Optional\\n\\nimport torch\\nimport triton\\nimport triton.language as tl\\n\\nfrom .utils import input_guard, make_tensor_descriptor, prepare_chunk_indices\\n\\n\\nFLA_TRIL_PRECISION = os.environ.get(\\\"FLA_TRIL_PRECISION\\\", \\\"ieee\\\")\\n\\n\\n@triton.heuristics({\\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None})\\n@triton.jit(do_not_specialize=[\\\"T\\\", \\\"TPP\\\"])\\ndef solve_tril_16x16_kernel(\\n    A,\\n    Ai,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    H: tl.constexpr,\\n    BT: tl.constexpr,\\n    TPP: tl.constexpr,\\n    USE_TMA: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n    DOT_PRECISION: tl.constexpr,\\n):\\n    pid_t, pid_bh = tl.program_id(0), tl.program_id(1)\\n    i_b, i_h = pid_bh // H, pid_bh % H\\n\\n    base_t = pid_t * TPP\\n\\n    if IS_VARLEN:\\n        i_n = tl.load(chunk_indices + base_t * 2).to(tl.int32)\\n        bos = tl.load(cu_seqlens + i_n).to(tl.int32)\\n        eos = tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n        T_eff = eos - bos\\n    else:\\n        bos, eos = i_b * T, i_b * T + T\\n        T_eff = T\\n\\n    o_i = tl.arange(0, 16)  # noqa: F841\\n    o_i_fp32 = tl.arange(0, 16).to(tl.float32)\\n    m_A = o_i_fp32[:, None] > o_i_fp32[None, :]\\n    m_I = o_i_fp32[:, None] == o_i_fp32[None, :]\\n\\n    A = A + (bos * H + i_h) * BT\\n    Ai = Ai + (bos * H + i_h) * BT\\n\\n    for tpp in tl.static_range(0, TPP):\\n        tile_t = base_t + tpp\\n        tile_row = tile_t * 16\\n\\n        offset = (tile_t * 16) % BT\\n\\n        if not USE_TMA:\\n            p_A = tl.make_block_ptr(A, (T_eff, BT), (H * BT, 1), (tile_row, offset), (16, 16), (1, 0))\\n            b_A_raw = tl.load(p_A, boundary_check=(0, 1)).to(tl.float32)\\n        else:\\n            desc = make_tensor_descriptor(A, [T_eff, BT], [H * BT, 1], [16, 16])\\n            desc_o = make_tensor_descriptor(Ai, [T_eff, 16], [H * 16, 1], [16, 16])\\n            b_A_raw = desc.load([tile_row, offset]).to(tl.float32)\\n\\n        b_A_neg = -b_A_raw\\n        b_A = b_A_neg * m_A\\n        for i in range(2, min(16, T_eff - tile_row)):\\n            slice_res = tl.extract_slice(b_A_neg, [i, 0], [1, 16], [1, 1])\\n            b_a_val = tl.reshape(slice_res, (16,), can_reorder=True)\\n            dot_prod = tl.sum(b_a_val[:, None] * b_A, 0)\\n            b_a_update = b_a_val + dot_prod\\n            b_A = tl.where((o_i_fp32 == i)[:, None], b_a_update, b_A)\\n        b_A += m_I\\n\\n        if not USE_TMA:\\n            p_Ai = tl.make_block_ptr(Ai, (T_eff, 16), (H * 16, 1), (tile_row, 0), (16, 16), (1, 0))\\n            tl.store(p_Ai, b_A.to(p_Ai.dtype.element_ty, fp_downcast_rounding=\\\"rtne\\\"), boundary_check=(0, 1))\\n        else:\\n            desc_o.store([tile_row, 0], b_A.to(desc_o.dtype, fp_downcast_rounding=\\\"rtne\\\"))\\n\\n\\n@triton.heuristics({\\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None})\\n@triton.jit(do_not_specialize=[\\\"T\\\", \\\"TPP\\\"])\\ndef merge_16x16_to_32x32_inverse_kernel(\\n    A,\\n    Ai,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    H: tl.constexpr,\\n    BT: tl.constexpr,\\n    TPP: tl.constexpr,\\n    USE_TMA: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n    DOT_PRECISION: tl.constexpr,\\n):\\n    i_t, i_bh = tl.program_id(0), tl.program_id(1)\\n    i_b, i_h = i_bh // H, i_bh % H\\n    if IS_VARLEN:\\n        i_n, i_t = tl.load(chunk_indices + i_t * 2).to(tl.int32), tl.load(chunk_indices + i_t * 2 + 1).to(tl.int32)\\n        bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n        T = eos - bos\\n    else:\\n        bos, eos = i_b * T, i_b * T + T\\n\\n    o_i = tl.arange(0, 16)\\n    m_A = o_i[:, None] > o_i[None, :]\\n    m_I = o_i[:, None] == o_i[None, :]\\n    A += (bos * H + i_h) * BT\\n    Ai += (bos * H + i_h) * BT\\n\\n    if not USE_TMA:\\n        p_A_11 = tl.make_block_ptr(A, (T, BT), (H * BT, 1), (i_t * BT, 0), (16, 16), (1, 0))\\n        p_A_22 = tl.make_block_ptr(A, (T, BT), (H * BT, 1), (i_t * BT + 16, 16), (16, 16), (1, 0))\\n        b_Ai_11 = tl.load(p_A_11, boundary_check=(0, 1)).to(tl.float32)\\n        b_Ai_22 = tl.load(p_A_22, boundary_check=(0, 1)).to(tl.float32)\\n    else:\\n        desc = make_tensor_descriptor(A, [T, BT], [H * BT, 1], [16, 16])\\n        desc_o = make_tensor_descriptor(Ai, [T, BT], [H * BT, 1], [16, 16])\\n        b_Ai_11 = desc.load([i_t * BT + 0, 0]).to(tl.float32)\\n        b_Ai_22 = desc.load([i_t * BT + 16, 16]).to(tl.float32)\\n\\n    b_Ai_11 = -tl.where(m_A, b_Ai_11, 0)\\n    b_Ai_22 = -tl.where(m_A, b_Ai_22, 0)\\n\\n    for i in range(2, min(16, T - i_t * BT)):\\n        b_a_11 = -tl.load(A + (i_t * BT + i) * H * BT + o_i)\\n        b_a_11 += tl.sum(b_a_11[:, None] * b_Ai_11, 0)\\n        b_Ai_11 = tl.where((o_i == i)[:, None], b_a_11, b_Ai_11)\\n    for i in range(16 + 2, min(32, T - i_t * BT)):\\n        b_a_22 = -tl.load(A + (i_t * BT + i) * H * BT + o_i + 16)\\n        b_a_22 += tl.sum(b_a_22[:, None] * b_Ai_22, 0)\\n        b_Ai_22 = tl.where((o_i == i - 16)[:, None], b_a_22, b_Ai_22)\\n\\n    b_Ai_11 += m_I\\n    b_Ai_22 += m_I\\n\\n    if not USE_TMA:\\n        p_A_21 = tl.make_block_ptr(A, (T, BT), (H * BT, 1), (i_t * BT + 16, 0), (16, 16), (1, 0))\\n        b_A_21 = tl.load(p_A_21, boundary_check=(0, 1)).to(tl.float32)\\n    else:\\n        b_A_21 = desc.load([i_t * BT + 16, 0]).to(tl.float32)\\n\\n    b_Ai_21 = -tl.dot(tl.dot(b_Ai_22, b_A_21, input_precision=DOT_PRECISION), b_Ai_11, input_precision=DOT_PRECISION)\\n\\n    if not USE_TMA:\\n        p_Ai_11 = tl.make_block_ptr(Ai, (T, BT), (H * BT, 1), (i_t * BT, 0), (16, 16), (1, 0))\\n        p_Ai_21 = tl.make_block_ptr(Ai, (T, BT), (H * BT, 1), (i_t * BT + 16, 0), (16, 16), (1, 0))\\n        p_Ai_22 = tl.make_block_ptr(Ai, (T, BT), (H * BT, 1), (i_t * BT + 16, 16), (16, 16), (1, 0))\\n        tl.store(p_Ai_11, b_Ai_11.to(p_Ai_11.dtype.element_ty, fp_downcast_rounding=\\\"rtne\\\"), boundary_check=(0, 1))\\n        tl.store(p_Ai_22, b_Ai_22.to(p_Ai_22.dtype.element_ty, fp_downcast_rounding=\\\"rtne\\\"), boundary_check=(0, 1))\\n        tl.store(p_Ai_21, b_Ai_21.to(p_Ai_21.dtype.element_ty, fp_downcast_rounding=\\\"rtne\\\"), boundary_check=(0, 1))\\n    else:\\n        desc_o.store([i_t * BT + 0, 0], b_Ai_11.to(desc_o.dtype, fp_downcast_rounding=\\\"rtne\\\"))\\n        desc_o.store([i_t * BT + 16, 0], b_Ai_21.to(desc_o.dtype, fp_downcast_rounding=\\\"rtne\\\"))\\n        desc_o.store([i_t * BT + 16, 16], b_Ai_22.to(desc_o.dtype, fp_downcast_rounding=\\\"rtne\\\"))\\n\\n\\n@triton.heuristics({\\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None})\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef solve_tril_64x64_kernel(\\n    A,\\n    Ai,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    H: tl.constexpr,\\n    BT: tl.constexpr,\\n    USE_TMA: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n    DOT_PRECISION: tl.constexpr,\\n):\\n    i_t, i_bh = tl.program_id(0), tl.program_id(1)\\n    i_b, i_h = i_bh // H, i_bh % H\\n    if IS_VARLEN:\\n        i_n, i_t = tl.load(chunk_indices + i_t * 2).to(tl.int32), tl.load(chunk_indices + i_t * 2 + 1).to(tl.int32)\\n        bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n        T = eos - bos\\n    else:\\n        bos, eos = i_b * T, i_b * T + T\\n    o_i = tl.arange(0, 64)\\n    m_I = o_i[:, None] == o_i[None, :]\\n\\n    A = A + (bos * H + i_h) * BT\\n    Ai = Ai + (bos * H + i_h) * 64\\n\\n    offset = (i_t * 64) % BT\\n    if not USE_TMA:\\n        p_A = tl.make_block_ptr(A, (T, BT), (H * BT, 1), (i_t * 64, offset), (64, 64), (1, 0))\\n        b_A = -tl.load(p_A, boundary_check=(0, 1)).to(tl.float32)\\n    else:\\n        desc = make_tensor_descriptor(A, [T, BT], [H * BT, 1], [64, 64])\\n        desc_o = make_tensor_descriptor(Ai, [T, 64], [H * 64, 1], [64, 64])\\n        b_A = -desc.load([i_t * 64, offset]).to(tl.float32)\\n\\n    for i in range(2, min(64, T - i_t * 64)):\\n        b_a = -tl.load(A + (i_t * 64 + i) * H * BT + o_i + offset)\\n        b_a = b_a + tl.sum(b_a[:, None] * b_A, 0)\\n        b_A = tl.where((o_i == i)[:, None], b_a, b_A)\\n    b_A += m_I\\n    if not USE_TMA:\\n        p_Ai = tl.make_block_ptr(Ai, (T, 64), (H * 64, 1), (i_t * 64, 0), (64, 64), (1, 0))\\n        tl.store(p_Ai, b_A.to(p_Ai.dtype.element_ty, fp_downcast_rounding=\\\"rtne\\\"), boundary_check=(0, 1))\\n    else:\\n        desc_o.store([i_t * 64, 0], b_A.to(desc_o.dtype, fp_downcast_rounding=\\\"rtne\\\"))\\n\\n\\n@input_guard\\ndef solve_tril(\\n    A: torch.Tensor, cu_seqlens: Optional[torch.Tensor] = None, output_dtype: torch.dtype = torch.float\\n) -> torch.Tensor:\\n    \\\"\\\"\\\"Compute the inverse of the matrix I + A\\n    A should be strictly lower triangular, i.e., A.triu() == 0.\\n\\n    Args:\\n        A (torch.Tensor):\\n            [B, T, H, BT], where BT should only be 16, 32, or 64.\\n        cu_seqlens (torch.Tensor):\\n            The cumulative sequence lengths of the input tensor. Default: `None`.\\n        output_dtype (torch.dtype):\\n            The dtype of the output tensor. Default: `torch.float`.\\n            If `None`, the output dtype will be the same as the input dtype.\\n\\n    Returns:\\n        (I + A)^-1 with the same shape as A\\n    \\\"\\\"\\\"  # noqa: D205\\n    if A.shape[-1] not in [16, 32, 64]:\\n        raise ValueError(f\\\"A shape BT should in [16,32, 64], but current is {A.shape[-1]}\\\")\\n    output_dtype = A.dtype if output_dtype is None else output_dtype\\n\\n    B, T, H, BT = A.shape\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n    NT = len(chunk_indices) if cu_seqlens is not None else triton.cdiv(T, BT)\\n\\n    Ai = torch.zeros_like(A, dtype=output_dtype)\\n\\n    if BT == 16:\\n        merge_fn = solve_tril_16x16_kernel\\n    elif BT == 32:\\n        merge_fn = merge_16x16_to_32x32_inverse_kernel\\n    elif BT == 64:\\n        merge_fn = solve_tril_64x64_kernel\\n\\n    merge_fn[NT, B * H](\\n        A=A,\\n        Ai=Ai,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        T=T,\\n        H=H,\\n        BT=BT,\\n        USE_TMA=False,\\n        DOT_PRECISION=FLA_TRIL_PRECISION,\\n    )\\n    return Ai\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"94757b53f31409dbb705cbd6595f8ba89cd43fc4b56acdd41a5712d28757a5f3\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport contextlib\\nimport functools\\nimport itertools\\nimport logging\\nimport os\\nimport warnings\\nfrom collections.abc import Callable\\nfrom enum import Enum\\nfrom typing import Any, Optional\\n\\nimport torch\\nimport triton\\nimport triton.language as tl\\nimport triton.language.extra.libdevice as tldevice\\nimport triton.runtime.driver as driver\\nfrom packaging import version\\n\\n\\nlogger = logging.getLogger(__name__)\\n\\nFLA_CI_ENV = os.getenv(\\\"FLA_CI_ENV\\\") == \\\"1\\\"\\n\\n\\ndef tensor_cache(fn: Optional[Callable[..., torch.Tensor]] = None, *, maxsize: int = 1) -> Any:\\n    \\\"\\\"\\\"A decorator that caches the most recent results of a function with tensor inputs.\\n\\n    This decorator will store the outputs of the decorated function for the most recent\\n    set of input tensors, up to `maxsize` entries. If the function is called again with\\n    the same input tensors, it will return the cached result.\\n\\n    When maxsize=1 (default), the behavior is identical to caching only the most recent result.\\n    Can be used as @tensor_cache or @tensor_cache(maxsize=n).\\n\\n    Args:\\n        fn (Callable[..., torch.Tensor], optional):\\n            The function to be decorated when used without parentheses.\\n        maxsize (int):\\n            Maximum number of input combinations to cache. Default is 1.\\n\\n    Returns:\\n        Callable[..., torch.Tensor]:\\n        A wrapped version of the input function with caching.\\n    \\\"\\\"\\\"\\n    if maxsize < 1:\\n        raise ValueError(\\\"maxsize must be at least 1\\\")\\n\\n    def _is_match(a: Any, b: Any) -> bool:\\n        if isinstance(a, torch.Tensor) and isinstance(b, torch.Tensor):\\n            return a is b\\n        try:\\n            return a == b\\n        except Exception:\\n            return a is b\\n\\n    def _make_wrapper(fn: Callable[..., torch.Tensor]) -> Callable[..., torch.Tensor]:\\n        cache: list = []\\n\\n        @functools.wraps(fn)\\n        def wrapper(*args: Any, **kwargs: Any) -> Any:\\n            for i, (cached_args, cached_kwargs, cached_result) in enumerate(cache):\\n                if len(args) == len(cached_args) and len(kwargs) == len(cached_kwargs):\\n                    if all(_is_match(a, b) for a, b in zip(args, cached_args)) and all(\\n                        k in cached_kwargs and _is_match(v, cached_kwargs[k]) for k, v in kwargs.items()\\n                    ):\\n                        if i != 0:\\n                            cache.insert(0, cache.pop(i))\\n                        return cached_result\\n\\n            result = fn(*args, **kwargs)\\n            cache.insert(0, (args, kwargs, result))\\n            if len(cache) > maxsize:\\n                cache.pop()\\n            return result\\n\\n        return wrapper\\n\\n    if fn is not None:\\n        return _make_wrapper(fn)\\n    return _make_wrapper\\n\\n\\n@tensor_cache\\ndef prepare_lens(cu_seqlens: torch.LongTensor) -> torch.LongTensor:\\n    return cu_seqlens[1:] - cu_seqlens[:-1]\\n\\n\\n@tensor_cache(maxsize=3)\\ndef prepare_chunk_indices(cu_seqlens: torch.LongTensor, chunk_size: int) -> torch.LongTensor:\\n    indices = torch.cat([torch.arange(n) for n in triton.cdiv(prepare_lens(cu_seqlens), chunk_size).tolist()])\\n    return torch.stack([indices.eq(0).cumsum(0) - 1, indices], 1).to(cu_seqlens)\\n\\n\\ndef get_abs_err(x, y):\\n    return (x.detach() - y.detach()).flatten().abs().max().item()\\n\\n\\ndef get_err_ratio(x, y):\\n    err = (x.detach() - y.detach()).flatten().square().mean().sqrt().item()\\n    base = (x.detach()).flatten().square().mean().sqrt().item()\\n    return err / (base + 1e-8)\\n\\n\\ndef assert_close(prefix, ref, tri, ratio, warning=False, err_atol=1e-6):\\n    abs_atol = get_abs_err(ref, tri)\\n    msg = f\\\"{prefix:>16} diff: {abs_atol:.6f} ratio: {get_err_ratio(ref, tri):.6f}\\\"\\n    logger.info(msg)\\n    error_rate = get_err_ratio(ref, tri)\\n    if abs_atol <= err_atol:\\n        return\\n    if warning or (FLA_CI_ENV and (error_rate < 0.01 or abs_atol <= 0.3)):\\n        if error_rate > ratio:\\n            warnings.warn(msg)\\n    else:\\n        assert error_rate < ratio, msg\\n\\n\\nif hasattr(triton.language, \\\"_experimental_make_tensor_descriptor\\\"):\\n    # For Triton 3.3.x\\n    make_tensor_descriptor = triton.language._experimental_make_tensor_descriptor\\nelif hasattr(triton.language, \\\"make_tensor_descriptor\\\"):\\n    # For Triton 3.4.x and later\\n    make_tensor_descriptor = triton.language.make_tensor_descriptor\\nelse:\\n    \\\"\\\"\\\"\\n    Fallback implementation when TMA is not supported.\\n    Returns None to indicate TMA descriptors are unavailable.\\n    Just make triton compiler happy.\\n    \\\"\\\"\\\"\\n\\n    @triton.jit\\n    def make_tensor_descriptor(\\n        base,\\n        shape,\\n        strides,\\n        block_shape,\\n        _builder=None,\\n    ):\\n        return None\\n\\n\\n@functools.cache\\ndef get_available_device() -> str:\\n    try:\\n        return triton.runtime.driver.active.get_current_target().backend\\n    except BaseException:\\n        _cpu_device_warning()\\n        return \\\"cpu\\\"\\n\\n\\ndef map_triton_backend_to_torch_device() -> str:\\n    backend = get_available_device()  # 'cuda' | 'hip' | 'xpu' | 'cpu' | ...\\n    return {\\\"cuda\\\": \\\"cuda\\\", \\\"hip\\\": \\\"cuda\\\", \\\"xpu\\\": \\\"xpu\\\"}.get(backend, backend)\\n\\n\\ndevice = get_available_device() if get_available_device() != \\\"hip\\\" else \\\"cuda\\\"\\ndevice_torch_lib = getattr(torch, device)\\ndevice_platform = get_available_device()\\nis_amd = device_platform == \\\"hip\\\"\\nis_nvidia = device_platform == \\\"cuda\\\"\\nis_nvidia_hopper = is_nvidia and (\\n    \\\"NVIDIA H\\\" in torch.cuda.get_device_name(0) or torch.cuda.get_device_capability()[0] >= 9\\n)\\n\\nis_tf32_supported = is_nvidia and torch.cuda.get_device_capability(0)[0] >= 8\\nis_tma_supported = (\\n    (is_nvidia and torch.cuda.get_device_capability(0)[0] >= 9)\\n    and os.environ.get(\\\"FLA_NO_USE_TMA\\\", \\\"0\\\") != \\\"1\\\"\\n    and (\\n        hasattr(triton.language, \\\"_experimental_make_tensor_descriptor\\\")\\n        or hasattr(triton.language, \\\"make_tensor_descriptor\\\")\\n    )\\n)\\n\\nif is_nvidia and not is_tf32_supported:\\n    # Make old card happy, since triton will use tf32 by default.\\n    # This is a workaround for old nvidia card.\\n    os.environ[\\\"TRITON_F32_DEFAULT\\\"] = \\\"ieee\\\"\\n\\n\\n@functools.cache\\ndef check_pytorch_version(version_s: str = \\\"2.4\\\") -> bool:\\n    return version.parse(torch.__version__) >= version.parse(version_s)\\n\\n\\nif check_pytorch_version(\\\"2.4\\\"):\\n    device = \\\"cuda\\\" if device == \\\"cpu\\\" else device\\n    autocast_custom_fwd = functools.partial(torch.amp.custom_fwd, device_type=device)\\n    autocast_custom_bwd = functools.partial(torch.amp.custom_bwd, device_type=device)\\n\\n    def custom_device_ctx(index: int):\\n        return device_torch_lib.device(index)\\nelse:\\n    assert device == \\\"cuda\\\", \\\"Only cuda device is supported for PyTorch version < 2.4.0.\\\"\\n    autocast_custom_fwd = device_torch_lib.amp.custom_fwd\\n    autocast_custom_bwd = device_torch_lib.amp.custom_bwd\\n\\n    def custom_device_ctx(index: int):\\n        return torch.cuda.device(index)\\n\\n\\ndef input_guard(fn: Callable[..., torch.Tensor]) -> Callable[..., torch.Tensor]:\\n    \\\"\\\"\\\"A decorator to make sure all input tensors are contiguous and set the device based on input tensors.\\\"\\\"\\\"\\n\\n    @functools.wraps(fn)\\n    def wrapper(*args, **kwargs):\\n        contiguous_args = (i if not isinstance(i, torch.Tensor) else i.contiguous() for i in args)\\n        contiguous_kwargs = {k: (v if not isinstance(v, torch.Tensor) else v.contiguous()) for k, v in kwargs.items()}\\n\\n        tensor = None\\n        for arg in args:\\n            if isinstance(arg, torch.Tensor):\\n                tensor = arg\\n                break\\n        if tensor is None:\\n            for value in kwargs.values():\\n                if isinstance(value, torch.Tensor):\\n                    tensor = value\\n                    break\\n\\n        if tensor is not None:\\n            ctx = custom_device_ctx(tensor.device.index)\\n        else:\\n            ctx = contextlib.nullcontext()\\n\\n        with ctx:\\n            return fn(*contiguous_args, **contiguous_kwargs)\\n\\n    return wrapper\\n\\n\\ndef _cpu_device_warning():\\n    warnings.warn((\\\"Triton is not supported on current platform, roll back to CPU.\\\"), stacklevel=1)\\n\\n\\n@tensor_cache\\ndef prepare_chunk_offsets(cu_seqlens: torch.LongTensor, chunk_size: int) -> torch.LongTensor:\\n    return torch.cat([cu_seqlens.new_tensor([0]), triton.cdiv(prepare_lens(cu_seqlens), chunk_size)]).cumsum(-1)\\n\\n\\nif os.environ.get(\\\"FLA_USE_FAST_OPS\\\", \\\"0\\\") == \\\"1\\\":\\n    exp = tldevice.fast_expf\\n    exp2 = tldevice.exp2\\n    log = tldevice.fast_logf\\n    log2 = tldevice.fast_log2f\\nelse:\\n    exp = tl.exp\\n    exp2 = tl.math.exp2\\n    log = tl.log\\n    log2 = tl.log2\\n\\n\\ndef get_all_max_shared_mem():\\n    try:\\n        return [\\n            triton.runtime.driver.active.utils.get_device_properties(i)[\\\"max_shared_mem\\\"]\\n            for i in range(device_torch_lib.device_count())\\n        ]\\n    except BaseException:\\n        _cpu_device_warning()\\n        return [-1]\\n\\n\\nclass Backend(Enum):\\n    ADA = 101376  # RTX 4090\\n    AMPERE = 166912  # A100\\n    HOPPER = 232448  # H100\\n    DEFAULT = 102400  # Default\\n\\n    @classmethod\\n    def get_shared_memory(cls, arch: str) -> int:\\n        try:\\n            return cls[arch.upper()].value\\n        except KeyError:\\n            return cls.DEFAULT.value\\n\\n\\n@functools.cache\\ndef check_shared_mem(arch: str = \\\"none\\\", tensor_idx: int = 0) -> bool:\\n    try:\\n        device_shared_mem_list = get_all_max_shared_mem()\\n        max_shared_memory = device_shared_mem_list[tensor_idx]\\n        return max_shared_memory >= Backend.get_shared_memory(arch)\\n    except Exception:\\n        return False\\n\\n\\ndef get_autotune_config(\\n    multibuffer_list: tuple = (False,),\\n    unit_flag_list: tuple = (False,),\\n    limit_auto_multi_buffer_only_for_local_buffer_list: tuple = (False,),\\n    limit_auto_multi_buffer_of_local_buffer_list: tuple = (\\\"no-l0c\\\",),\\n    set_workspace_multibuffer_list: tuple = (2, 4),\\n    enable_hivm_auto_cv_balance_list: tuple = (True,),\\n    tile_mix_vector_loop_num_list: tuple = (2, 4),\\n    tile_mix_cube_loop_num_list: tuple = (2, 4),\\n):\\n    configs = []\\n    for (\\n        multibuffer,\\n        unit_flag,\\n        limit_auto_multi_buffer_only_for_local_buffer,\\n        limit_auto_multi_buffer_of_local_buffer,\\n    ) in itertools.product(\\n        list(multibuffer_list),\\n        list(unit_flag_list),\\n        list(limit_auto_multi_buffer_only_for_local_buffer_list),\\n        list(limit_auto_multi_buffer_of_local_buffer_list),\\n    ):\\n        base_config_dict = {\\n            \\\"multibuffer\\\": multibuffer,\\n            \\\"unit_flag\\\": unit_flag,\\n            \\\"limit_auto_multi_buffer_only_for_local_buffer\\\": limit_auto_multi_buffer_only_for_local_buffer,\\n            \\\"limit_auto_multi_buffer_of_local_buffer\\\": limit_auto_multi_buffer_of_local_buffer,\\n        }\\n\\n        if limit_auto_multi_buffer_only_for_local_buffer:\\n            configs.append(triton.Config(base_config_dict))\\n        else:\\n            for (\\n                set_workspace_multibuffer,\\n                enable_hivm_auto_cv_balance,\\n                tile_mix_vector_loop,\\n                tile_mix_cube_loop,\\n            ) in itertools.product(\\n                list(set_workspace_multibuffer_list),\\n                list(enable_hivm_auto_cv_balance_list),\\n                list(tile_mix_vector_loop_num_list),\\n                list(tile_mix_cube_loop_num_list),\\n            ):\\n                full_config_dict = base_config_dict.copy()\\n                full_config_dict.update(\\n                    {\\n                        \\\"set_workspace_multibuffer\\\": set_workspace_multibuffer,\\n                        \\\"enable_hivm_auto_cv_balance\\\": enable_hivm_auto_cv_balance,\\n                        \\\"tile_mix_vector_loop\\\": tile_mix_vector_loop,\\n                        \\\"tile_mix_cube_loop\\\": tile_mix_cube_loop,\\n                    }\\n                )\\n                configs.append(triton.Config(full_config_dict))\\n    return configs\\n\\n\\ndef get_npu_properties():\\n    return driver.active.utils.get_device_properties(torch.npu.current_device())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/third_party/triton/wy_fast.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7eb3bbdea90ca34880544e0099ab3ad2c13ad67ab1c23b09f04a8cca081fc2fd\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n# Copyright (c) 2023-2025, Songlin Yang, Yu Zhang\\n# Copyright (c) 2026, Huawei Technologies Co., Ltd.  All rights reserved.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import Optional\\n\\nimport torch\\nimport triton\\nimport triton.language as tl\\n\\nfrom .utils import exp, prepare_chunk_indices\\n\\n\\n@triton.heuristics({\\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None})\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef prepare_wy_repr_bwd_kernel(\\n    k,\\n    v,\\n    beta,\\n    g,\\n    A,\\n    dw,\\n    du,\\n    dk,\\n    dv,\\n    dbeta,\\n    dg,\\n    cu_seqlens,\\n    chunk_indices,\\n    T,\\n    B,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    V: tl.constexpr,\\n    NT: tl.constexpr,\\n    BT: tl.constexpr,\\n    BK: tl.constexpr,\\n    BV: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    core_id = tl.program_id(0)\\n    total_cores = tl.num_programs(0)\\n    T_max = T\\n\\n    base_chunks_per_pid = NT // total_cores\\n    remainder_chunks = NT % total_cores\\n\\n    if core_id < remainder_chunks:\\n        chunks_this_pid = base_chunks_per_pid + 1\\n        start_idx = core_id * chunks_this_pid\\n    else:\\n        chunks_this_pid = base_chunks_per_pid\\n        start_idx = core_id * chunks_this_pid + remainder_chunks\\n\\n    for idx in range(start_idx, start_idx + chunks_this_pid):\\n        for i_b in range(B):\\n            if IS_VARLEN:\\n                i_n, i_t = (\\n                    tl.load(chunk_indices + idx * 2).to(tl.int32),\\n                    tl.load(chunk_indices + idx * 2 + 1).to(tl.int32),\\n                )\\n                bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n                T = eos - bos\\n            else:\\n                i_t = idx\\n                bos, eos = i_b * T, i_b * T + T\\n\\n            o_t = i_t * BT + tl.arange(0, BT)\\n            m_t = o_t < T\\n            m_A = (o_t[:, None] > o_t[None, :]) & (m_t[:, None] & m_t)\\n            for i_h in range(0, H):\\n                if IS_VARLEN:\\n                    offset = bos + i_h * T_max\\n                else:\\n                    offset = bos * H + i_h * T_max\\n\\n                p_beta = tl.make_block_ptr(beta + offset, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                p_g = tl.make_block_ptr(g + offset, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                p_A = tl.make_block_ptr(\\n                    A + (bos * H + i_h) * BT, (BT, T), (1, H * BT), (0, i_t * BT), (BT, BT), (0, 1)\\n                )\\n\\n                b_A = tl.load(p_A, boundary_check=(0, 1))\\n                b_beta = tl.load(p_beta, boundary_check=(0,))\\n                b_g = tl.load(p_g, boundary_check=(0,))\\n                b_g_exp = tl.exp(b_g)\\n\\n                b_dbeta = tl.zeros([BT], dtype=tl.float32)\\n                b_dA = tl.zeros([BT, BT], dtype=tl.float32)\\n                b_dg = tl.zeros([BT], dtype=tl.float32)\\n\\n                for i_k in range(tl.cdiv(K, BK)):\\n                    p_k = tl.make_block_ptr(\\n                        k + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                    )\\n                    p_dk = tl.make_block_ptr(\\n                        dk + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                    )\\n                    p_dw = tl.make_block_ptr(\\n                        dw + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                    )\\n                    b_k = tl.load(p_k, boundary_check=(0, 1))\\n                    b_k_beta_g = (b_k * b_beta[:, None] * b_g_exp[:, None]).to(b_k.dtype)\\n                    b_dw = tl.load(p_dw, boundary_check=(0, 1))\\n                    b_dA += tl.dot(b_dw, tl.trans(b_k_beta_g))\\n                    b_dk_beta_g = tl.dot(b_A, b_dw)\\n                    b_dk = b_dk_beta_g * b_beta[:, None] * b_g_exp[:, None]\\n                    b_dbeta += tl.sum(b_dk_beta_g * b_k * b_g_exp[:, None], 1)\\n                    b_dg += tl.sum(b_dk_beta_g * b_k * b_g_exp[:, None] * b_beta[:, None], 1)\\n                    tl.store(p_dk, b_dk.to(p_dk.dtype.element_ty), boundary_check=(0, 1))\\n\\n                for i_v in range(tl.cdiv(V, BV)):\\n                    p_v = tl.make_block_ptr(\\n                        v + (bos * H + i_h) * V, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0)\\n                    )\\n                    p_dv = tl.make_block_ptr(\\n                        dv + (bos * H + i_h) * V, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0)\\n                    )\\n                    p_du = tl.make_block_ptr(\\n                        du + (bos * H + i_h) * V, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0)\\n                    )\\n                    b_v = tl.load(p_v, boundary_check=(0, 1))\\n                    b_v_beta = (b_v * b_beta[:, None]).to(b_v.dtype)\\n                    b_du = tl.load(p_du, boundary_check=(0, 1))\\n                    b_dA += tl.dot(b_du, tl.trans(b_v_beta))\\n                    b_dv_beta = tl.dot(b_A, b_du)\\n                    b_dv = b_dv_beta * b_beta[:, None]\\n                    b_dbeta += tl.sum(b_dv_beta * b_v, 1)\\n                    tl.store(p_dv, b_dv.to(p_dv.dtype.element_ty), boundary_check=(0, 1))\\n\\n                b_dA = tl.where(m_A, b_dA, 0)\\n                b_dA = tl.dot(b_dA.to(b_A.dtype), b_A)\\n                b_dA = tl.dot(b_A, b_dA.to(b_A.dtype))\\n                b_dA = tl.where(m_A, -b_dA * exp(b_g[:, None] - b_g[None, :]), 0)\\n                b_dA = b_dA.to(k.dtype.element_ty)\\n                b_A = tl.zeros([BT, BT], dtype=tl.float32)\\n\\n                for i_k in range(tl.cdiv(K, BK)):\\n                    p_k = tl.make_block_ptr(\\n                        k + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                    )\\n                    p_dk = tl.make_block_ptr(\\n                        dk + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                    )\\n                    b_k = tl.load(p_k, boundary_check=(0, 1))\\n                    b_dk = tl.load(p_dk, boundary_check=(0, 1))\\n                    b_k_beta = (b_k * b_beta[:, None]).to(b_k.dtype)\\n                    b_A += tl.dot(b_k_beta, tl.trans(b_k))\\n                    b_dk_beta = tl.dot(b_dA, b_k)\\n                    b_dbeta += tl.sum(b_dk_beta * b_k, 1)\\n                    b_dk += tl.dot(tl.trans(b_dA), b_k_beta)\\n                    b_dk += b_dk_beta * b_beta[:, None]\\n                    tl.store(p_dk, b_dk.to(p_dk.dtype.element_ty), boundary_check=(0, 1))\\n\\n                b_dA_A = b_dA * b_A\\n                b_dg += tl.sum(b_dA_A, axis=1) - tl.sum(b_dA_A, axis=0)\\n                p_dg = tl.make_block_ptr(dg + offset, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                p_dbeta = tl.make_block_ptr(dbeta + offset, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                tl.store(p_dg, b_dg.to(p_dg.dtype.element_ty), boundary_check=(0,))\\n                tl.store(p_dbeta, b_dbeta.to(p_dbeta.dtype.element_ty), boundary_check=(0,))\\n\\n\\n@triton.heuristics(\\n    {\\n        \\\"USE_G\\\": lambda args: args[\\\"g\\\"] is not None,\\n        \\\"USE_GK\\\": lambda args: args[\\\"gk\\\"] is not None,\\n        \\\"IS_VARLEN\\\": lambda args: args[\\\"cu_seqlens\\\"] is not None,\\n    }\\n)\\n@triton.jit(do_not_specialize=[\\\"T\\\"])\\ndef recompute_w_u_fwd_kernel(\\n    k,\\n    v,\\n    beta,\\n    w,\\n    u,\\n    A,\\n    g,\\n    gk,\\n    cu_seqlens,\\n    chunk_indices,\\n    T_tmp,\\n    B,\\n    H: tl.constexpr,\\n    K: tl.constexpr,\\n    V: tl.constexpr,\\n    NT: tl.constexpr,\\n    BT: tl.constexpr,\\n    BK: tl.constexpr,\\n    BV: tl.constexpr,\\n    USE_G: tl.constexpr,\\n    USE_GK: tl.constexpr,\\n    IS_VARLEN: tl.constexpr,\\n):\\n    core_id = tl.program_id(0)\\n    total_cores = tl.num_programs(0)\\n    T_max = T_tmp\\n\\n    base_chunks_per_pid = NT // total_cores\\n    remainder_chunks = NT % total_cores\\n\\n    if core_id < remainder_chunks:\\n        chunks_this_pid = base_chunks_per_pid + 1\\n        start_idx = core_id * chunks_this_pid\\n    else:\\n        chunks_this_pid = base_chunks_per_pid\\n        start_idx = core_id * chunks_this_pid + remainder_chunks\\n\\n    for idx in range(start_idx, start_idx + chunks_this_pid):\\n        for i_b in range(B):\\n            for i_h in range(0, H):\\n                if IS_VARLEN:\\n                    i_n, i_t = (\\n                        tl.load(chunk_indices + idx * 2).to(tl.int32),\\n                        tl.load(chunk_indices + idx * 2 + 1).to(tl.int32),\\n                    )\\n                    bos, eos = tl.load(cu_seqlens + i_n).to(tl.int32), tl.load(cu_seqlens + i_n + 1).to(tl.int32)\\n                    offset = bos + i_h * T_max\\n                    T = eos - bos\\n                else:\\n                    T = T_tmp\\n                    i_t = idx\\n                    bos, eos = i_b * T, i_b * T + T\\n                    offset = bos * H + i_h * T_max\\n\\n                p_beta = tl.make_block_ptr(beta + offset, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                b_beta = tl.load(p_beta, boundary_check=(0,))\\n\\n                p_A = tl.make_block_ptr(\\n                    A + (bos * H + i_h) * BT, (T, BT), (H * BT, 1), (i_t * BT, 0), (BT, BT), (1, 0)\\n                )\\n                b_A = tl.load(p_A, boundary_check=(0, 1))\\n\\n                for i_v in range(tl.cdiv(V, BV)):\\n                    p_v = tl.make_block_ptr(\\n                        v + (bos * H + i_h) * V, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0)\\n                    )\\n                    p_u = tl.make_block_ptr(\\n                        u + (bos * H + i_h) * V, (T, V), (H * V, 1), (i_t * BT, i_v * BV), (BT, BV), (1, 0)\\n                    )\\n                    b_v = tl.load(p_v, boundary_check=(0, 1))\\n                    b_vb = (b_v * b_beta[:, None]).to(b_v.dtype)\\n                    b_u = tl.dot(b_A, b_vb, allow_tf32=False)\\n                    tl.store(p_u, b_u.to(p_u.dtype.element_ty), boundary_check=(0, 1))\\n\\n                if USE_G:\\n                    p_g = tl.make_block_ptr(g + offset, (T,), (1,), (i_t * BT,), (BT,), (0,))\\n                    b_g = tl.exp(tl.load(p_g, boundary_check=(0,)))\\n\\n                for i_k in range(tl.cdiv(K, BK)):\\n                    p_k = tl.make_block_ptr(\\n                        k + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                    )\\n                    p_w = tl.make_block_ptr(\\n                        w + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                    )\\n                    b_k = tl.load(p_k, boundary_check=(0, 1))\\n                    b_kb = b_k * b_beta[:, None]\\n                    if USE_G:\\n                        b_kb *= b_g[:, None]\\n                    if USE_GK:\\n                        p_gk = tl.make_block_ptr(\\n                            gk + (bos * H + i_h) * K, (T, K), (H * K, 1), (i_t * BT, i_k * BK), (BT, BK), (1, 0)\\n                        )\\n                        b_kb *= tl.exp(tl.load(p_gk, boundary_check=(0, 1)))\\n                    b_w = tl.dot(b_A, b_kb.to(b_k.dtype))\\n                    tl.store(p_w, b_w.to(p_w.dtype.element_ty), boundary_check=(0, 1))\\n\\n\\ndef recompute_w_u_fwd(\\n    k: torch.Tensor,\\n    v: torch.Tensor,\\n    beta: torch.Tensor,\\n    A: torch.Tensor,\\n    g: Optional[torch.Tensor] = None,\\n    gk: Optional[torch.Tensor] = None,\\n    cu_seqlens: Optional[torch.LongTensor] = None,\\n) -> tuple[torch.Tensor, torch.Tensor]:\\n    B, T, H, K, V = *k.shape, v.shape[-1]\\n    BT = A.shape[-1]\\n    BK = 128\\n    BV = 128\\n\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n    NT = triton.cdiv(T, BT) if cu_seqlens is None else len(chunk_indices)\\n    g = g.transpose(1, 2).contiguous() if g is not None else None\\n    beta = beta.transpose(1, 2).contiguous()\\n\\n    w = torch.empty_like(k)\\n    u = torch.empty_like(v)\\n    cv_kernel_num = 24\\n    recompute_w_u_fwd_kernel[(cv_kernel_num,)](\\n        k=k,\\n        v=v,\\n        beta=beta,\\n        w=w,\\n        u=u,\\n        A=A,\\n        g=g,\\n        gk=gk,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        T_tmp=T,\\n        B=B,\\n        H=H,\\n        K=K,\\n        V=V,\\n        NT=NT,\\n        BT=BT,\\n        BK=BK,\\n        BV=BV,\\n    )\\n    return w, u\\n\\n\\ndef prepare_wy_repr_bwd(\\n    k: torch.Tensor,\\n    v: torch.Tensor,\\n    g: torch.Tensor,\\n    beta: torch.Tensor,\\n    A: torch.Tensor,\\n    dw: torch.Tensor,\\n    du: torch.Tensor,\\n    cu_seqlens: Optional[torch.LongTensor],\\n    chunk_size: int = 64,\\n) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:\\n    B, T, H, K, V = *k.shape, v.shape[-1]\\n    BT = chunk_size\\n    chunk_indices = prepare_chunk_indices(cu_seqlens, BT) if cu_seqlens is not None else None\\n    NT = triton.cdiv(T, BT) if cu_seqlens is None else len(chunk_indices)\\n    BK = 128\\n    BV = 128\\n    beta = beta.transpose(1, 2).contiguous()\\n    g = g.transpose(1, 2).contiguous()\\n\\n    dk = torch.empty_like(k)\\n    dv = torch.empty_like(v)\\n    dbeta = torch.empty_like(beta)\\n    dg = torch.empty_like(g)\\n\\n    cv_kernel_num = 24\\n    prepare_wy_repr_bwd_kernel[(cv_kernel_num,)](\\n        k=k,\\n        v=v,\\n        beta=beta,\\n        g=g,\\n        A=A,\\n        dw=dw,\\n        du=du,\\n        dk=dk,\\n        dv=dv,\\n        dbeta=dbeta,\\n        dg=dg,\\n        cu_seqlens=cu_seqlens,\\n        chunk_indices=chunk_indices,\\n        T=T,\\n        B=B,\\n        H=H,\\n        K=K,\\n        V=V,\\n        NT=NT,\\n        BT=BT,\\n        BK=BK,\\n        BV=BV,\\n    )\\n\\n    dbeta = dbeta.transpose(1, 2).contiguous()\\n    dg = dg.transpose(1, 2).contiguous()\\n\\n    return dk, dv, dbeta, dg\\n\\n\\nbwd_prepare_wy_repr = prepare_wy_repr_bwd\\n\\nfwd_recompute_w_u = recompute_w_u_fwd\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/callbacks.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5196dbbd851ea4dbb5469e07efd638578af1d9c3ca5a57dac2ae77832385adbd\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport fnmatch\\nimport json\\nimport os\\nimport signal\\nimport sys\\nimport time\\nfrom collections import defaultdict\\nfrom concurrent.futures import ThreadPoolExecutor\\nfrom datetime import timedelta\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nimport torch\\nimport transformers\\nfrom peft import PeftModel\\nfrom transformers import PreTrainedModel, ProcessorMixin, TrainerCallback\\nfrom transformers.trainer_utils import PREFIX_CHECKPOINT_DIR, has_length\\nfrom transformers.utils import SAFE_WEIGHTS_NAME, WEIGHTS_NAME\\nfrom typing_extensions import override\\n\\nfrom ..extras import logging\\nfrom ..extras.constants import TRAINER_LOG, V_HEAD_SAFE_WEIGHTS_NAME, V_HEAD_WEIGHTS_NAME\\nfrom ..extras.misc import get_peak_memory, is_env_enabled, is_torch_cuda_available, is_torch_npu_available, use_ray\\nfrom ..extras.packages import is_safetensors_available\\n\\n\\nif is_safetensors_available():\\n    from safetensors import safe_open\\n    from safetensors.torch import save_file\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import TrainerControl, TrainerState, TrainingArguments\\n    from trl import AutoModelForCausalLMWithValueHead\\n\\n    from ..hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef fix_valuehead_checkpoint(\\n    model: \\\"AutoModelForCausalLMWithValueHead\\\", output_dir: str, safe_serialization: bool\\n) -> None:\\n    r\\\"\\\"\\\"Fix the valuehead checkpoint files.\\n\\n    The model is already unwrapped.\\n\\n    There are three cases:\\n    1. full tuning without ds_zero3: state_dict = {\\\"model.layers.*\\\": ..., \\\"v_head.summary.*\\\": ...}\\n    2. lora tuning without ds_zero3: state_dict = {\\\"v_head.summary.*\\\": ...}\\n    3. under deepspeed zero3: state_dict = {\\\"pretrained_model.model.layers.*\\\": ..., \\\"v_head.summary.*\\\": ...}\\n\\n    We assume `stage3_gather_16bit_weights_on_model_save=true`.\\n    \\\"\\\"\\\"\\n    if not isinstance(model.pretrained_model, (PreTrainedModel, PeftModel)):\\n        return\\n\\n    if safe_serialization:\\n        path_to_checkpoint = os.path.join(output_dir, SAFE_WEIGHTS_NAME)\\n        with safe_open(path_to_checkpoint, framework=\\\"pt\\\", device=\\\"cpu\\\") as f:\\n            state_dict: dict[str, torch.Tensor] = {key: f.get_tensor(key).clone() for key in f.keys()}\\n    else:\\n        path_to_checkpoint = os.path.join(output_dir, WEIGHTS_NAME)\\n        state_dict: dict[str, torch.Tensor] = torch.load(path_to_checkpoint, map_location=\\\"cpu\\\", weights_only=True)\\n\\n    os.remove(path_to_checkpoint)\\n    decoder_state_dict, v_head_state_dict = {}, {}\\n    for name, param in state_dict.items():\\n        if name.startswith(\\\"v_head.\\\"):\\n            v_head_state_dict[name] = param\\n        else:\\n            decoder_state_dict[name.replace(\\\"pretrained_model.\\\", \\\"\\\", 1)] = param\\n\\n    model.pretrained_model.save_pretrained(\\n        output_dir, state_dict=decoder_state_dict or None, safe_serialization=safe_serialization\\n    )\\n\\n    if safe_serialization:\\n        save_file(v_head_state_dict, os.path.join(output_dir, V_HEAD_SAFE_WEIGHTS_NAME), metadata={\\\"format\\\": \\\"pt\\\"})\\n    else:\\n        torch.save(v_head_state_dict, os.path.join(output_dir, V_HEAD_WEIGHTS_NAME))\\n\\n    logger.info_rank0(f\\\"Value head model saved at: {output_dir}\\\")\\n\\n\\nclass FixValueHeadModelCallback(TrainerCallback):\\n    r\\\"\\\"\\\"A callback for fixing the checkpoint for valuehead models.\\\"\\\"\\\"\\n\\n    @override\\n    def on_save(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if args.should_save:\\n            output_dir = os.path.join(args.output_dir, f\\\"{PREFIX_CHECKPOINT_DIR}-{state.global_step}\\\")\\n            fix_valuehead_checkpoint(\\n                model=kwargs.pop(\\\"model\\\"),\\n                output_dir=output_dir,\\n                safe_serialization=getattr(args, \\\"save_safetensors\\\", True),\\n            )\\n\\n\\nclass SaveProcessorCallback(TrainerCallback):\\n    r\\\"\\\"\\\"A callback for saving the processor.\\\"\\\"\\\"\\n\\n    def __init__(self, processor: \\\"ProcessorMixin\\\") -> None:\\n        self.processor = processor\\n\\n    @override\\n    def on_save(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if args.should_save:\\n            output_dir = os.path.join(args.output_dir, f\\\"{PREFIX_CHECKPOINT_DIR}-{state.global_step}\\\")\\n            self.processor.save_pretrained(output_dir)\\n\\n    @override\\n    def on_train_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if args.should_save:\\n            self.processor.save_pretrained(args.output_dir)\\n\\n\\nclass PissaConvertCallback(TrainerCallback):\\n    r\\\"\\\"\\\"A callback for converting the PiSSA adapter to a normal one.\\\"\\\"\\\"\\n\\n    @override\\n    def on_train_begin(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if args.should_save:\\n            model = kwargs.pop(\\\"model\\\")\\n            pissa_init_dir = os.path.join(args.output_dir, \\\"pissa_init\\\")\\n            logger.info_rank0(f\\\"Initial PiSSA adapter will be saved at: {pissa_init_dir}.\\\")\\n            if isinstance(model, PeftModel):\\n                init_lora_weights = getattr(model.peft_config[\\\"default\\\"], \\\"init_lora_weights\\\")\\n                setattr(model.peft_config[\\\"default\\\"], \\\"init_lora_weights\\\", True)\\n                model.save_pretrained(pissa_init_dir, safe_serialization=getattr(args, \\\"save_safetensors\\\", True))\\n                setattr(model.peft_config[\\\"default\\\"], \\\"init_lora_weights\\\", init_lora_weights)\\n\\n    @override\\n    def on_train_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if args.should_save:\\n            model = kwargs.pop(\\\"model\\\")\\n            pissa_init_dir = os.path.join(args.output_dir, \\\"pissa_init\\\")\\n            pissa_backup_dir = os.path.join(args.output_dir, \\\"pissa_backup\\\")\\n            pissa_convert_dir = os.path.join(args.output_dir, \\\"pissa_converted\\\")\\n            logger.info_rank0(f\\\"Converted PiSSA adapter will be saved at: {pissa_convert_dir}.\\\")\\n            # 1. save a pissa backup with init_lora_weights: True\\n            # 2. save a converted lora with init_lora_weights: pissa\\n            # 3. load the pissa backup with init_lora_weights: True\\n            # 4. delete the initial adapter and change init_lora_weights to pissa\\n            if isinstance(model, PeftModel):\\n                init_lora_weights = getattr(model.peft_config[\\\"default\\\"], \\\"init_lora_weights\\\")\\n                setattr(model.peft_config[\\\"default\\\"], \\\"init_lora_weights\\\", True)\\n                model.save_pretrained(pissa_backup_dir, safe_serialization=getattr(args, \\\"save_safetensors\\\", True))\\n                setattr(model.peft_config[\\\"default\\\"], \\\"init_lora_weights\\\", init_lora_weights)\\n                model.save_pretrained(\\n                    pissa_convert_dir,\\n                    safe_serialization=getattr(args, \\\"save_safetensors\\\", True),\\n                    path_initial_model_for_weight_conversion=pissa_init_dir,\\n                )\\n                model.load_adapter(pissa_backup_dir, \\\"default\\\", is_trainable=True)\\n                model.set_adapter(\\\"default\\\")\\n                setattr(model.peft_config[\\\"default\\\"], \\\"init_lora_weights\\\", init_lora_weights)\\n\\n\\nclass LogCallback(TrainerCallback):\\n    r\\\"\\\"\\\"A callback for logging training and evaluation status.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        # Progress\\n        self.start_time = 0\\n        self.cur_steps = 0\\n        self.max_steps = 0\\n        self.elapsed_time = \\\"\\\"\\n        self.remaining_time = \\\"\\\"\\n        self.thread_pool: Optional[ThreadPoolExecutor] = None\\n        # Status\\n        self.aborted = False\\n        self.do_train = False\\n        # Web UI\\n        self.webui_mode = is_env_enabled(\\\"LLAMABOARD_ENABLED\\\")\\n        if self.webui_mode and not use_ray():\\n            signal.signal(signal.SIGABRT, self._set_abort)\\n            self.logger_handler = logging.LoggerHandler(os.getenv(\\\"LLAMABOARD_WORKDIR\\\"))\\n            logging.add_handler(self.logger_handler)\\n            transformers.logging.add_handler(self.logger_handler)\\n\\n    def _set_abort(self, signum, frame) -> None:\\n        self.aborted = True\\n\\n    def _reset(self, max_steps: int = 0) -> None:\\n        self.start_time = time.time()\\n        self.cur_steps = 0\\n        self.max_steps = max_steps\\n        self.elapsed_time = \\\"\\\"\\n        self.remaining_time = \\\"\\\"\\n\\n    def _timing(self, cur_steps: int) -> None:\\n        cur_time = time.time()\\n        elapsed_time = cur_time - self.start_time\\n        avg_time_per_step = elapsed_time / cur_steps if cur_steps != 0 else 0\\n        remaining_time = (self.max_steps - cur_steps) * avg_time_per_step\\n        self.cur_steps = cur_steps\\n        self.elapsed_time = str(timedelta(seconds=int(elapsed_time)))\\n        self.remaining_time = str(timedelta(seconds=int(remaining_time)))\\n\\n    def _write_log(self, output_dir: str, logs: dict[str, Any]) -> None:\\n        with open(os.path.join(output_dir, TRAINER_LOG), \\\"a\\\", encoding=\\\"utf-8\\\") as f:\\n            f.write(json.dumps(logs) + \\\"\\\\n\\\")\\n\\n    def _create_thread_pool(self, output_dir: str) -> None:\\n        os.makedirs(output_dir, exist_ok=True)\\n        self.thread_pool = ThreadPoolExecutor(max_workers=1)\\n\\n    def _close_thread_pool(self) -> None:\\n        if self.thread_pool is not None:\\n            self.thread_pool.shutdown(wait=True)\\n            self.thread_pool = None\\n\\n    @override\\n    def on_init_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if (\\n            args.should_save\\n            and os.path.exists(os.path.join(args.output_dir, TRAINER_LOG))\\n            and getattr(args, \\\"overwrite_output_dir\\\", False)\\n        ):\\n            logger.warning_rank0_once(\\\"Previous trainer log in this folder will be deleted.\\\")\\n            os.remove(os.path.join(args.output_dir, TRAINER_LOG))\\n\\n    @override\\n    def on_train_begin(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if args.should_save:\\n            self.do_train = True\\n            self._reset(max_steps=state.max_steps)\\n            self._create_thread_pool(output_dir=args.output_dir)\\n\\n    @override\\n    def on_train_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        self._close_thread_pool()\\n\\n    @override\\n    def on_substep_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if self.aborted:\\n            control.should_epoch_stop = True\\n            control.should_training_stop = True\\n\\n    @override\\n    def on_step_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if self.aborted:\\n            control.should_epoch_stop = True\\n            control.should_training_stop = True\\n\\n    @override\\n    def on_evaluate(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if not self.do_train:\\n            self._close_thread_pool()\\n\\n    @override\\n    def on_predict(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if not self.do_train:\\n            self._close_thread_pool()\\n\\n    @override\\n    def on_log(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if not args.should_save:\\n            return\\n\\n        self._timing(cur_steps=state.global_step)\\n        logs = dict(\\n            current_steps=self.cur_steps,\\n            total_steps=self.max_steps,\\n            loss=state.log_history[-1].get(\\\"loss\\\"),\\n            eval_loss=state.log_history[-1].get(\\\"eval_loss\\\"),\\n            predict_loss=state.log_history[-1].get(\\\"predict_loss\\\"),\\n            reward=state.log_history[-1].get(\\\"reward\\\"),\\n            accuracy=state.log_history[-1].get(\\\"rewards/accuracies\\\"),\\n            lr=state.log_history[-1].get(\\\"learning_rate\\\"),\\n            epoch=state.log_history[-1].get(\\\"epoch\\\"),\\n            percentage=round(self.cur_steps / self.max_steps * 100, 2) if self.max_steps != 0 else 100,\\n            elapsed_time=self.elapsed_time,\\n            remaining_time=self.remaining_time,\\n        )\\n        if state.num_input_tokens_seen:\\n            logs[\\\"throughput\\\"] = round(state.num_input_tokens_seen / (time.time() - self.start_time), 2)\\n            logs[\\\"total_tokens\\\"] = state.num_input_tokens_seen\\n\\n        if is_env_enabled(\\\"RECORD_VRAM\\\"):\\n            vram_allocated, vram_reserved = get_peak_memory()\\n            logs[\\\"vram_allocated\\\"] = round(vram_allocated / (1024**3), 2)\\n            logs[\\\"vram_reserved\\\"] = round(vram_reserved / (1024**3), 2)\\n\\n        logs = {k: v for k, v in logs.items() if v is not None}\\n        if self.webui_mode and all(key in logs for key in (\\\"loss\\\", \\\"lr\\\", \\\"epoch\\\")):\\n            log_str = f\\\"'loss': {logs['loss']:.4f}, 'learning_rate': {logs['lr']:2.4e}, 'epoch': {logs['epoch']:.2f}\\\"\\n            for extra_key in (\\\"reward\\\", \\\"accuracy\\\", \\\"throughput\\\"):\\n                if logs.get(extra_key):\\n                    log_str += f\\\", '{extra_key}': {logs[extra_key]:.2f}\\\"\\n\\n            logger.info_rank0(\\\"{\\\" + log_str + \\\"}\\\")\\n\\n        if self.thread_pool is not None:\\n            self.thread_pool.submit(self._write_log, args.output_dir, logs)\\n\\n    @override\\n    def on_prediction_step(\\n        self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs\\n    ):\\n        if self.do_train:\\n            return\\n\\n        if self.aborted:\\n            sys.exit(0)\\n\\n        if not args.should_save:\\n            return\\n\\n        eval_dataloader = kwargs.pop(\\\"eval_dataloader\\\", None)\\n        if has_length(eval_dataloader):\\n            if self.max_steps == 0:\\n                self._reset(max_steps=len(eval_dataloader))\\n                self._create_thread_pool(output_dir=args.output_dir)\\n\\n            self._timing(cur_steps=self.cur_steps + 1)\\n            if self.cur_steps % 5 == 0 and self.thread_pool is not None:\\n                logs = dict(\\n                    current_steps=self.cur_steps,\\n                    total_steps=self.max_steps,\\n                    percentage=round(self.cur_steps / self.max_steps * 100, 2) if self.max_steps != 0 else 100,\\n                    elapsed_time=self.elapsed_time,\\n                    remaining_time=self.remaining_time,\\n                )\\n                self.thread_pool.submit(self._write_log, args.output_dir, logs)\\n\\n\\nclass TorchProfilerCallback(TrainerCallback):\\n    r\\\"\\\"\\\"A callback for collecting torch.profiler traces during training.\\n\\n    Activated by setting ``enable_torch_profiler: true`` in the YAML config.\\n\\n    Configuration fields (in YAML):\\n      profiler_output_dir     \u2013 where to write traces (default: <output_dir>/profiler)\\n      profiler_wait_steps     \u2013 steps to skip at start of each cycle (default: 1)\\n      profiler_warmup_steps   \u2013 profiler warm-up steps per cycle       (default: 1)\\n      profiler_active_steps   \u2013 steps to record per cycle              (default: 1)\\n      profiler_repeat         \u2013 number of cycles; 0 = forever          (default: 1)\\n      profiler_record_shapes  \u2013 record tensor shapes (default: true)\\n      profiler_profile_memory \u2013 profile memory usage (default: true)\\n      profiler_with_stack     \u2013 record stack traces (default: true)\\n\\n    Trace files (one per rank, Chrome / TensorBoard JSON format) are written to\\n    ``<profiler_output_dir>/rank_<N>/``.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, training_args: \\\"TrainingArguments\\\") -> None:\\n        self.profiler = None\\n        self.profiler_args = training_args\\n\\n    @staticmethod\\n    def _get_rank() -> int:\\n        import torch.distributed as dist\\n\\n        if dist.is_available() and dist.is_initialized():\\n            return dist.get_rank()\\n        return 0\\n\\n    @override\\n    def on_train_begin(\\n        self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs\\n    ) -> None:\\n        if self.profiler is not None:\\n            self.profiler.stop()\\n            self.profiler = None\\n\\n        pa = self.profiler_args\\n        output_dir = pa.profiler_output_dir or os.path.join(args.output_dir, \\\"profiler\\\")\\n        rank = self._get_rank()\\n        trace_dir = os.path.join(output_dir, f\\\"rank_{rank}\\\")\\n        os.makedirs(trace_dir, exist_ok=True)\\n\\n        activities = [torch.profiler.ProfilerActivity.CPU]\\n        try:\\n            if is_torch_cuda_available():\\n                activities.append(torch.profiler.ProfilerActivity.CUDA)\\n            if is_torch_npu_available():\\n                activities.append(torch.profiler.ProfilerActivity.NPU)\\n        except Exception:\\n            pass\\n\\n        self.profiler = torch.profiler.profile(\\n            activities=activities,\\n            schedule=torch.profiler.schedule(\\n                wait=pa.profiler_wait_steps,\\n                warmup=pa.profiler_warmup_steps,\\n                active=pa.profiler_active_steps,\\n                repeat=pa.profiler_repeat,\\n            ),\\n            on_trace_ready=torch.profiler.tensorboard_trace_handler(trace_dir),\\n            record_shapes=pa.profiler_record_shapes,\\n            profile_memory=pa.profiler_profile_memory,\\n            with_stack=pa.profiler_with_stack,\\n        )\\n        self.profiler.start()\\n        logger.info_rank0(\\n            f\\\"TorchProfiler started \u2014 schedule: wait={pa.profiler_wait_steps}, warmup={pa.profiler_warmup_steps}, \\\"\\n            f\\\"active={pa.profiler_active_steps}, repeat={pa.profiler_repeat}. Traces \u2192 {output_dir}\\\"\\n        )\\n\\n    @override\\n    def on_step_end(\\n        self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs\\n    ) -> None:\\n        if self.profiler is not None:\\n            self.profiler.step()\\n\\n    @override\\n    def on_train_end(\\n        self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs\\n    ) -> None:\\n        if self.profiler is not None:\\n            self.profiler.stop()\\n            self.profiler = None\\n            logger.info_rank0(\\\"TorchProfiler stopped.\\\")\\n\\n\\nclass ReporterCallback(TrainerCallback):\\n    r\\\"\\\"\\\"A callback for reporting training status to external logger.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        model_args: \\\"ModelArguments\\\",\\n        data_args: \\\"DataArguments\\\",\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        generating_args: \\\"GeneratingArguments\\\",\\n    ) -> None:\\n        self.model_args = model_args\\n        self.data_args = data_args\\n        self.finetuning_args = finetuning_args\\n        self.generating_args = generating_args\\n        os.environ[\\\"WANDB_PROJECT\\\"] = os.getenv(\\\"WANDB_PROJECT\\\", \\\"llamafactory\\\")\\n\\n    @override\\n    def on_train_begin(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if not state.is_world_process_zero:\\n            return\\n\\n        if \\\"wandb\\\" in args.report_to:\\n            import wandb\\n\\n            wandb.config.update(\\n                {\\n                    \\\"model_args\\\": self.model_args.to_dict(),\\n                    \\\"data_args\\\": self.data_args.to_dict(),\\n                    \\\"finetuning_args\\\": self.finetuning_args.to_dict(),\\n                    \\\"generating_args\\\": self.generating_args.to_dict(),\\n                }\\n            )\\n\\n        if \\\"trackio\\\" in args.report_to:\\n            import trackio\\n\\n            trackio.config.update(\\n                {\\n                    \\\"model_args\\\": self.model_args.to_dict(),\\n                    \\\"data_args\\\": self.data_args.to_dict(),\\n                    \\\"finetuning_args\\\": self.finetuning_args.to_dict(),\\n                    \\\"generating_args\\\": self.generating_args.to_dict(),\\n                }\\n            )\\n\\n        if self.finetuning_args.use_swanlab:\\n            import swanlab  # type: ignore\\n\\n            swanlab.config.update(\\n                {\\n                    \\\"model_args\\\": self.model_args.to_dict(),\\n                    \\\"data_args\\\": self.data_args.to_dict(),\\n                    \\\"finetuning_args\\\": self.finetuning_args.to_dict(),\\n                    \\\"generating_args\\\": self.generating_args.to_dict(),\\n                }\\n            )\\n\\n\\nclass ModuleProfilerCallback(TrainerCallback):\\n    r\\\"\\\"\\\"Profile forward/backward time of specified modules using accelerator events.\\n\\n    Hooks are registered on modules matching the user-provided name patterns.\\n    Timing statistics are logged at each trainer logging step.\\n\\n    Usage in YAML config:\\n        profile_modules: \\\"*.layers.0.self_attn,*.layers.0.mlp\\\"\\n\\n    Supports fnmatch wildcards:\\n        profile_modules: \\\"*.layers.*.self_attn,*.layers.*.mlp.experts\\\"\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _get_accelerator():\\n        \\\"\\\"\\\"Detect available accelerator and return (event_factory, synchronize_fn).\\\"\\\"\\\"\\n        if is_torch_cuda_available():\\n            return torch.cuda.Event, torch.cuda.synchronize\\n        if is_torch_npu_available():\\n            return torch.npu.Event, torch.npu.synchronize\\n        return None, None\\n\\n    def __init__(self, profile_modules: str) -> None:\\n        self.patterns = [p.strip() for p in profile_modules.split(\\\",\\\") if p.strip()]\\n        self._create_event, self._synchronize = self._get_accelerator()\\n        self._handles: list[Any] = []\\n        self._forward_times: dict[str, list[float]] = defaultdict(list)\\n        self._backward_times: dict[str, list[float]] = defaultdict(list)\\n        self._pending_forward: dict[str, tuple] = {}\\n        self._pending_backward: dict[str, tuple] = {}\\n\\n    @property\\n    def enabled(self) -> bool:\\n        return self._create_event is not None\\n\\n    def _match(self, name: str) -> bool:\\n        return any(fnmatch.fnmatch(name, pat) for pat in self.patterns)\\n\\n    def _make_forward_pre_hook(self, name: str):\\n        def hook(module, input):\\n            start = self._create_event(enable_timing=True)\\n            end = self._create_event(enable_timing=True)\\n            start.record()\\n            self._pending_forward[name] = (start, end)\\n\\n        return hook\\n\\n    def _make_forward_hook(self, name: str):\\n        def hook(module, input, output):\\n            pair = self._pending_forward.get(name)\\n            if pair is not None:\\n                pair[1].record()\\n\\n        return hook\\n\\n    def _make_backward_pre_hook(self, name: str):\\n        def hook(module, grad_output):\\n            start = self._create_event(enable_timing=True)\\n            end = self._create_event(enable_timing=True)\\n            start.record()\\n            self._pending_backward[name] = (start, end)\\n\\n        return hook\\n\\n    def _make_backward_hook(self, name: str):\\n        def hook(module, grad_input, grad_output):\\n            pair = self._pending_backward.get(name)\\n            if pair is not None:\\n                pair[1].record()\\n\\n        return hook\\n\\n    @override\\n    def on_train_begin(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if not self.enabled:\\n            logger.warning_rank0(\\\"ModuleProfiler: no supported accelerator (CUDA/NPU) found, profiling disabled.\\\")\\n            return\\n\\n        model = kwargs.get(\\\"model\\\")\\n        if model is None:\\n            return\\n\\n        matched = []\\n        for name, module in model.named_modules():\\n            if not name or not self._match(name):\\n                continue\\n            self._handles.append(module.register_forward_pre_hook(self._make_forward_pre_hook(name)))\\n            self._handles.append(module.register_forward_hook(self._make_forward_hook(name)))\\n            self._handles.append(module.register_full_backward_pre_hook(self._make_backward_pre_hook(name)))\\n            self._handles.append(module.register_full_backward_hook(self._make_backward_hook(name)))\\n            matched.append(name)\\n\\n        if matched:\\n            logger.info_rank0(\\n                f\\\"ModuleProfiler: registered hooks on {len(matched)} modules: {matched[:5]}\\\"\\n                + (f\\\" ... (+{len(matched) - 5} more)\\\" if len(matched) > 5 else \\\"\\\")\\n            )\\n        else:\\n            logger.warning_rank0(f\\\"ModuleProfiler: no modules matched patterns {self.patterns}\\\")\\n\\n    @override\\n    def on_step_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if not self.enabled:\\n            return\\n\\n        self._synchronize()\\n\\n        for name, (start, end) in self._pending_forward.items():\\n            self._forward_times[name].append(start.elapsed_time(end))\\n        self._pending_forward.clear()\\n\\n        for name, (start, end) in self._pending_backward.items():\\n            self._backward_times[name].append(start.elapsed_time(end))\\n        self._pending_backward.clear()\\n\\n    @override\\n    def on_log(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        if not self._forward_times and not self._backward_times:\\n            return\\n\\n        lines = [\\\"[ModuleProfiler] Timing (ms):\\\"]\\n        all_names = sorted(set(list(self._forward_times.keys()) + list(self._backward_times.keys())))\\n        for name in all_names:\\n            fwd = self._forward_times.get(name, [])\\n            bwd = self._backward_times.get(name, [])\\n            fwd_mean = sum(fwd) / len(fwd) if fwd else 0.0\\n            bwd_mean = sum(bwd) / len(bwd) if bwd else 0.0\\n            lines.append(f\\\"  {name}: fwd={fwd_mean:.3f}, bwd={bwd_mean:.3f}, total={fwd_mean + bwd_mean:.3f}\\\")\\n\\n        logger.info_rank0(\\\"\\\\n\\\".join(lines))\\n        self._forward_times.clear()\\n        self._backward_times.clear()\\n\\n    @override\\n    def on_train_end(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", control: \\\"TrainerControl\\\", **kwargs):\\n        for handle in self._handles:\\n            handle.remove()\\n        self._handles.clear()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/dpo/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9b2dbca82aee3f7704500647336a7956d6029552020c1c5de7f1e2ec6d9cca9b\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_dpo\\n\\n\\n__all__ = [\\\"run_dpo\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/dpo/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"18e4df235abb1a667f73d7f71f1c69ed7e3efcaa2a181ead994b4ffcbfcd0a38\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's TRL library.\\n# https://github.com/huggingface/trl/blob/v0.8.0/trl/trainer/dpo_trainer.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport warnings\\nfrom collections import defaultdict\\nfrom contextlib import nullcontext\\nfrom types import MethodType\\nfrom typing import TYPE_CHECKING, Literal, Optional, Union\\n\\nimport torch\\nimport torch.nn.functional as F\\nfrom transformers import Trainer\\nfrom trl import DPOTrainer\\nfrom trl.models.utils import prepare_deepspeed, prepare_fsdp\\nfrom trl.trainer import disable_dropout_in_model\\nfrom typing_extensions import override\\n\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ...extras.packages import is_transformers_version_greater_than\\nfrom ..callbacks import SaveProcessorCallback\\nfrom ..trainer_utils import create_custom_optimizer, create_custom_scheduler, get_batch_logps, nested_detach\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel, ProcessorMixin\\n\\n    from ...hparams import FinetuningArguments\\n\\n\\nclass CustomDPOTrainer(DPOTrainer):\\n    def __init__(\\n        self,\\n        model: Union[\\\"PreTrainedModel\\\", torch.nn.Module],\\n        ref_model: Optional[Union[\\\"PreTrainedModel\\\", torch.nn.Module]],\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        disable_dropout: bool = True,\\n        **kwargs,\\n    ):\\n        if is_transformers_version_greater_than(\\\"4.46\\\"):\\n            kwargs[\\\"processing_class\\\"] = kwargs.pop(\\\"tokenizer\\\")\\n\\n        if disable_dropout:\\n            disable_dropout_in_model(model)\\n            if ref_model is not None:\\n                disable_dropout_in_model(ref_model)\\n\\n        self.finetuning_args = finetuning_args\\n        self.f_divergence_type = \\\"reverse_kl\\\"\\n        self.reference_free = False\\n        self.use_dpo_data_collator = True  # hack to avoid warning\\n        self.generate_during_eval = False  # disable at evaluation\\n        self.label_pad_token_id = IGNORE_INDEX\\n        self.padding_value = 0\\n        self.is_encoder_decoder = model.config.is_encoder_decoder\\n        self.precompute_ref_log_probs = False\\n        self._precomputed_train_ref_log_probs = False\\n        self._precomputed_eval_ref_log_probs = False\\n        self._peft_has_been_casted_to_bf16 = False\\n\\n        self.ref_model = ref_model\\n        self._stored_metrics = defaultdict(lambda: defaultdict(list))\\n\\n        # dpo hyperparams\\n        self.beta = finetuning_args.pref_beta\\n        self.loss_type = finetuning_args.pref_loss\\n        self.ftx_gamma = finetuning_args.pref_ftx\\n        self.bco_gemma = finetuning_args.pref_bco_weight\\n        self.label_smoothing = finetuning_args.dpo_label_smoothing\\n        self.simpo_gamma = finetuning_args.simpo_gamma\\n        self.ld_alpha = finetuning_args.ld_alpha\\n\\n        Trainer.__init__(self, model=model, **kwargs)\\n        self.model_accepts_loss_kwargs = False  # overwrite trainer's default behavior\\n        if not hasattr(self, \\\"accelerator\\\"):\\n            raise AttributeError(\\\"Please update `transformers`.\\\")\\n\\n        warnings.simplefilter(\\\"ignore\\\")  # remove gc warnings on ref model\\n\\n        if ref_model is not None:\\n            if self.is_deepspeed_enabled:\\n                if not (\\n                    getattr(ref_model, \\\"is_loaded_in_8bit\\\", False) or getattr(ref_model, \\\"is_loaded_in_4bit\\\", False)\\n                ):  # quantized models are already set on the correct device\\n                    self.ref_model = prepare_deepspeed(self.ref_model, self.accelerator)\\n            elif self.is_fsdp_enabled:\\n                if self.accelerator.is_fsdp2:\\n                    from accelerate.utils.fsdp_utils import fsdp2_prepare_model\\n\\n                    self.ref_model = fsdp2_prepare_model(self.accelerator, self.ref_model)\\n                else:\\n                    self.ref_model = prepare_fsdp(self.ref_model, self.accelerator)\\n            else:\\n                self.ref_model = self.accelerator.prepare_model(self.ref_model, evaluation_mode=True)\\n                self.ref_model.eval()\\n\\n        if processor is not None:\\n            self.add_callback(SaveProcessorCallback(processor))\\n\\n        if finetuning_args.use_badam:\\n            from badam import BAdamCallback, clip_grad_norm_old_version  # type: ignore\\n\\n            self.accelerator.clip_grad_norm_ = MethodType(clip_grad_norm_old_version, self.accelerator)\\n            self.add_callback(BAdamCallback)\\n\\n        if self.bco_gemma >= 1e-6:\\n            from trl.trainer import RunningMoments\\n\\n            self.running = RunningMoments(self.accelerator)\\n\\n    @override\\n    def create_optimizer(self, *args, **kwargs) -> \\\"torch.optim.Optimizer\\\":\\n        if self.optimizer is None:\\n            self.optimizer = create_custom_optimizer(self.model, self.args, self.finetuning_args)\\n        return super().create_optimizer(*args, **kwargs)\\n\\n    @override\\n    def create_scheduler(\\n        self, num_training_steps: int, optimizer: Optional[\\\"torch.optim.Optimizer\\\"] = None\\n    ) -> \\\"torch.optim.lr_scheduler.LRScheduler\\\":\\n        create_custom_scheduler(self.args, num_training_steps, optimizer)\\n        return super().create_scheduler(num_training_steps, optimizer)\\n\\n    @override\\n    def _get_train_sampler(self, *args, **kwargs) -> Optional[\\\"torch.utils.data.Sampler\\\"]:\\n        if self.finetuning_args.disable_shuffling:\\n            return torch.utils.data.SequentialSampler(self.train_dataset)\\n\\n        return super()._get_train_sampler(*args, **kwargs)\\n\\n    @override\\n    def get_batch_samples(self, *args, **kwargs):\\n        r\\\"\\\"\\\"Replace the method of DPO Trainer with the one of the standard Trainer.\\\"\\\"\\\"\\n        return Trainer.get_batch_samples(self, *args, **kwargs)\\n\\n    def odds_ratio_loss(self, chosen_logps: \\\"torch.Tensor\\\", rejected_logps: \\\"torch.Tensor\\\") -> \\\"torch.Tensor\\\":\\n        r\\\"\\\"\\\"Compute ORPO's odds ratio (OR) loss for batched log probabilities of the policy model.\\\"\\\"\\\"\\n        log_odds = (chosen_logps - rejected_logps) - (\\n            torch.log1p(-torch.exp(chosen_logps)) - torch.log1p(-torch.exp(rejected_logps))\\n        )\\n        sft_loss = -chosen_logps\\n        odds_ratio_loss = -F.logsigmoid(log_odds)\\n        orpo_loss = sft_loss + self.beta * odds_ratio_loss\\n        return orpo_loss\\n\\n    def simpo_loss(self, chosen_logps: \\\"torch.Tensor\\\", rejected_logps: \\\"torch.Tensor\\\") -> \\\"torch.Tensor\\\":\\n        r\\\"\\\"\\\"Compute SimPO loss for batched log probabilities of the policy model.\\\"\\\"\\\"\\n        pi_logratios = chosen_logps - rejected_logps\\n        gamma_logratios = self.simpo_gamma / self.beta\\n        logits = pi_logratios - gamma_logratios\\n        simpo_loss = -F.logsigmoid(self.beta * logits)\\n        return simpo_loss\\n\\n    def bco_loss(\\n        self,\\n        chosen_logps: \\\"torch.Tensor\\\",\\n        rejected_logps: \\\"torch.Tensor\\\",\\n        reference_chosen_logps: \\\"torch.Tensor\\\",\\n        reference_rejected_logps: \\\"torch.Tensor\\\",\\n    ) -> \\\"torch.Tensor\\\":\\n        chosen_logratios = chosen_logps - reference_chosen_logps\\n        rejected_logratios = rejected_logps - reference_rejected_logps\\n        chosen_rewards = self.beta * chosen_logratios\\n        rejected_rewards = self.beta * rejected_logratios\\n        rewards = torch.cat((chosen_rewards, rejected_rewards), 0).mean().detach()\\n        self.running.update(rewards)  # update baseline\\n        delta = self.running.mean\\n        bco_loss = -F.logsigmoid((self.beta * chosen_logratios) - delta) - F.logsigmoid(\\n            -(self.beta * rejected_logratios - delta)\\n        )\\n        return bco_loss\\n\\n    def compute_preference_loss(\\n        self,\\n        policy_chosen_logps: \\\"torch.Tensor\\\",\\n        policy_rejected_logps: \\\"torch.Tensor\\\",\\n        reference_chosen_logps: Optional[\\\"torch.Tensor\\\"],\\n        reference_rejected_logps: Optional[\\\"torch.Tensor\\\"],\\n    ) -> tuple[\\\"torch.Tensor\\\", \\\"torch.Tensor\\\", \\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Compute loss for preference learning.\\\"\\\"\\\"\\n        if not self.finetuning_args.use_ref_model:\\n            if self.loss_type == \\\"orpo\\\":\\n                losses = self.odds_ratio_loss(policy_chosen_logps, policy_rejected_logps)\\n            elif self.loss_type == \\\"simpo\\\":\\n                losses = self.simpo_loss(policy_chosen_logps, policy_rejected_logps)\\n            else:\\n                raise NotImplementedError(f\\\"Unknown loss type: {self.loss_type}.\\\")\\n\\n            chosen_rewards = self.beta * policy_chosen_logps.to(self.accelerator.device).detach()\\n            rejected_rewards = self.beta * policy_rejected_logps.to(self.accelerator.device).detach()\\n        else:\\n            losses, chosen_rewards, rejected_rewards = self.dpo_loss(\\n                policy_chosen_logps, policy_rejected_logps, reference_chosen_logps, reference_rejected_logps\\n            )\\n\\n            if self.bco_gemma > 1e-6:\\n                bco_losses = self.bco_loss(\\n                    policy_chosen_logps, policy_rejected_logps, reference_chosen_logps, reference_rejected_logps\\n                )\\n                losses = (losses + bco_losses * self.bco_gemma) / (1.0 + self.bco_gemma)  # re-weight W_p and W_q\\n\\n        return losses, chosen_rewards, rejected_rewards\\n\\n    @override\\n    def concatenated_forward(\\n        self, model: \\\"PreTrainedModel\\\", batch: dict[str, \\\"torch.Tensor\\\"], is_ref_model: bool = False\\n    ) -> dict[str, \\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Compute the sum log probabilities of the labels under given logits if loss_type is not IPO, ORPO or SimPO.\\n\\n        Otherwise the average log probabilities.\\n        \\\"\\\"\\\"\\n        if self.finetuning_args.use_ref_model:\\n            batch = nested_detach(batch, clone=True)  # avoid error\\n\\n        labels = batch.pop(\\\"labels\\\")  # dpo do not need compute loss in forward\\n        all_logits: torch.Tensor = model(**batch, return_dict=True, use_cache=False).logits.to(torch.float32)\\n        all_logps, valid_length = get_batch_logps(\\n            logits=all_logits, labels=labels, ld_alpha=(self.ld_alpha if not is_ref_model else None)\\n        )\\n        if self.loss_type in [\\\"ipo\\\", \\\"orpo\\\", \\\"simpo\\\"]:\\n            all_logps = all_logps / valid_length\\n\\n        batch_size = batch[\\\"input_ids\\\"].size(0) // 2\\n        chosen_logps, rejected_logps = all_logps.split(batch_size, dim=0)\\n        chosen_logits, rejected_logits = all_logits.split(batch_size, dim=0)\\n        chosen_length, _ = valid_length.split(batch_size, dim=0)\\n        if self.loss_type in [\\\"ipo\\\", \\\"orpo\\\", \\\"simpo\\\"]:\\n            chosen_logps_avg = chosen_logps\\n        else:\\n            chosen_logps_avg = chosen_logps / chosen_length\\n\\n        return {\\n            \\\"chosen_logps\\\": chosen_logps,\\n            \\\"rejected_logps\\\": rejected_logps,\\n            \\\"chosen_logits\\\": chosen_logits,\\n            \\\"rejected_logits\\\": rejected_logits,\\n            \\\"chosen_logps_avg\\\": chosen_logps_avg,\\n        }\\n\\n    @override\\n    def compute_reference_log_probs(\\n        self, model: \\\"PreTrainedModel\\\", batch: dict[str, \\\"torch.Tensor\\\"]\\n    ) -> tuple[Optional[\\\"torch.Tensor\\\"], Optional[\\\"torch.Tensor\\\"]]:\\n        r\\\"\\\"\\\"Compute log probabilities of the reference model.\\\"\\\"\\\"\\n        if not self.finetuning_args.use_ref_model:\\n            return None, None\\n\\n        if self.ref_model is None:\\n            ref_model = model\\n            ref_context = self.accelerator.unwrap_model(model).disable_adapter()\\n        else:\\n            ref_model = self.ref_model\\n            ref_context = nullcontext()\\n\\n        with torch.no_grad(), ref_context:\\n            ref_output = self.concatenated_forward(ref_model, batch, is_ref_model=True)\\n            reference_chosen_logps = ref_output[\\\"chosen_logps\\\"]\\n            reference_rejected_logps = ref_output[\\\"rejected_logps\\\"]\\n\\n        return reference_chosen_logps, reference_rejected_logps\\n\\n    @override\\n    def get_batch_loss_metrics(\\n        self,\\n        model: \\\"PreTrainedModel\\\",\\n        batch: dict[str, \\\"torch.Tensor\\\"],\\n        train_eval: Literal[\\\"train\\\", \\\"eval\\\"] = \\\"train\\\",\\n    ) -> tuple[\\\"torch.Tensor\\\", dict[str, \\\"torch.Tensor\\\"]]:\\n        r\\\"\\\"\\\"Compute the DPO loss and other metrics for the given batch of inputs for train or test.\\\"\\\"\\\"\\n        metrics = {}\\n\\n        model_output = self.concatenated_forward(model, batch)\\n        policy_chosen_logps = model_output[\\\"chosen_logps\\\"]\\n        policy_rejected_logps = model_output[\\\"rejected_logps\\\"]\\n        policy_chosen_logits = model_output[\\\"chosen_logits\\\"]\\n        policy_rejected_logits = model_output[\\\"rejected_logits\\\"]\\n        policy_chosen_logps_avg = model_output[\\\"chosen_logps_avg\\\"]\\n\\n        reference_chosen_logps, reference_rejected_logps = self.compute_reference_log_probs(model, batch)\\n        losses, chosen_rewards, rejected_rewards = self.compute_preference_loss(\\n            policy_chosen_logps,\\n            policy_rejected_logps,\\n            reference_chosen_logps,\\n            reference_rejected_logps,\\n        )\\n        sft_loss = -policy_chosen_logps_avg\\n        if self.ftx_gamma > 1e-6:\\n            losses += self.ftx_gamma * sft_loss\\n\\n        prefix = \\\"eval_\\\" if train_eval == \\\"eval\\\" else \\\"\\\"\\n        metrics[f\\\"{prefix}rewards/chosen\\\"] = chosen_rewards.mean().item()\\n        metrics[f\\\"{prefix}rewards/rejected\\\"] = rejected_rewards.mean().item()\\n        metrics[f\\\"{prefix}rewards/accuracies\\\"] = (chosen_rewards > rejected_rewards).float().mean().item()\\n        metrics[f\\\"{prefix}rewards/margins\\\"] = (chosen_rewards - rejected_rewards).mean().item()\\n        metrics[f\\\"{prefix}logps/chosen\\\"] = policy_chosen_logps.mean().item()\\n        metrics[f\\\"{prefix}logps/rejected\\\"] = policy_rejected_logps.mean().item()\\n        metrics[f\\\"{prefix}logits/chosen\\\"] = policy_chosen_logits.mean().item()\\n        metrics[f\\\"{prefix}logits/rejected\\\"] = policy_rejected_logits.mean().item()\\n        if self.loss_type == \\\"orpo\\\":\\n            metrics[f\\\"{prefix}sft_loss\\\"] = sft_loss.mean().item()\\n            metrics[f\\\"{prefix}odds_ratio_loss\\\"] = ((losses - sft_loss) / self.beta).mean().item()\\n\\n        return losses.mean(), metrics\\n\\n    @override\\n    def compute_loss(\\n        self, model: \\\"PreTrainedModel\\\", inputs: dict[str, \\\"torch.Tensor\\\"], return_outputs: bool = False, **kwargs\\n    ) -> Union[\\\"torch.Tensor\\\", tuple[\\\"torch.Tensor\\\", list[\\\"torch.Tensor\\\"]]]:\\n        r\\\"\\\"\\\"Subclass and override to accept extra kwargs.\\\"\\\"\\\"\\n        return super().compute_loss(model, inputs, return_outputs)\\n\\n    @override\\n    def log(self, logs: dict[str, float], *args, **kwargs) -> None:\\n        r\\\"\\\"\\\"Log `logs` on the various objects watching training, including stored metrics.\\\"\\\"\\\"\\n        # logs either has \\\"loss\\\" or \\\"eval_loss\\\"\\n        train_eval = \\\"train\\\" if \\\"loss\\\" in logs else \\\"eval\\\"\\n        # Add averaged stored metrics to logs\\n        key_list, metric_list = [], []\\n        for key, metrics in self._stored_metrics[train_eval].items():\\n            key_list.append(key)\\n            metric_list.append(torch.tensor(metrics, dtype=torch.float).to(self.accelerator.device).mean().item())\\n\\n        del self._stored_metrics[train_eval]\\n        if len(metric_list) < 10:  # pad to for all reduce\\n            for i in range(10 - len(metric_list)):\\n                key_list.append(f\\\"dummy_{i}\\\")\\n                metric_list.append(0.0)\\n\\n        metric_list = torch.tensor(metric_list, dtype=torch.float).to(self.accelerator.device)\\n        metric_list = self.accelerator.reduce(metric_list, \\\"mean\\\").tolist()\\n        for key, metric in zip(key_list, metric_list):  # add remaining items\\n            if not key.startswith(\\\"dummy_\\\"):\\n                logs[key] = metric\\n\\n        return Trainer.log(self, logs, *args, **kwargs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/dpo/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6335d87cba184b03d7f552789cdf01b8591f6dd7e9666e07fd566454d0f9ab6b\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's TRL library.\\n# https://github.com/huggingface/trl/blob/v0.8.0/examples/scripts/dpo.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom ...data import PairwiseDataCollatorWithPadding, get_dataset, get_template_and_fix_tokenizer\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ...extras.misc import calculate_tps\\nfrom ...extras.ploting import plot_loss\\nfrom ...hparams import ModelArguments\\nfrom ...model import load_model, load_tokenizer\\nfrom ..trainer_utils import create_modelcard_and_push, create_ref_model\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import Seq2SeqTrainingArguments, TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments\\n\\n\\ndef run_dpo(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"rm\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train)\\n\\n    data_collator = PairwiseDataCollatorWithPadding(\\n        template=template,\\n        model=model,\\n        pad_to_multiple_of=8,\\n        label_pad_token_id=IGNORE_INDEX if data_args.ignore_pad_token_for_loss else tokenizer.pad_token_id,\\n        **tokenizer_module,\\n    )\\n\\n    # Create reference model\\n    if finetuning_args.use_ref_model:\\n        if finetuning_args.ref_model is None and (not training_args.do_train):  # use the model itself\\n            ref_model = model\\n        else:\\n            ref_model = create_ref_model(model_args, finetuning_args)\\n    else:\\n        ref_model = None\\n\\n    from .trainer import CustomDPOTrainer\\n\\n    # Initialize our Trainer\\n    trainer = CustomDPOTrainer(\\n        model=model,\\n        ref_model=ref_model,\\n        args=training_args,\\n        finetuning_args=finetuning_args,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        **dataset_module,\\n        **tokenizer_module,\\n    )\\n\\n    # Training\\n    if training_args.do_train:\\n        train_result = trainer.train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        if finetuning_args.include_effective_tokens_per_second:\\n            train_result.metrics[\\\"effective_tokens_per_sec\\\"] = calculate_tps(\\n                dataset_module[\\\"train_dataset\\\"], train_result.metrics, stage=\\\"rm\\\"\\n            )\\n\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\", \\\"rewards/accuracies\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += [f\\\"eval_{key}_loss\\\" for key in dataset_module[\\\"eval_dataset\\\"].keys()]\\n            else:\\n                keys += [\\\"eval_loss\\\"]\\n\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n    # Evaluation\\n    if training_args.do_eval:\\n        metrics = trainer.evaluate(metric_key_prefix=\\\"eval\\\")\\n        if id(model) == id(ref_model):  # unable to compute rewards if reference model is the model itself\\n            remove_keys = [key for key in metrics.keys() if \\\"rewards\\\" in key]\\n            for key in remove_keys:\\n                metrics.pop(key)\\n        trainer.log_metrics(\\\"eval\\\", metrics)\\n        trainer.save_metrics(\\\"eval\\\", metrics)\\n\\n    # Create model card\\n    create_modelcard_and_push(trainer, model_args, data_args, training_args, finetuning_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/fp8_utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"01e019057b2cacd633ea11a8411742634b6bace27da32adbdc05ab26e2eddea1\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\nimport types\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nfrom ..extras import logging\\n\\n\\nif TYPE_CHECKING:\\n    from ..hparams import TrainingArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef create_fp8_kwargs(training_args: \\\"TrainingArguments\\\") -> list[Any]:\\n    \\\"\\\"\\\"Create AORecipeKwargs for FP8 training with HuggingFace Accelerate.\\n\\n    Args:\\n        training_args: Training arguments containing FP8 configuration\\n\\n    Returns:\\n        List containing AORecipeKwargs if FP8 is enabled and supported, empty list otherwise\\n    \\\"\\\"\\\"\\n    if not training_args.fp8:\\n        return []\\n\\n    backend = getattr(training_args, \\\"fp8_backend\\\", \\\"auto\\\")\\n    logger.info_rank0(f\\\"Creating FP8 configuration with backend: {backend}\\\")\\n\\n    try:\\n        # Use Transformer Engine backend (optimal for Hopper GPUs)\\n        if backend == \\\"te\\\":\\n            from accelerate.utils import FP8RecipeKwargs\\n\\n            logger.info_rank0(\\\"Using Transformer Engine FP8 backend\\\")\\n            return [FP8RecipeKwargs(backend=\\\"TE\\\", fp8_format=\\\"HYBRID\\\", amax_history_len=16, amax_compute_algo=\\\"max\\\")]\\n\\n        # Use TorchAO backend (default)\\n        from accelerate.utils import AORecipeKwargs\\n\\n        # Create Float8LinearConfig if torchao backend is used\\n        config = None\\n        if backend == \\\"torchao\\\" or backend == \\\"auto\\\":\\n            from torchao.float8 import Float8LinearConfig\\n\\n            # Use rowwise scaling for better performance (as recommended by torchao)\\n            # Configure alignment requirements for FP8 kernels\\n            config = Float8LinearConfig.from_recipe_name(\\\"rowwise\\\")\\n\\n            # Enable alignment for better kernel performance\\n            if hasattr(config, \\\"enable_amax_init\\\"):\\n                config.enable_amax_init = True\\n            if hasattr(config, \\\"enable_pre_and_post_forward\\\"):\\n                config.enable_pre_and_post_forward = True\\n\\n        # Create module filter function to skip problematic layers\\n        # TorchAO FP8 requires dimensions divisible by 16 for optimal kernels\\n        def module_filter_func(module, layer_name):\\n            # Skip embedding and output layers for numerical stability\\n            skip_layers = [\\\"embed\\\", \\\"lm_head\\\", \\\"output\\\", \\\"classifier\\\"]\\n            if any(skip_name in layer_name.lower() for skip_name in skip_layers):\\n                return False\\n\\n            # Only convert Linear layers\\n            if not (hasattr(module, \\\"weight\\\") and len(module.weight.shape) == 2):\\n                return False\\n\\n            # Check dimension alignment for FP8 kernels\\n            weight = module.weight\\n            in_features, out_features = weight.shape[1], weight.shape[0]\\n\\n            # Skip layers with dimensions not divisible by 16 to avoid kernel errors\\n            if in_features % 16 != 0 or out_features % 16 != 0:\\n                logger.debug(\\n                    f\\\"Skipping layer {layer_name} with dimensions {out_features}x{in_features} (not divisible by 16)\\\"\\n                )\\n                return False\\n\\n            return True\\n\\n        # Map FSDP all-gather setting if available (this affects the underlying implementation)\\n        if (\\n            hasattr(training_args, \\\"fp8_enable_fsdp_float8_all_gather\\\")\\n            and training_args.fp8_enable_fsdp_float8_all_gather\\n        ):\\n            logger.info_rank0(\\\"FSDP float8 all-gather optimization requested\\\")\\n\\n        return [AORecipeKwargs(config=config, module_filter_func=module_filter_func)]\\n    except Exception as e:\\n        logger.info_rank0(f\\\"Failed to create FP8 configuration: {e}\\\")\\n        return []\\n\\n\\ndef get_fp8_mixed_precision(training_args: \\\"TrainingArguments\\\") -> Optional[str]:\\n    \\\"\\\"\\\"Get the mixed precision setting for Accelerate when using FP8.\\n\\n    Args:\\n        training_args: Training arguments containing FP8 configuration\\n\\n    Returns:\\n        \\\"fp8\\\" if FP8 is enabled, None otherwise\\n    \\\"\\\"\\\"\\n    return \\\"fp8\\\" if training_args.fp8 else None\\n\\n\\ndef configure_fp8_environment(training_args: \\\"TrainingArguments\\\") -> None:\\n    \\\"\\\"\\\"Configure FP8 environment for HuggingFace Accelerate.\\n\\n    FP8 training is handled entirely through HuggingFace Accelerate, regardless of whether\\n    DeepSpeed or FSDP is used for distributed training. This function sets up the environment\\n    variables and validates the FP8 configuration.\\n\\n    Args:\\n        training_args: Training arguments containing FP8 configuration\\n    \\\"\\\"\\\"\\n    if not training_args.fp8:\\n        return\\n\\n    # Set mixed precision to fp8 for HuggingFace Accelerate\\n    os.environ[\\\"ACCELERATE_MIXED_PRECISION\\\"] = \\\"fp8\\\"\\n    logger.info_rank0(\\\"Set ACCELERATE_MIXED_PRECISION=fp8\\\")\\n\\n    # Configure FP8 backend and options\\n    backend = getattr(training_args, \\\"fp8_backend\\\", \\\"auto\\\")\\n    if backend != \\\"auto\\\":\\n        os.environ[\\\"FP8_BACKEND\\\"] = backend\\n        logger.info_rank0(f\\\"Set FP8_BACKEND={backend}\\\")\\n\\n    # Create and validate FP8 recipe kwargs (for logging/debugging)\\n    fp8_kwargs = create_fp8_kwargs(training_args)\\n    logger.info_rank0(f\\\"FP8 AORecipeKwargs created: {len(fp8_kwargs)} items\\\")\\n\\n    # Enable FSDP float8 all-gather optimization if requested\\n    if hasattr(training_args, \\\"fp8_enable_fsdp_float8_all_gather\\\") and training_args.fp8_enable_fsdp_float8_all_gather:\\n        os.environ[\\\"FP8_ENABLE_FSDP_FLOAT8_ALL_GATHER\\\"] = \\\"true\\\"\\n        logger.info_rank0(\\\"Set FP8_ENABLE_FSDP_FLOAT8_ALL_GATHER=true\\\")\\n\\n    logger.info_rank0(\\\"FP8 environment configured - all FP8 training handled by HuggingFace Accelerate\\\")\\n\\n\\ndef verify_fp8_status(accelerator, training_args: \\\"TrainingArguments\\\") -> None:\\n    \\\"\\\"\\\"Verify that FP8 training is actually working after model preparation.\\n\\n    Args:\\n        accelerator: The HuggingFace Accelerator instance\\n        training_args: Training arguments containing FP8 configuration\\n    \\\"\\\"\\\"\\n    if not training_args.fp8:\\n        return\\n\\n    # Check Accelerate's FP8 status\\n    fp8_enabled = getattr(accelerator, \\\"fp8_enabled\\\", False)\\n    fp8_backend_type = getattr(accelerator, \\\"fp8_backend\\\", \\\"UNKNOWN\\\")\\n\\n    backend = getattr(training_args, \\\"fp8_backend\\\", \\\"auto\\\")\\n    if backend == \\\"torchao\\\" or backend == \\\"auto\\\":\\n        logger.info_rank0(\\n            \\\"FP8 training enabled with TorchAO backend. For optimal performance, \\\"\\n            \\\"ensure model layer dimensions are mostly divisible by 16. \\\"\\n            \\\"If you encounter issues, try fp8_backend='te' with Transformer Engine.\\\"\\n        )\\n    else:\\n        logger.info_rank0(f\\\"FP8 training enabled with {backend} backend.\\\")\\n\\n    logger.info_rank0(f\\\"Accelerate FP8 status - enabled: {fp8_enabled}, backend: {fp8_backend_type}\\\")\\n\\n    if not fp8_enabled:\\n        logger.info_rank0(\\\"WARNING: FP8 was requested but Accelerate shows fp8_enabled=False. FP8 may not be working.\\\")\\n\\n\\ndef patch_accelerator_for_fp8() -> None:\\n    \\\"\\\"\\\"Patch Accelerator to inject FP8 recipe kwargs.\\n\\n    This is needed because HuggingFace Trainer doesn't pass kwargs_handlers to Accelerator.\\n    We monkey-patch Accelerator.__init__ to inject the FP8 recipe and force mixed_precision='fp8'.\\n    \\\"\\\"\\\"\\n    import transformer_engine.pytorch as te\\n    from accelerate import Accelerator\\n\\n    # Guard against multiple patches\\n    if getattr(Accelerator, \\\"_te_fp8_patched\\\", False):\\n        return\\n\\n    # Stub for Accelerate 1.12+ compatibility (te.fp8.check_mxfp8_support doesn't exist yet)\\n    if not hasattr(te, \\\"fp8\\\"):\\n        te.fp8 = types.ModuleType(\\\"fp8\\\")\\n        te.fp8.check_mxfp8_support = lambda: (False, \\\"MXFP8 not supported\\\")\\n\\n    try:\\n        from accelerate.utils import TERecipeKwargs as FP8Recipe\\n\\n        use_te_recipe = True\\n    except ImportError:\\n        from accelerate.utils import FP8RecipeKwargs as FP8Recipe\\n\\n        use_te_recipe = False\\n\\n    original_init = Accelerator.__init__\\n\\n    def patched_init(self, *args, **kwargs):\\n        if \\\"kwargs_handlers\\\" not in kwargs or not kwargs[\\\"kwargs_handlers\\\"]:\\n            if use_te_recipe:\\n                kwargs[\\\"kwargs_handlers\\\"] = [\\n                    FP8Recipe(fp8_format=\\\"HYBRID\\\", amax_history_len=16, amax_compute_algo=\\\"max\\\")\\n                ]\\n            else:\\n                kwargs[\\\"kwargs_handlers\\\"] = [\\n                    FP8Recipe(backend=\\\"TE\\\", fp8_format=\\\"HYBRID\\\", amax_history_len=16, amax_compute_algo=\\\"max\\\")\\n                ]\\n            # Only force mixed_precision when we inject handlers\\n            kwargs[\\\"mixed_precision\\\"] = \\\"fp8\\\"\\n        return original_init(self, *args, **kwargs)\\n\\n    Accelerator.__init__ = patched_init\\n    Accelerator._te_fp8_patched = True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/hyper_parallel/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8b2510b78403d4f902dec8a76105b2b48662f03229db2ff6f3a5ff181f0e8b8b\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_pt, run_sft\\n\\n\\n__all__ = [\\\"run_pt\\\", \\\"run_sft\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/hyper_parallel/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"284c412f267e43b454de22176a6b4e7bcdf15a32941e9ba15a57e487a9e085e1\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"HyperParallel distributed trainer for LlamaFactory.\\\"\\\"\\\"\\n\\nimport logging\\nimport os\\nimport types\\nfrom contextlib import nullcontext\\nfrom functools import partial\\nfrom typing import Any, Optional\\n\\nimport torch\\nfrom hyper_parallel.integration.llamafactory import (\\n    HSDPModule,\\n    HyperParallelArguments,\\n    export_to_hf_format,\\n    fsdp2_prepare_model,\\n    hsdp_sync_stream,\\n    load_hsdp_model,\\n    load_hsdp_optimizer_and_scheduler,\\n    save_hsdp_checkpoint,\\n    wrap_optimizer_with_skip_dtensor_dispatch,\\n)\\nfrom hyper_parallel.integration.llamafactory import (\\n    clip_grad_norm_ as hp_clip_grad_norm_,\\n)\\nfrom hyper_parallel.integration.llamafactory.context_parallel import (\\n    cp_prepare_model,\\n    get_cp_rank,\\n    get_dp_rank,\\n    shard_inputs_for_cp,\\n)\\nfrom hyper_parallel.integration.llamafactory.expert_parallel import ep_prepare_model\\nfrom hyper_parallel.platform import get_platform\\nfrom torch import nn\\n\\nfrom ..sft.trainer import CustomSeq2SeqTrainer\\n\\n\\nlogger = logging.getLogger(__name__)\\n\\n\\nclass _CPBatchRepeatedBatchSampler(torch.utils.data.BatchSampler):\\n    \\\"\\\"\\\"Repeat logical batches so Accelerate shards CP peers onto the same samples.\\\"\\\"\\\"\\n\\n    def __init__(self, sampler, batch_size: int, drop_last: bool, repeat_factor: int, logical_group_size: int):\\n        super().__init__(sampler, batch_size, drop_last)\\n        self.repeat_factor = repeat_factor\\n        self.logical_group_size = logical_group_size\\n\\n    def __len__(self):\\n        logical_length = super().__len__()\\n        if not self.drop_last and logical_length > 0:\\n            logical_length = _ceil_div(logical_length, self.logical_group_size) * self.logical_group_size\\n        return logical_length * self.repeat_factor\\n\\n    def __iter__(self):\\n        initial_data = []\\n        logical_count = 0\\n        pad_cursor = 0\\n        max_initial_data = self.batch_size * self.logical_group_size\\n\\n        def collect_initial_data(batch):\\n            if len(initial_data) < max_initial_data:\\n                initial_data.extend(batch[: max_initial_data - len(initial_data)])\\n\\n        def get_padding_item():\\n            nonlocal pad_cursor\\n            item = initial_data[pad_cursor % len(initial_data)]\\n            pad_cursor += 1\\n            return item\\n\\n        def pad_batch(batch):\\n            batch = list(batch)\\n            if self.drop_last or len(batch) == self.batch_size:\\n                return batch\\n\\n            while len(batch) < self.batch_size:\\n                batch.append(get_padding_item())\\n            return batch\\n\\n        def make_padding_batch():\\n            return [get_padding_item() for _ in range(self.batch_size)]\\n\\n        def repeat_batch(batch):\\n            for _ in range(self.repeat_factor):\\n                yield list(batch)\\n\\n        for batch in super().__iter__():\\n            collect_initial_data(batch)\\n            batch = pad_batch(batch)\\n            logical_count += 1\\n            yield from repeat_batch(batch)\\n\\n        if self.drop_last or logical_count == 0:\\n            return\\n\\n        while logical_count % self.logical_group_size != 0:\\n            logical_count += 1\\n            yield from repeat_batch(make_padding_batch())\\n\\n\\nclass _CPDataLoaderLengthProxy:\\n    \\\"\\\"\\\"Keep baseline logical dataloader length while yielding CP-repeated batches.\\\"\\\"\\\"\\n\\n    def __init__(self, dataloader, logical_length: int):\\n        self._dataloader = dataloader\\n        self._logical_length = logical_length\\n\\n    def __iter__(self):\\n        return iter(self._dataloader)\\n\\n    def __len__(self):\\n        return self._logical_length\\n\\n    def __getattr__(self, name):\\n        return getattr(self._dataloader, name)\\n\\n\\ndef _ceil_div(numerator: int, denominator: int) -> int:\\n    return (numerator + denominator - 1) // denominator\\n\\n\\nclass HyperParallelTrainer(CustomSeq2SeqTrainer):\\n    \\\"\\\"\\\"Trainer that replaces Accelerate FSDP2 with HyperParallel fully_shard.\\n\\n    Inherits CustomSeq2SeqTrainer for training algorithm logic (loss, metrics,\\n    prediction, sampler, etc.) and only overrides HSDP-specific behavior.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        hp_args: HyperParallelArguments,\\n        finetuning_args=None,\\n        processor=None,\\n        ref_model: Optional[nn.Module] = None,\\n        **kwargs,\\n    ):\\n        self._hp_args = hp_args\\n\\n        # Let CustomSeq2SeqTrainer handle everything except ref_model \u2014\\n        # Custom would prepare it with accelerate's fsdp2_prepare_model,\\n        # but we need HP's version instead.\\n        super().__init__(\\n            finetuning_args=finetuning_args,\\n            processor=processor,\\n            ref_model=None,\\n            **kwargs,\\n        )\\n\\n        if not getattr(self.accelerator, \\\"is_fsdp2\\\", False):\\n            raise ValueError(\\\"HyperParallel trainer requires Accelerate FSDP2 mode to be enabled.\\\")\\n\\n        self._cp_size = hp_args.cp_size\\n        self._ep_size = hp_args.ep_size\\n        self._cp_rank = get_cp_rank(hp_args) if self._cp_size > 1 else 0\\n        self._dp_rank = get_dp_rank(hp_args) if self._cp_size > 1 else get_platform().get_rank()\\n\\n        # Prepare ref_model with the same CP + EP + HSDP path as the train model.\\n        self.ref_model = ref_model\\n        if self.ref_model is not None:\\n            self.ref_model = self._prepare_model_for_hyper_parallel(self.ref_model)\\n\\n        self._orig_accelerator_clip_grad_norm = self.accelerator.clip_grad_norm_\\n        self._orig_fsdp2_prepare_model = None\\n        self._accelerator_patches_active = False\\n\\n    def _prepare_model_for_hyper_parallel(self, model: nn.Module) -> nn.Module:\\n        \\\"\\\"\\\"Apply CP/EP preparation before delegating to HyperParallel FSDP2.\\\"\\\"\\\"\\n        if self._cp_size > 1:\\n            model = cp_prepare_model(model, self.accelerator, self._hp_args)\\n        if self._ep_size > 1:\\n            model = ep_prepare_model(model, self.accelerator, self._hp_args)\\n        return fsdp2_prepare_model(self.accelerator, model, self._hp_args)\\n\\n    def _activate_accelerator_patches(self) -> None:\\n        \\\"\\\"\\\"Patch Accelerate to use HyperParallel fsdp2_prepare_model and clip_grad_norm_.\\\"\\\"\\\"\\n        if self._accelerator_patches_active:\\n            return\\n\\n        import accelerate.accelerator as acc_module  # pylint: disable=C0415\\n\\n        self._orig_fsdp2_prepare_model = acc_module.fsdp2_prepare_model\\n\\n        def _hp_fsdp2_prepare_model(accelerator, model):\\n            return self._prepare_model_for_hyper_parallel(model)\\n\\n        acc_module.fsdp2_prepare_model = _hp_fsdp2_prepare_model\\n\\n        def _hp_clip_grad_norm(accelerator, parameters, max_norm, norm_type=2):\\n            if getattr(accelerator, \\\"is_fsdp2\\\", False):\\n                accelerator.unscale_gradients()\\n                parameter_list = list(parameters)\\n                parameter_ids = {id(param) for param in parameter_list}\\n                for model in accelerator._models:  # pylint: disable=protected-access\\n                    if not isinstance(model, HSDPModule):\\n                        continue\\n                    model_param_ids = {id(param) for param in model.parameters()}\\n                    if parameter_ids and parameter_ids.issubset(model_param_ids):\\n                        return hp_clip_grad_norm_(parameter_list, max_norm, norm_type=norm_type)\\n            return self._orig_accelerator_clip_grad_norm(parameters, max_norm, norm_type=norm_type)\\n\\n        self.accelerator.clip_grad_norm_ = types.MethodType(_hp_clip_grad_norm, self.accelerator)\\n        self._accelerator_patches_active = True\\n\\n    def _restore_accelerator_patches(self) -> None:\\n        \\\"\\\"\\\"Restore original Accelerate methods.\\\"\\\"\\\"\\n        if not self._accelerator_patches_active:\\n            return\\n\\n        import accelerate.accelerator as acc_module  # pylint: disable=C0415\\n\\n        if self._orig_fsdp2_prepare_model is not None:\\n            acc_module.fsdp2_prepare_model = self._orig_fsdp2_prepare_model\\n        self.accelerator.clip_grad_norm_ = self._orig_accelerator_clip_grad_norm\\n        self._accelerator_patches_active = False\\n\\n    def _wrap_model(self, model: nn.Module, training: bool = True, dataloader=None) -> nn.Module:\\n        \\\"\\\"\\\"Let Accelerate own FSDP2/HSDP wrapping so optimizer remapping stays correct.\\\"\\\"\\\"\\n        del dataloader\\n        if isinstance(model, HSDPModule):\\n            return model\\n        if training and getattr(self.accelerator, \\\"is_fsdp2\\\", False):\\n            return model\\n        return super()._wrap_model(model, training=training)\\n\\n    def _get_train_sampler(self, train_dataset=None):\\n        \\\"\\\"\\\"Match the no-CP baseline sampler semantics before CP repeats whole logical batches.\\\"\\\"\\\"\\n        if train_dataset is None:\\n            train_dataset = self.train_dataset\\n        if getattr(self.finetuning_args, \\\"disable_shuffling\\\", False):\\n            return torch.utils.data.SequentialSampler(train_dataset)\\n        return super()._get_train_sampler(train_dataset)\\n\\n    def _build_cp_batch_sampler(self, dataset, shuffle: bool, batch_size: int, drop_last: bool):\\n        \\\"\\\"\\\"Repeat complete logical batches so CP groups consume the same baseline batch.\\\"\\\"\\\"\\n        sampler = self._get_train_sampler(dataset) if shuffle else torch.utils.data.SequentialSampler(dataset)\\n        return _CPBatchRepeatedBatchSampler(\\n            sampler,\\n            batch_size=batch_size,\\n            drop_last=drop_last,\\n            repeat_factor=self._cp_size,\\n            logical_group_size=max(1, get_platform().get_world_size() // self._cp_size),\\n        )\\n\\n    def _get_cp_dataloader(self, dataset, batch_size: int, shuffle: bool):\\n        \\\"\\\"\\\"Create a train dataloader whose logical batches are shared within each CP group.\\\"\\\"\\\"\\n        if isinstance(dataset, torch.utils.data.IterableDataset):\\n            raise NotImplementedError(\\n                \\\"HyperParallel CP training requires a map-style dataset because iterable datasets cannot \\\"\\n                \\\"repeat logical batches across CP ranks.\\\"\\n            )\\n\\n        try:\\n            import datasets  # pylint: disable=C0415\\n        except ImportError:  # pragma: no cover\\n            datasets = None\\n\\n        if datasets is not None and isinstance(dataset, datasets.Dataset):\\n            dataset = self._remove_unused_columns(dataset, description=\\\"Training\\\")\\n            data_collator = self.data_collator\\n        else:\\n            data_collator = self._get_collator_with_removed_columns(self.data_collator, description=\\\"Training\\\")\\n\\n        batch_sampler = self._build_cp_batch_sampler(\\n            dataset,\\n            shuffle=shuffle,\\n            batch_size=batch_size,\\n            drop_last=self.args.dataloader_drop_last,\\n        )\\n        logical_batches = len(batch_sampler) // self._cp_size\\n        dp_size = max(1, get_platform().get_world_size() // self._cp_size)\\n        logical_length = (\\n            logical_batches // dp_size if self.args.dataloader_drop_last else _ceil_div(logical_batches, dp_size)\\n        )\\n\\n        dataloader_params = {\\n            \\\"batch_sampler\\\": batch_sampler,\\n            \\\"collate_fn\\\": data_collator,\\n            \\\"num_workers\\\": self.args.dataloader_num_workers,\\n            \\\"pin_memory\\\": self.args.dataloader_pin_memory,\\n            \\\"persistent_workers\\\": self.args.dataloader_persistent_workers\\n            if self.args.dataloader_num_workers > 0\\n            else False,\\n        }\\n        if self.args.dataloader_num_workers > 0:\\n            dataloader_params[\\\"prefetch_factor\\\"] = self.args.dataloader_prefetch_factor\\n\\n        from transformers.trainer import seed_worker  # pylint: disable=C0415\\n\\n        dataloader_params[\\\"worker_init_fn\\\"] = partial(\\n            seed_worker,\\n            num_workers=self.args.dataloader_num_workers,\\n            rank=self.args.process_index,\\n        )\\n\\n        dataloader = self.accelerator.prepare(torch.utils.data.DataLoader(dataset, **dataloader_params))\\n        return _CPDataLoaderLengthProxy(dataloader, logical_length)\\n\\n    def get_train_dataloader(self):\\n        \\\"\\\"\\\"Keep the no-CP logical batch stream, then repeat each whole batch across CP peers.\\\"\\\"\\\"\\n        if self.train_dataset is None:\\n            raise ValueError(\\\"Trainer: training requires a train_dataset.\\\")\\n        if self._cp_size <= 1:\\n            return super().get_train_dataloader()\\n\\n        shuffle = not getattr(self.finetuning_args, \\\"disable_shuffling\\\", False)\\n        return self._get_cp_dataloader(\\n            dataset=self.train_dataset,\\n            batch_size=self._train_batch_size,\\n            shuffle=shuffle,\\n        )\\n\\n    def _move_model_to_device(self, model: nn.Module, device: Optional[torch.device] = None):\\n        \\\"\\\"\\\"Skip redundant device moves for HSDP-wrapped models.\\\"\\\"\\\"\\n        if isinstance(model, HSDPModule):\\n            return model\\n        if device is None:\\n            return model\\n        return model.to(device)\\n\\n    def train(self, *args, **kwargs):\\n        \\\"\\\"\\\"Activate HP patches during training and restore afterwards.\\\"\\\"\\\"\\n        self._activate_accelerator_patches()\\n        try:\\n            return super().train(*args, **kwargs)\\n        finally:\\n            self._restore_accelerator_patches()\\n\\n    def training_step(\\n        self,\\n        model: nn.Module,\\n        inputs: dict[str, Any],\\n        num_items_in_batch: Optional[int] = None,\\n    ) -> torch.Tensor:\\n        \\\"\\\"\\\"Standard training step with HSDP sync plus optional CP input sharding.\\\"\\\"\\\"\\n        model.train()\\n        inputs = self._prepare_inputs(inputs)\\n\\n        if self._cp_size > 1:\\n            inputs = shard_inputs_for_cp(inputs, self._cp_rank, self._cp_size)\\n\\n        sync_gradients = getattr(self.accelerator, \\\"sync_gradients\\\", True)\\n        if isinstance(model, HSDPModule):\\n            model.set_is_last_backward(sync_gradients)\\n            model.set_requires_gradient_sync(sync_gradients)\\n\\n        compute_loss_context_manager = getattr(self, \\\"compute_loss_context_manager\\\", nullcontext)\\n        with compute_loss_context_manager():\\n            loss = self.compute_loss(model, inputs, num_items_in_batch=num_items_in_batch)\\n\\n        if self.args.n_gpu > 1:\\n            loss = loss.mean()\\n\\n        if not getattr(self, \\\"model_accepts_loss_kwargs\\\", False) and getattr(self, \\\"compute_loss_func\\\", None) is None:\\n            accumulation_steps = getattr(\\n                self,\\n                \\\"current_gradient_accumulation_steps\\\",\\n                self.args.gradient_accumulation_steps,\\n            )\\n            loss = loss / accumulation_steps\\n\\n        self.accelerator.backward(loss)\\n\\n        if isinstance(model, HSDPModule) and sync_gradients:\\n            hsdp_sync_stream()\\n\\n        return loss.detach()\\n\\n    def create_optimizer(self):\\n        \\\"\\\"\\\"Create optimizer and wrap step with SkipDTensorDispatch.\\\"\\\"\\\"\\n        optimizer = super().create_optimizer()\\n        wrap_optimizer_with_skip_dtensor_dispatch(optimizer)\\n        return optimizer\\n\\n    def _save_optimizer_and_scheduler(self, output_dir: str) -> None:\\n        \\\"\\\"\\\"Save model/optimizer shards per-rank and scheduler.\\\"\\\"\\\"\\n        save_hsdp_checkpoint(\\n            model=self.model,\\n            optimizer=self.optimizer,\\n            lr_scheduler=self.lr_scheduler,\\n            output_dir=output_dir,\\n            should_save_scheduler=self.args.should_save and self.lr_scheduler is not None,\\n        )\\n\\n    def _load_from_checkpoint(self, resume_from_checkpoint: str, model: Optional[nn.Module] = None) -> None:\\n        \\\"\\\"\\\"Load model from HSDP sharded checkpoint.\\\"\\\"\\\"\\n        target = model if model is not None else self.model\\n        loaded = load_hsdp_model(target, resume_from_checkpoint)\\n        if not loaded:\\n            return super()._load_from_checkpoint(resume_from_checkpoint, model=model)\\n        self._pending_hsdp_checkpoint = resume_from_checkpoint\\n        return None\\n\\n    def _load_optimizer_and_scheduler(self, checkpoint: Optional[str] = None) -> None:\\n        \\\"\\\"\\\"Load optimizer/scheduler from per-rank checkpoint files.\\\"\\\"\\\"\\n        ckpt_dir = getattr(self, \\\"_pending_hsdp_checkpoint\\\", None) or checkpoint\\n        if ckpt_dir is None:\\n            return\\n        load_hsdp_optimizer_and_scheduler(self.optimizer, self.lr_scheduler, ckpt_dir)\\n\\n    def save_model(self, output_dir: Optional[str] = None, _internal_call: bool = False):\\n        \\\"\\\"\\\"Save model weights in HuggingFace-compatible format.\\\"\\\"\\\"\\n        save_dir = output_dir or self.args.output_dir\\n        os.makedirs(save_dir, exist_ok=True)\\n        export_to_hf_format(self.model, getattr(self, \\\"processing_class\\\", None), save_dir)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/hyper_parallel/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"907938f27f56dad4c5110c0ad29273c98a9b27cd21b9e6b48744fb1fe3f507b5\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport math\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom transformers import DataCollatorForLanguageModeling\\n\\nfrom ...data import SFTDataCollatorWith4DAttentionMask, get_dataset, get_template_and_fix_tokenizer\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ...extr";
